@Composable
fun OdysseyApp(
    onThemeChanged: (Boolean) -> Unit = {},
    onSplashVisibleChanged: (Boolean) -> Unit = {},
    pendingTripId: String? = null,
    pendingPasswordReset: Boolean = false,
    onPendingDeepLinkHandled: () -> Unit = {},
) {
    val navController = rememberNavController()
    val currentBackStackEntry by navController.currentBackStackEntryAsState()
    val currentRoute = currentBackStackEntry?.destination?.route
    var darkTheme by remember { mutableStateOf(false) }
    var language by remember { mutableStateOf("RU") }
    var languageSelectedBeforeAuth by remember { mutableStateOf<String?>(null) }
    var authReady by remember { mutableStateOf(false) }
    var hasSession by remember { mutableStateOf(false) }
    var authRestoreError by remember { mutableStateOf(false) }
    var authRestoreAttempt by remember { mutableStateOf(0) }
    var sessionRestoreVersion by remember { mutableStateOf(0) }
    var accountProfile by remember { mutableStateOf<AccountProfile?>(null) }
    var rememberCredentials by remember { mutableStateOf(false) }
    var rememberedAccounts by remember { mutableStateOf<List<RememberedAccount>>(emptyList()) }
    val lifecycleOwner = LocalLifecycleOwner.current
    val authScope = rememberCoroutineScope()
    val deviceLocation = rememberDeviceLocation(enabled = authReady && hasSession)

    LaunchedEffect(darkTheme, authReady) {
        if (authReady) {
            onSplashVisibleChanged(false)
            onThemeChanged(darkTheme)
        } else {
            onSplashVisibleChanged(true)
        }
    }

    LaunchedEffect(authRestoreAttempt) {
        authReady = false
        authRestoreError = false
        accountProfile = null
        var result = AuthRestoreResult.FAILED
        for (attempt in 0 until 3) {
            result = SupabaseProvider.restorePersistentSession()
            if (result != AuthRestoreResult.FAILED) break
            if (attempt < 2) delay(250)
        }
        when (result) {
            AuthRestoreResult.RESTORED -> {
                hasSession = true
                rememberedAccounts = emptyList()
            }
            AuthRestoreResult.NO_SESSION -> {
                hasSession = false
                rememberedAccounts = SupabaseProvider.loadRememberedAccounts()
            }
            AuthRestoreResult.FAILED -> {
                hasSession = false
                authRestoreError = true
            }
        }
        authReady = true
    }

    LaunchedEffect(authReady, hasSession, authRestoreError) {
        if (!authReady || authRestoreError) return@LaunchedEffect
        if (!hasSession) {
            accountProfile = null
            rememberedAccounts = SupabaseProvider.loadRememberedAccounts()
        } else {
            rememberedAccounts = emptyList()
            val profile = runCatching {
                AccountRepository(SupabaseProvider.clientForCurrentAuthFlow()).loadProfile()
            }.getOrNull()
            accountProfile = profile
            profile?.let {
                darkTheme = it.darkTheme
                val languageChosenBeforeAuth = languageSelectedBeforeAuth
                if (languageChosenBeforeAuth != null) {
                    language = languageChosenBeforeAuth
                    if (normalizeLanguage(it.language) != languageChosenBeforeAuth) {
                        runCatching {
                            AccountRepository(SupabaseProvider.clientForCurrentAuthFlow())
                                .updateAppearance(languageChosenBeforeAuth, it.darkTheme)
                        }
                    }
                    languageSelectedBeforeAuth = null
                } else {
                    language = normalizeLanguage(it.language)
                }
            }
        }
    }

    DisposableEffect(lifecycleOwner, authReady, authRestoreError) {
        if (!authReady || authRestoreError) {
            onDispose { }
        } else {
            val observer = LifecycleEventObserver { _, event ->
                if (event == Lifecycle.Event.ON_RESUME) {
                    authScope.launch {
                        // Re-read the persisted auth session after returning
                        // from background/process recreation. A failed restore
                        // must not turn an explicit logout into a login.
                        val restoreResult = SupabaseProvider.restorePersistentSession()
                        if (restoreResult == AuthRestoreResult.RESTORED) {
                            hasSession = true
                            sessionRestoreVersion += 1
                        }
                    }
                }
            }
            lifecycleOwner.lifecycle.addObserver(observer)
            onDispose { lifecycleOwner.lifecycle.removeObserver(observer) }
        }
    }

    fun handleLanguageChange(value: String) {
        val normalized = normalizeLanguage(value)
        language = normalized
        if (!hasSession) languageSelectedBeforeAuth = normalized
    }

    LaunchedEffect(authReady, hasSession, currentRoute, authRestoreError) {
        if (!authReady || authRestoreError || currentRoute == null) return@LaunchedEffect
        if (hasSession && currentRoute == "foundation") {
            navController.navigate("trips") { popUpTo("foundation") { inclusive = true } }
        } else if (!hasSession && currentRoute != "foundation") {
            navController.navigate("foundation") { popUpTo(0) { inclusive = true } }
        }
    }

    LaunchedEffect(authReady, authRestoreError) {
        if (!authReady || authRestoreError) return@LaunchedEffect
        val authClients = SupabaseProvider.authClients()
        authClients.forEach { client ->
            launch {
                client.auth.sessionStatus.collect { status ->
                    val isActiveClient = SupabaseProvider.clientForCurrentAuthFlow() === client
                    if (isActiveClient && status is SessionStatus.Authenticated) {
                        hasSession = true
                    }
                    // The auth library can briefly publish NotAuthenticated
                    // while Android pauses/resumes its refresh job. Do not
                    // turn that transient state into a navigation logout;
                    // explicit UI logout handlers are the source of truth.
                }
            }
        }
    }

    val currentTripId = currentBackStackEntry?.arguments?.getString("tripId")

    LaunchedEffect(authReady, hasSession, currentRoute, currentTripId, pendingTripId, pendingPasswordReset) {
        if (!authReady || !hasSession || currentRoute == null) return@LaunchedEffect
        when {
            pendingPasswordReset && currentRoute != "reset-password" -> {
                navController.navigate("reset-password")
                onPendingDeepLinkHandled()
            }
            !pendingTripId.isNullOrBlank() -> {
                if (pendingTripId == currentTripId) {
                    onPendingDeepLinkHandled()
                } else {
                    navController.navigate("trip/$pendingTripId")
                    onPendingDeepLinkHandled()
                }
            }
        }
    }

    CompositionLocalProvider(
        LocalDarkTheme provides darkTheme,
        LocalLanguage provides language,
        LocalDeviceLocation provides deviceLocation,
    ) {
    MaterialTheme(colorScheme = if (darkTheme) OdysseyDarkColors else OdysseyLightColors) {
        Surface(color = if (darkTheme) OdysseyDarkBackground else OdysseyBackground) {
            if (!authReady) {
                RamingoSplash()
            } else if (authRestoreError) {
                RamingoSplash(
                    message = localized(
                        "Не удалось восстановить вход. Проверьте соединение и попробуйте ещё раз.",
                        "Could not restore your session. Check your connection and try again.",
                        "No se pudo restaurar la sesión. Compruebe la conexión e inténtelo de nuevo.",
                        "Die Sitzung konnte nicht wiederhergestellt werden. Prüfen Sie die Verbindung und versuchen Sie es erneut.",
                    ),
                    onRetry = {
                        authRestoreAttempt += 1
                    },
                )
            } else NavHost(navController = navController, startDestination = if (hasSession) "trips" else "foundation") {
                composable("foundation") {
                    AuthScreen(
                        rememberCredentials = rememberCredentials,
                        rememberedAccounts = rememberedAccounts,
                        onRememberedAccountSelected = { account ->
                            SupabaseProvider.activateRememberedAccount(account.id)
                        },
                        onRememberedAccountRemoved = { account ->
                            SupabaseProvider.removeRememberedAccount(account.id)
                            rememberedAccounts = SupabaseProvider.loadRememberedAccounts()
                        },
                        onRememberCredentialsChange = { rememberCredentials = it },
                        onLanguageChange = ::handleLanguageChange,
                        onAuthenticated = {
                            rememberedAccounts = emptyList()
                            accountProfile = null
                            hasSession = true
                            navController.navigate("trips")
                        },
                    )
                }
                composable("trips") {
                    MyTripsScreen(
                        onTripClick = { navController.navigate("trip/$it") },
                        onNewTrip = { navController.navigate("create-trip") },
                        onLogout = {
                            hasSession = false
                            navController.navigate("foundation") {
                                popUpTo(0) { inclusive = true }
                            }
                        },
                        darkTheme = darkTheme,
                        onThemeToggle = { darkTheme = !darkTheme },
                        language = language,
                        onLanguageChange = ::handleLanguageChange,
                        sessionRestoreVersion = sessionRestoreVersion,
                        accountProfile = accountProfile,
                    )
                }
                composable("settings") {
                    AccountSettingsScreen(
                        onBack = { navController.popBackStack() },
                        onLogout = {
                            hasSession = false
                            navController.navigate("foundation") {
                                popUpTo(0) { inclusive = true }
                            }
                        },
                        darkTheme = darkTheme,
                        onThemeToggle = { darkTheme = !darkTheme },
                        onThemeSet = { darkTheme = it },
                        language = language,
                        onLanguageChange = { language = normalizeLanguage(it) },
                    )
                }
                composable("create-trip") {
                    CreateTripScreen(
                        onBack = { navController.popBackStack() },
                        onCreated = { created ->
                            navController.navigate("trip/${created.id}") {
                                popUpTo("trips") { inclusive = false }
                            }
                        },
                        onAuthRequired = {
                            hasSession = false
                            navController.navigate("foundation") {
                                popUpTo(0) { inclusive = true }
                            }
                        },
                    )
                }
                composable("reset-password") {
                    ResetPasswordScreen(
                        onFinished = {
                            navController.navigate("trips") {
                                popUpTo("reset-password") { inclusive = true }
                            }
                        },
                        onCancel = { navController.popBackStack() },
                    )
                }
                composable("trip/{tripId}") { entry ->
                    TripOverviewScreen(
                        tripId = entry.arguments?.getString("tripId").orEmpty(),
                        onBack = { navController.popBackStack() },
                        onSettings = { navController.navigate("settings") },
                    )
                }
            }
        }
    }
    }
}

@Composable
private fun AuthScreen(
    rememberCredentials: Boolean,
    rememberedAccounts: List<RememberedAccount>,
    onRememberCredentialsChange: (Boolean) -> Unit,
    onRememberedAccountSelected: suspend (RememberedAccount) -> Boolean = { false },
    onRememberedAccountRemoved: suspend (RememberedAccount) -> Unit = {},
    onLanguageChange: (String) -> Unit,
    onAuthenticated: () -> Unit,
) {
    val darkTheme = LocalDarkTheme.current
    val context = LocalContext.current
    val language = LocalLanguage.current
    var isRegistration by remember { mutableStateOf(false) }
    var name by remember { mutableStateOf("") }
    var email by remember { mutableStateOf("") }
    var password by remember { mutableStateOf("") }
    var repeatPassword by remember { mutableStateOf("") }
    var isLoading by remember { mutableStateOf(false) }
    var message by remember { mutableStateOf<String?>(null) }
    var registrationNeedsRecoveryHint by remember { mutableStateOf(false) }
    var languagePickerOpen by remember { mutableStateOf(false) }
    // Legacy saved accounts are shown only long enough to migrate them to the
    // single persistent auth session used by the current app. New logins do
    // not create account-picker entries.
    var accountPickerOpen by remember(rememberedAccounts) {
        mutableStateOf(rememberedAccounts.isNotEmpty())
    }
    val scope = rememberCoroutineScope()
    val languageCode = normalizeLanguage(language)
    val languageOptions = listOf(
        Triple("RU", "\uD83C\uDDF7\uD83C\uDDFA", "\u0420\u0443\u0441\u0441\u043A\u0438\u0439"),
        Triple("EN", "\uD83C\uDDEC\uD83C\uDDE7", "English"),
        Triple("ES", "\uD83C\uDDEA\uD83C\uDDF8", "Espa\u00F1ol"),
        Triple("DE", "\uD83C\uDDE9\uD83C\uDDEA", "Deutsch"),
    )
    fun messageText(ru: String, en: String, es: String, de: String) = localized(language, ru, en, es, de)

    LaunchedEffect(Unit) {
        SupabaseProvider.loadRememberedCredentials()?.let { credentials ->
            if (email.isBlank() && password.isBlank()) {
                email = credentials.email
                password = credentials.password
                onRememberCredentialsChange(true)
            }
        }
    }

    fun setRememberCredentials(checked: Boolean) {
        onRememberCredentialsChange(checked)
        if (!checked) {
            scope.launch { SupabaseProvider.clearRememberedCredentials() }
        }
    }

    fun requestPasswordRecovery() {
        if (email.isBlank()) {
            message = messageText("Введите e-mail для восстановления", "Enter your email to reset the password", "Introduzca su e-mail para restablecer la contraseña", "Geben Sie Ihre E-Mail zum Zurücksetzen des Passworts ein")
            registrationNeedsRecoveryHint = false
            return
        }
        scope.launch {
            isLoading = true
            message = null
            registrationNeedsRecoveryHint = false
            runCatching {
                SupabaseProvider.clientForCurrentAuthFlow().auth.resetPasswordForEmail(email.trim(), redirectUrl = "https://ramingo.online/mobile/reset")
            }.onSuccess {
                message = messageText("Письмо для восстановления отправлено", "Password reset email sent", "Correo de restablecimiento enviado", "E-Mail zum Zurücksetzen gesendet")
            }.onFailure {
                message = localizedFailure(language, it, messageText("Не удалось отправить письмо", "Could not send reset email", "No se pudo enviar el correo", "E-Mail konnte nicht gesendet werden"))
            }
            isLoading = false
        }
    }

    fun submit() {
        if (email.isBlank() || password.isBlank() || (isRegistration && name.isBlank())) {
            message = messageText("Заполните обязательные поля", "Complete the required fields", "Complete los campos obligatorios", "Füllen Sie die Pflichtfelder aus")
            return
        }
        if (isRegistration && password != repeatPassword) {
            message = messageText("Пароли не совпадают", "Passwords do not match", "Las contraseñas no coinciden", "Passwörter stimmen nicht überein")
            return
        }
        if (isRegistration && password.length < 6) {
            message = messageText("Пароль должен содержать минимум 6 символов", "Password must contain at least 6 characters", "La contraseña debe tener al menos 6 caracteres", "Das Passwort muss mindestens 6 Zeichen enthalten")
            return
        }
        scope.launch {
            isLoading = true
            message = null
            runCatching {
                SupabaseProvider.prepareAuthentication()
                val auth = SupabaseProvider.clientForCurrentAuthFlow().auth
                if (isRegistration) {
                    auth.signUpWith(Email, "https://ramingo.online/mobile/auth") {
                        this.email = email.trim()
                        this.password = password
                        data = buildJsonObject { put("full_name", name.trim()) }
                    }
                    val authenticatedImmediately = auth.currentSessionOrNull() != null
                    if (authenticatedImmediately) {
                        SupabaseProvider.finalizeAuthentication()
                    }
                    SupabaseProvider.updateRememberedCredentials(email.trim(), password, rememberCredentials)
                    authenticatedImmediately
                } else {
                    auth.signInWith(Email) {
                        this.email = email.trim()
                        this.password = password
                    }
                    SupabaseProvider.finalizeAuthentication()
                    SupabaseProvider.updateRememberedCredentials(email.trim(), password, rememberCredentials)
                    true
                }
            }.onSuccess { authenticatedImmediately ->
                if (isRegistration && !authenticatedImmediately) {
                    message = messageText(
                        "Проверьте e-mail для подтверждения. Если адрес уже зарегистрирован, письмо не придёт.",
                        "Check your email to confirm. If this address is already registered, no message will arrive.",
                        "Revise su correo para confirmar. Si esta dirección ya está registrada, no recibirá ningún mensaje.",
                        "Prüfen Sie Ihre E-Mail zur Bestätigung. Wenn diese Adresse bereits registriert ist, kommt keine Nachricht.",
                    )
                    registrationNeedsRecoveryHint = true
                } else {
                    registrationNeedsRecoveryHint = false
                    onAuthenticated()
                }
            }.onFailure { error ->
                if (error is CancellationException) throw error
                registrationNeedsRecoveryHint = false
                message = when {
                    isRegistration && isAlreadyRegisteredAuthError(error) -> {
                        messageText("Этот e-mail уже зарегистрирован. Войдите в аккаунт.", "This e-mail is already registered. Sign in instead.", "Este e-mail ya está registrado. Inicie sesión.", "Diese E-Mail ist bereits registriert. Melden Sie sich stattdessen an.")
                    }
                    !isRegistration -> {
                        when (classifyAuthFailure(error)) {
                            is AuthFailure.InvalidCredentials -> messageText(
                                "Неверный e-mail или пароль",
                                "Incorrect email or password",
                                "E-mail o contraseña incorrectos",
                                "Falsche E-Mail oder falsches Passwort",
                            )
                            is AuthFailure.Network -> messageText(
                                "Не удалось подключиться. Проверьте интернет и повторите попытку.",
                                "Could not connect. Check your internet connection and try again.",
                                "No se pudo conectar. Compruebe su conexión a internet e inténtelo de nuevo.",
                                "Verbindung fehlgeschlagen. Prüfen Sie Ihre Internetverbindung und versuchen Sie es erneut.",
                            )
                            is AuthFailure.Unknown -> messageText(
                                "Не удалось войти. Повторите попытку.",
                                "Could not sign in. Please try again.",
                                "No se pudo iniciar sesión. Inténtelo de nuevo.",
                                "Anmeldung fehlgeschlagen. Bitte versuchen Sie es erneut.",
                            )
                        }
                    }
                    else -> messageText("Не удалось выполнить запрос", "Could not complete the request", "No se pudo completar la solicitud", "Anfrage konnte nicht ausgeführt werden")
                }
            }
            isLoading = false
        }
    }

    fun signInWithGoogle() {
        if (BuildConfig.GOOGLE_WEB_CLIENT_ID.isBlank()) {
            message = messageText("Google OAuth не настроен", "Google OAuth is not configured", "Google OAuth no está configurado", "Google OAuth ist nicht eingerichtet")
            return
        }
        scope.launch {
            isLoading = true
            message = null
            runCatching {
                SupabaseProvider.prepareAuthentication()
                val option = GetSignInWithGoogleOption.Builder(
                    BuildConfig.GOOGLE_WEB_CLIENT_ID,
                ).build()
                val request = GetCredentialRequest.Builder().addCredentialOption(option).build()
                val credential = CredentialManager.create(context).getCredential(context, request).credential
                val googleCredential = GoogleIdTokenCredential.createFrom(credential.data)
                SupabaseProvider.clientForCurrentAuthFlow().auth.signInWith(IDToken) {
                    idToken = googleCredential.idToken
                    provider = Google
                }
                SupabaseProvider.finalizeAuthentication()
            }.onSuccess { onAuthenticated() }.onFailure { error ->
                message = if (error is NoCredentialException) {
                    messageText("Аккаунт Google не выбран", "No Google account was selected", "No se seleccionó ninguna cuenta de Google", "Kein Google-Konto ausgewählt")
                } else {
                    messageText("Не удалось войти через Google", "Google sign-in failed", "No se pudo iniciar sesión con Google", "Google-Anmeldung fehlgeschlagen")
                }
            }
            isLoading = false
        }
    }

    Column(
        modifier = Modifier
            .fillMaxSize()
            .background(if (darkTheme) OdysseyDarkBackground else OdysseyBackground)
            .padding(WindowInsets.statusBars.asPaddingValues())
            .verticalScroll(rememberScrollState())
            .imePadding()
            .padding(start = 24.dp, top = 40.dp, end = 24.dp, bottom = 28.dp + WindowInsets.navigationBars.asPaddingValues().calculateBottomPadding()),
    ) {
        Box(modifier = Modifier.fillMaxWidth()) {
            Row(
                verticalAlignment = Alignment.CenterVertically,
                modifier = Modifier.padding(end = 84.dp),
            ) {
                Text(
                    text = "R",
                    color = primaryContentColor(),
                    fontFamily = Manrope,
                    fontWeight = FontWeight.W800,
                    fontSize = 19.sp,
                    modifier = Modifier
                        .background(
                            Brush.linearGradient(listOf(primaryColor(), Color(0xFF8E7BF5))),
                            RoundedCornerShape(12.dp),
                        )
                        .padding(horizontal = 12.dp, vertical = 7.dp),
                )
                Text(
                    text = "Ramingo",
                    color = contentTextColor(),
                    fontFamily = Manrope,
                    fontWeight = FontWeight.W800,
                    fontSize = 20.sp,
                    modifier = Modifier.padding(start = 11.dp),
                )
            }
            Box(modifier = Modifier.align(Alignment.TopEnd)) {
                Row(
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.spacedBy(4.dp),
                    modifier = Modifier
                        .clip(RoundedCornerShape(10.dp))
                        .background(tintedSurfaceColor())
                        .border(1.dp, contentBorderColor(), RoundedCornerShape(10.dp))
                        .clickable { languagePickerOpen = true }
                        .padding(horizontal = 8.dp, vertical = 6.dp),
                ) {
                    Icon(
                        imageVector = Icons.Outlined.Language,
                        contentDescription = localized("\u042f\u0437\u044b\u043a", "Language", "Idioma", "Sprache"),
                        tint = primaryColor(),
                        modifier = Modifier.size(16.dp),
                    )
                    Text(
                        text = languageCode,
                        color = contentTextColor(),
                        fontFamily = Manrope,
                        fontWeight = FontWeight.W800,
                        fontSize = 12.sp,
                    )
                    Icon(
                        imageVector = Icons.Outlined.KeyboardArrowDown,
                        contentDescription = null,
                        tint = secondaryTextColor(),
                        modifier = Modifier.size(16.dp),
                    )
                }
                DropdownMenu(
                    expanded = languagePickerOpen,
                    onDismissRequest = { languagePickerOpen = false },
                    modifier = Modifier.width(178.dp),
                    shape = RoundedCornerShape(14.dp),
                    containerColor = cardSurfaceColor(),
                    shadowElevation = 12.dp,
                ) {
                    languageOptions.forEach { (code, flag, label) ->
                        val selected = languageCode == code
                        DropdownMenuItem(
                            text = {
                                Row(
                                    verticalAlignment = Alignment.CenterVertically,
                                    horizontalArrangement = Arrangement.spacedBy(9.dp),
                                ) {
                                    Text(flag, fontSize = 17.sp)
                                    Text(
                                        text = label,
                                        color = if (selected) primaryColor() else contentTextColor(),
                                        fontFamily = Manrope,
                                        fontWeight = if (selected) FontWeight.W800 else FontWeight.W700,
                                        fontSize = 13.sp,
                                    )
                                }
                            },
                            onClick = {
                                languagePickerOpen = false
                                onLanguageChange(code)
                            },
                            trailingIcon = {
                                if (selected) {
                                    Icon(
                                        imageVector = Icons.Filled.Check,
                                        contentDescription = null,
                                        tint = primaryColor(),
                                        modifier = Modifier.size(17.dp),
                                    )
                                }
                            },
                        )
                    }
                }
            }
        }

        Spacer(Modifier.height(34.dp))
        Text(
            text = if (isRegistration) localized("Создать аккаунт", "Create account", "Crear cuenta", "Konto erstellen") else localized("С возвращением", "Welcome back", "Bienvenido de nuevo", "Willkommen zurück"),
            color = contentTextColor(),
            fontFamily = Manrope,
            fontWeight = FontWeight.W800,
            fontSize = 30.sp,
            lineHeight = 32.sp,
        )
        Text(
            text = if (isRegistration) localized("Пара шагов - и планируем поездку", "A few steps and you can plan your trip", "Unos pasos y podrá planificar su viaje", "Noch ein paar Schritte bis zur Reiseplanung") else localized("Войдите, чтобы продолжить планирование", "Sign in to continue planning", "Inicie sesión para continuar planificando", "Melden Sie sich an, um weiterzuplanen"),
            color = secondaryTextColor(),
            fontFamily = Manrope,
            fontWeight = FontWeight.W600,
            fontSize = 14.sp,
            modifier = Modifier.padding(top = 8.dp),
        )

        val showRememberedAccounts = !isRegistration && accountPickerOpen && rememberedAccounts.isNotEmpty()
        if (showRememberedAccounts) {
            RememberedAccountsPanel(
                accounts = rememberedAccounts,
                isLoading = isLoading,
                onSelect = { account ->
                    scope.launch {
                        isLoading = true
                        message = null
                        val activated = runCatching {
                            onRememberedAccountSelected(account)
                        }.getOrDefault(false)
                        if (activated) {
                            onAuthenticated()
                        } else {
                            onRememberedAccountRemoved(account)
                            message = messageText(
                                "Не удалось войти под этим аккаунтом. Войдите снова.",
                                "Could not use this account. Sign in again.",
                                "No se pudo usar esta cuenta. Inicie sesión de nuevo.",
                                "Dieses Konto konnte nicht verwendet werden. Melden Sie sich erneut an.",
                            )
                            if (rememberedAccounts.size <= 1) accountPickerOpen = false
                        }
                        isLoading = false
                    }
                },
                onRemove = { account ->
                    scope.launch {
                        onRememberedAccountRemoved(account)
                        if (rememberedAccounts.size <= 1) accountPickerOpen = false
                    }
                },
                onOtherAccount = {
                    accountPickerOpen = false
                    message = null
                },
            )
        } else {
            Spacer(Modifier.height(28.dp))
        if (isRegistration) {
            AuthField(localized("Имя", "Name", "Nombre", "Name"), localized("Как вас зовут", "What is your name", "Cómo se llama", "Wie heißen Sie"), name) { name = it }
            Spacer(Modifier.height(14.dp))
        }
        AuthField(localized("E-mail", "E-mail", "Correo electrónico", "E-Mail"), "you@example.com", email) { email = it }
        Spacer(Modifier.height(14.dp))
        AuthField(localized("Пароль", "Password", "Contraseña", "Passwort"), "••••••••", password, password = true) { password = it }
        if (isRegistration) {
            Spacer(Modifier.height(14.dp))
            AuthField(localized("Повторите пароль", "Repeat password", "Repita la contraseña", "Passwort wiederholen"), "••••••••", repeatPassword, password = true) { repeatPassword = it }
        } else {
            Text(
                text = localized("Забыли пароль?", "Forgot password?", "¿Olvidó su contraseña?", "Passwort vergessen?"),
                color = primaryColor(),
                fontFamily = Manrope,
                fontWeight = FontWeight.W800,
                fontSize = 13.sp,
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(top = 10.dp)
                    .clickable {
                        requestPasswordRecovery()
                    },
            )
        }
        Row(
            verticalAlignment = Alignment.CenterVertically,
            modifier = Modifier.padding(top = 14.dp).clickable { setRememberCredentials(!rememberCredentials) },
        ) {
            Box(
                contentAlignment = Alignment.Center,
                modifier = Modifier.size(20.dp).background(if (rememberCredentials) primaryColor() else Color.Transparent, RoundedCornerShape(6.dp)).drawBehind {
                    if (!rememberCredentials) drawRoundRect(Color(0xFFBDBCC6), style = Stroke(width = 1.dp.toPx()), cornerRadius = androidx.compose.ui.geometry.CornerRadius(6.dp.toPx()))
                },
            ) {
                if (rememberCredentials) Text("✓", color = primaryContentColor(), fontWeight = FontWeight.W800, fontSize = 13.sp)
            }
            Text(
                text = localized("Запомнить данные входа", "Remember login details", "Recordar datos de acceso", "Anmeldedaten speichern"),
                color = secondaryTextColor(),
                fontFamily = Manrope,
                fontWeight = FontWeight.W700,
                fontSize = 13.sp,
                modifier = Modifier.padding(start = 9.dp),
            )
        }

        Button(
            onClick = ::submit,
            enabled = !isLoading,
            colors = ButtonDefaults.buttonColors(containerColor = Color.Transparent, contentColor = primaryContentColor()),
            shape = RoundedCornerShape(15.dp),
            contentPadding = androidx.compose.foundation.layout.PaddingValues(),
            modifier = Modifier
                .fillMaxWidth()
                .padding(top = 18.dp)
                .height(56.dp)
                .background(
                    Brush.linearGradient(listOf(primaryColor(), Color(0xFF7D6CF0))),
                    RoundedCornerShape(15.dp),
                ),
        ) {
            Text(
                text = if (isLoading) localized("Подождите…", "Please wait…", "Espere…", "Bitte warten…") else if (isRegistration) localized("Создать аккаунт", "Create account", "Crear cuenta", "Konto erstellen") else localized("Войти", "Sign in", "Iniciar sesión", "Anmelden"),
                fontFamily = Manrope,
                fontWeight = FontWeight.W800,
                fontSize = 16.sp,
            )
        }
        if (message != null) {
            Text(
                text = message!!,
                color = if (message == "Вход выполнен" || message?.startsWith("Проверьте") == true || message?.startsWith("Check your email") == true || message?.startsWith("Revise su correo") == true || message?.startsWith("Prüfen Sie Ihre E-Mail") == true || message?.contains("отправлено", true) == true || message?.contains("sent", true) == true || message?.contains("enviado", true) == true || message?.contains("gesendet", true) == true) Color(0xFF22B07D) else Color(0xFFE0524B),
                fontFamily = Manrope,
                fontWeight = FontWeight.W700,
                fontSize = 13.sp,
                modifier = Modifier.padding(top = 10.dp),
            )
        }
        if (isRegistration && registrationNeedsRecoveryHint) {
            Text(
                text = localized(
                    "Если вы уже регистрировались, восстановите пароль:",
                    "If you have already registered, reset your password:",
                    "Si ya se registró, restablezca su contraseña:",
                    "Wenn Sie sich bereits registriert haben, setzen Sie Ihr Passwort zurück:",
                ),
                color = secondaryTextColor(),
                fontFamily = Manrope,
                fontWeight = FontWeight.W600,
                fontSize = 12.sp,
                lineHeight = 17.sp,
                modifier = Modifier.padding(top = 6.dp),
            )
            TextButton(
                onClick = ::requestPasswordRecovery,
                enabled = !isLoading,
                contentPadding = androidx.compose.foundation.layout.PaddingValues(horizontal = 0.dp, vertical = 2.dp),
            ) {
                Text(
                    text = localized("Восстановить пароль", "Reset password", "Restablecer contraseña", "Passwort zurücksetzen"),
                    color = primaryColor(),
                    fontFamily = Manrope,
                    fontWeight = FontWeight.W800,
                    fontSize = 13.sp,
                )
            }
        }

        Row(
            verticalAlignment = Alignment.CenterVertically,
            modifier = Modifier.padding(vertical = 22.dp),
        ) {
            Spacer(Modifier.weight(1f).height(1.dp).background(contentBorderColor()))
            Text(
                text = localized("или", "or", "o", "oder"),
                color = secondaryTextColor(),
                fontFamily = Manrope,
                fontWeight = FontWeight.W700,
                fontSize = 12.sp,
                modifier = Modifier.padding(horizontal = 12.dp),
            )
            Spacer(Modifier.weight(1f).height(1.dp).background(contentBorderColor()))
        }
        Button(
            onClick = ::signInWithGoogle,
            shape = RoundedCornerShape(15.dp),
            colors = ButtonDefaults.buttonColors(containerColor = cardSurfaceColor(), contentColor = contentTextColor()),
            modifier = Modifier.fillMaxWidth().height(53.dp),
        ) {
            Text("G", color = Color(0xFF4285F4), fontWeight = FontWeight.W800, fontSize = 18.sp)
            Text(
                text = localized("Продолжить с Google", "Continue with Google", "Continuar con Google", "Mit Google fortfahren"),
                fontFamily = Manrope,
                fontWeight = FontWeight.W800,
                fontSize = 15.sp,
                modifier = Modifier.padding(start = 10.dp),
            )
        }
        Row(
            horizontalArrangement = Arrangement.Center,
            modifier = Modifier.fillMaxWidth().padding(top = 26.dp),
        ) {
            Text(
                text = if (isRegistration) localized("Уже есть аккаунт?", "Already have an account?", "¿Ya tiene una cuenta?", "Bereits ein Konto?") else localized("Нет аккаунта?", "No account?", "¿No tiene cuenta?", "Noch kein Konto?"),
                color = secondaryTextColor(),
                fontFamily = Manrope,
                fontWeight = FontWeight.W600,
                fontSize = 14.sp,
            )
            Text(
                text = if (isRegistration) " " + localized("Войти", "Sign in", "Iniciar sesión", "Anmelden") else " " + localized("Зарегистрироваться", "Sign up", "Registrarse", "Registrieren"),
                color = primaryColor(),
                fontFamily = Manrope,
                fontWeight = FontWeight.W800,
                fontSize = 14.sp,
                modifier = Modifier.clickable {
                    isRegistration = !isRegistration
                    name = ""
                    password = ""
                    repeatPassword = ""
                    message = null
                    registrationNeedsRecoveryHint = false
                },
            )
        }
        }
    }
}

@Composable
private fun RememberedAccountsPanel(
    accounts: List<RememberedAccount>,
    isLoading: Boolean,
    onSelect: (RememberedAccount) -> Unit,
    onRemove: suspend (RememberedAccount) -> Unit,
    onOtherAccount: () -> Unit,
) {
    val scope = rememberCoroutineScope()
    var selectedId by remember(accounts) { mutableStateOf(accounts.firstOrNull()?.id) }
    var menuAccount by remember { mutableStateOf<RememberedAccount?>(null) }
    var removeAccount by remember { mutableStateOf<RememberedAccount?>(null) }
    val selectedAccount = accounts.firstOrNull { it.id == selectedId } ?: accounts.firstOrNull()

    Column(modifier = Modifier.padding(top = 27.dp)) {
        Text(
            text = localized("СОХРАНЁННЫЕ АККАУНТЫ", "SAVED ACCOUNTS", "CUENTAS GUARDADAS", "GESPEICHERTE KONTEN"),
            color = primaryColor(),
            fontFamily = Manrope,
            fontWeight = FontWeight.W800,
            fontSize = 11.sp,
            letterSpacing = 1.2.sp,
        )
        Text(
            text = localized(
                "Выберите аккаунт, под которым хотите продолжить.",
                "Choose the account you want to continue with.",
                "Elija la cuenta con la que desea continuar.",
                "Wählen Sie das Konto, mit dem Sie fortfahren möchten.",
            ),
            color = secondaryTextColor(),
            fontFamily = Manrope,
            fontWeight = FontWeight.W600,
            fontSize = 13.sp,
            lineHeight = 19.sp,
            modifier = Modifier.padding(top = 8.dp, bottom = 17.dp),
        )

        Column(verticalArrangement = Arrangement.spacedBy(11.dp)) {
            accounts.forEachIndexed { index, account ->
                val selected = selectedAccount?.id == account.id
                val cardShape = RoundedCornerShape(14.dp)
                Box(
                    modifier = Modifier
                        .fillMaxWidth()
                        .clip(cardShape)
                        .background(if (selected) tintedSurfaceColor() else cardSurfaceColor())
                        .border(
                            width = if (selected) 1.5.dp else 1.dp,
                            color = if (selected) primaryColor() else contentBorderColor(),
                            shape = cardShape,
                        )
                        .clickable {
                            selectedId = account.id
                        }
                        .padding(start = 13.dp, top = 13.dp, bottom = 13.dp, end = 42.dp),
                ) {
                    Row(verticalAlignment = Alignment.CenterVertically) {
                        val avatarColors = if (index % 2 == 0) {
                            listOf(Color(0xFFF6CDA5), Color(0xFFE88E77))
                        } else {
                            listOf(Color(0xFFACCBFF), Color(0xFF7384E9))
                        }
                        Text(
                            text = account.displayName.trim().take(1).uppercase().ifBlank { "R" },
                            color = Color.White,
                            fontFamily = Manrope,
                            fontWeight = FontWeight.W800,
                            fontSize = 17.sp,
                            textAlign = TextAlign.Center,
                            modifier = Modifier
                                .size(42.dp)
                                .background(Brush.linearGradient(avatarColors), RoundedCornerShape(12.dp))
                                .padding(top = 10.dp),
                        )
                        Column(
                            modifier = Modifier
                                .weight(1f)
                                .padding(start = 12.dp),
                        ) {
                            Text(
                                text = account.displayName,
                                color = contentTextColor(),
                                fontFamily = Manrope,
                                fontWeight = FontWeight.W800,
                                fontSize = 14.sp,
                                maxLines = 1,
                                overflow = TextOverflow.Ellipsis,
                            )
                            Text(
                                text = account.email,
                                color = secondaryTextColor(),
                                fontFamily = Manrope,
                                fontWeight = FontWeight.W600,
                                fontSize = 11.sp,
                                maxLines = 1,
                                overflow = TextOverflow.Ellipsis,
                                modifier = Modifier.padding(top = 3.dp),
                            )
                            Row(
                                verticalAlignment = Alignment.CenterVertically,
                                modifier = Modifier.padding(top = 5.dp),
                            ) {
                                Box(
                                    modifier = Modifier
                                        .size(6.dp)
                                        .background(Color(0xFF22B07D), CircleShape),
                                )
                                Text(
                                    text = localized(
                                        "Сохранён на этом устройстве",
                                        "Saved on this device",
                                        "Guardado en este dispositivo",
                                        "Auf diesem Gerät gespeichert",
                                    ),
                                    color = Color(0xFF22B07D),
                                    fontFamily = Manrope,
                                    fontWeight = FontWeight.W800,
                                    fontSize = 10.sp,
                                    modifier = Modifier.padding(start = 5.dp),
                                )
                            }
                        }
                        Box(
                            contentAlignment = Alignment.Center,
                            modifier = Modifier
                                .size(20.dp)
                                .background(if (selected) primaryColor() else Color.Transparent, RoundedCornerShape(6.dp))
                                .drawBehind {
                                    if (!selected) {
                                        drawRoundRect(
                                            Color(0xFFBDBCC6),
                                            style = Stroke(width = 1.dp.toPx()),
                                            cornerRadius = androidx.compose.ui.geometry.CornerRadius(6.dp.toPx()),
                                        )
                                    }
                                },
                        ) {
                            if (selected) {
                                Text("✓", color = primaryContentColor(), fontWeight = FontWeight.W800, fontSize = 13.sp)
                            }
                        }
                    }

                    IconButton(
                        onClick = { menuAccount = account },
                        modifier = Modifier
                            .align(Alignment.TopEnd)
                            .size(34.dp)
                            .padding(top = 2.dp, end = 2.dp),
                    ) {
                        Icon(
                            imageVector = Icons.Filled.MoreVert,
                            contentDescription = localized("Настройки аккаунта", "Account options", "Opciones de cuenta", "Kontenoptionen"),
                            tint = Color(0xFFB1B1BB),
                            modifier = Modifier.size(18.dp),
                        )
                    }
                    DropdownMenu(
                        expanded = menuAccount?.id == account.id,
                        onDismissRequest = { menuAccount = null },
                        shape = RoundedCornerShape(14.dp),
                        containerColor = cardSurfaceColor(),
                    ) {
                        DropdownMenuItem(
                            text = {
                                Text(
                                    text = localized("Удалить с устройства", "Remove from device", "Eliminar del dispositivo", "Vom Gerät entfernen"),
                                    color = contentTextColor(),
                                    fontFamily = Manrope,
                                    fontWeight = FontWeight.W700,
                                    fontSize = 13.sp,
                                )
                            },
                            onClick = {
                                removeAccount = account
                                menuAccount = null
                            },
                        )
                    }
                }
            }
        }

        Button(
            onClick = { selectedAccount?.let(onSelect) },
            enabled = selectedAccount != null && !isLoading,
            colors = ButtonDefaults.buttonColors(containerColor = Color.Transparent, contentColor = primaryContentColor()),
            shape = RoundedCornerShape(15.dp),
            contentPadding = androidx.compose.foundation.layout.PaddingValues(),
            modifier = Modifier
                .fillMaxWidth()
                .padding(top = 18.dp)
                .height(56.dp)
                .background(
                    Brush.linearGradient(listOf(primaryColor(), Color(0xFF7D6CF0))),
                    RoundedCornerShape(15.dp),
                ),
        ) {
            Text(
                text = if (isLoading) {
                    localized("Подождите…", "Please wait…", "Espere…", "Bitte warten…")
                } else {
                    localized("Продолжить как ${selectedAccount?.displayName.orEmpty()}", "Continue as ${selectedAccount?.displayName.orEmpty()}", "Continuar como ${selectedAccount?.displayName.orEmpty()}", "Fortfahren als ${selectedAccount?.displayName.orEmpty()}")
                },
                fontFamily = Manrope,
                fontWeight = FontWeight.W800,
                fontSize = 16.sp,
            )
        }

        Row(
            verticalAlignment = Alignment.CenterVertically,
            modifier = Modifier.padding(vertical = 21.dp),
        ) {
            Spacer(Modifier.weight(1f).height(1.dp).background(contentBorderColor()))
            Text(
                text = localized("или", "or", "o", "oder"),
                color = secondaryTextColor(),
                fontFamily = Manrope,
                fontWeight = FontWeight.W700,
                fontSize = 12.sp,
                modifier = Modifier.padding(horizontal = 12.dp),
            )
            Spacer(Modifier.weight(1f).height(1.dp).background(contentBorderColor()))
        }
        TextButton(
            onClick = onOtherAccount,
            enabled = !isLoading,
            modifier = Modifier.fillMaxWidth(),
        ) {
            Box(
                contentAlignment = Alignment.Center,
                modifier = Modifier
                    .size(23.dp)
                    .border(1.dp, Color(0xFFCFCBFA), RoundedCornerShape(8.dp)),
            ) {
                Text("+", color = primaryColor(), fontSize = 17.sp, lineHeight = 17.sp)
            }
            Text(
                text = localized("Войти под другим аккаунтом", "Sign in with another account", "Iniciar sesión con otra cuenta", "Mit einem anderen Konto anmelden"),
                color = primaryColor(),
                fontFamily = Manrope,
                fontWeight = FontWeight.W800,
                fontSize = 14.sp,
                modifier = Modifier.padding(start = 8.dp),
            )
        }
        Text(
            text = localized(
                "Если сохранённых аккаунтов нет, откроется обычная форма входа.",
                "If there are no saved accounts, the standard sign-in form opens.",
                "Si no hay cuentas guardadas, se abrirá el formulario de inicio de sesión.",
                "Wenn keine Konten gespeichert sind, wird das normale Anmeldeformular geöffnet.",
            ),
            color = secondaryTextColor(),
            fontFamily = Manrope,
            fontWeight = FontWeight.W600,
            fontSize = 10.sp,
            lineHeight = 14.sp,
            modifier = Modifier.padding(top = 24.dp),
        )
    }

    removeAccount?.let { account ->
        AlertDialog(
            onDismissRequest = { removeAccount = null },
            title = {
                Text(
                    text = localized("Удалить аккаунт?", "Remove account?", "¿Eliminar la cuenta?", "Konto entfernen?"),
                    fontFamily = Manrope,
                    fontWeight = FontWeight.W800,
                )
            },
            text = {
                Text(
                    text = localized(
                        "Аккаунт будет удалён только с этого устройства.",
                        "The account will only be removed from this device.",
                        "La cuenta solo se eliminará de este dispositivo.",
                        "Das Konto wird nur von diesem Gerät entfernt.",
                    ),
                    fontFamily = Manrope,
                    fontWeight = FontWeight.W600,
                )
            },
            confirmButton = {
                TextButton(
                    onClick = {
                        val target = removeAccount
                        removeAccount = null
                        if (target != null) {
                            scope.launch { onRemove(target) }
                        }
                    },
                ) {
                    Text(
                        text = localized("Удалить", "Remove", "Eliminar", "Entfernen"),
                        color = Color(0xFFE0524B),
                        fontFamily = Manrope,
                        fontWeight = FontWeight.W800,
                    )
                }
            },
            dismissButton = {
                TextButton(onClick = { removeAccount = null }) {
                    Text(
                        text = localized("Отмена", "Cancel", "Cancelar", "Abbrechen"),
                        color = primaryColor(),
                        fontFamily = Manrope,
                        fontWeight = FontWeight.W800,
                    )
                }
            },
        )
    }
}

@Composable
private fun AuthField(
    label: String,
    placeholder: String,
    value: String,
    password: Boolean = false,
    onValueChange: (String) -> Unit,
) {
    val darkTheme = LocalDarkTheme.current
    val surface = cardSurfaceColor()
    val border = if (darkTheme) OdysseyDarkBorder else contentBorderColor()
    val text = contentTextColor()
    var passwordVisible by remember { mutableStateOf(false) }
    Text(
        text = label,
        color = if (darkTheme) OdysseyDarkText else Color(0xFF3A3A42),
        fontFamily = Manrope,
        fontWeight = FontWeight.W800,
        fontSize = 13.sp,
        modifier = Modifier.padding(bottom = 8.dp),
    )
    OutlinedTextField(
        value = value,
        onValueChange = onValueChange,
        placeholder = { Text(placeholder, fontFamily = Manrope, color = secondaryTextColor()) },
        singleLine = true,
        visualTransformation = if (password && !passwordVisible) PasswordVisualTransformation() else androidx.compose.ui.text.input.VisualTransformation.None,
        trailingIcon = if (password) {
            {
                IconButton(onClick = { passwordVisible = !passwordVisible }) {
                    Icon(
                        imageVector = if (passwordVisible) Icons.Outlined.VisibilityOff else Icons.Outlined.Visibility,
                        contentDescription = if (passwordVisible) {
                            localized("Скрыть пароль", "Hide password", "Ocultar contraseña", "Passwort ausblenden")
                        } else {
                            localized("Показать пароль", "Show password", "Mostrar contraseña", "Passwort anzeigen")
                        },
                        tint = secondaryTextColor(),
                    )
                }
            }
        } else null,
        shape = RoundedCornerShape(14.dp),
        textStyle = androidx.compose.ui.text.TextStyle(
            color = text,
            fontFamily = Manrope,
            fontWeight = FontWeight.W600,
            fontSize = 15.sp,
        ),
        colors = OutlinedTextFieldDefaults.colors(
            focusedBorderColor = primaryColor(),
            unfocusedBorderColor = border,
            focusedContainerColor = surface,
            unfocusedContainerColor = surface,
            cursorColor = primaryColor(),
        ),
        modifier = Modifier.fillMaxWidth(),
    )
}

@Composable
private fun ResetPasswordScreen(onFinished: () -> Unit, onCancel: () -> Unit) {
    val language = LocalLanguage.current
    val scope = rememberCoroutineScope()
    var password by remember { mutableStateOf("") }
    var repeatedPassword by remember { mutableStateOf("") }
    var saving by remember { mutableStateOf(false) }
    var message by remember { mutableStateOf<String?>(null) }

    Column(
        verticalArrangement = Arrangement.Center,
        modifier = Modifier
            .fillMaxSize()
            .background(if (LocalDarkTheme.current) OdysseyDarkBackground else OdysseyBackground)
            .windowInsetsPadding(WindowInsets.statusBars)
            .windowInsetsPadding(WindowInsets.navigationBars)
            .imePadding()
            .verticalScroll(rememberScrollState())
            .padding(horizontal = 24.dp, vertical = 32.dp),
    ) {
        Text(
            localized("Новый пароль", "New password", "Nueva contraseña", "Neues Passwort"),
            color = contentTextColor(),
            fontFamily = Manrope,
            fontWeight = FontWeight.W800,
            fontSize = 28.sp,
        )
        Text(
            localized("Задайте новый пароль для аккаунта", "Choose a new password for your account", "Elija una nueva contraseña para su cuenta", "Legen Sie ein neues Passwort für Ihr Konto fest"),
            color = secondaryTextColor(),
            fontFamily = Manrope,
            fontWeight = FontWeight.W600,
            fontSize = 14.sp,
            modifier = Modifier.padding(top = 8.dp, bottom = 22.dp),
        )
        AuthField(localized("Новый пароль", "New password", "Nueva contraseña", "Neues Passwort"), "••••••••", password, password = true) { password = it }
        Spacer(Modifier.height(12.dp))
        AuthField(localized("Повторите пароль", "Repeat password", "Repita la contraseña", "Passwort wiederholen"), "••••••••", repeatedPassword, password = true) { repeatedPassword = it }
        message?.let {
            Text(it, color = Color(0xFFE85B56), fontFamily = Manrope, fontWeight = FontWeight.W700, fontSize = 12.sp, modifier = Modifier.padding(top = 10.dp))
        }
        Button(
            enabled = !saving,
            onClick = {
                when {
                    password.length < 6 -> message = localized(language, "Пароль должен содержать минимум 6 символов", "Password must contain at least 6 characters", "La contraseña debe tener al menos 6 caracteres", "Das Passwort muss mindestens 6 Zeichen enthalten")
                    password != repeatedPassword -> message = localized(language, "Пароли не совпадают", "Passwords do not match", "Las contraseñas no coinciden", "Passwörter stimmen nicht überein")
                    else -> scope.launch {
                        saving = true
                        message = null
                        runCatching { AccountRepository(SupabaseProvider.clientForCurrentAuthFlow()).changePassword(password) }
                            .onSuccess { onFinished() }
                            .onFailure { message = localizedFailure(language, it, localized(language, "Не удалось сменить пароль", "Could not change password", "No se pudo cambiar la contraseña", "Passwort konnte nicht geändert werden")) }
                        saving = false
                    }
                }
            },
            colors = ButtonDefaults.buttonColors(containerColor = primaryColor(), contentColor = primaryContentColor()),
            shape = RoundedCornerShape(13.dp),
            modifier = Modifier.fillMaxWidth().height(52.dp).padding(top = 16.dp),
        ) {
            Text(if (saving) localized("Сохраняем…", "Saving…", "Guardando…", "Wird gespeichert…") else localized("Сохранить пароль", "Save password", "Guardar contraseña", "Passwort speichern"), fontFamily = Manrope, fontWeight = FontWeight.W800)
        }
        TextButton(onClick = onCancel, modifier = Modifier.align(Alignment.CenterHorizontally).padding(top = 8.dp)) {
            Text(localized("Отмена", "Cancel", "Cancelar", "Abbrechen"), color = secondaryTextColor(), fontFamily = Manrope, fontWeight = FontWeight.W700)
        }
    }
}

@Composable
private fun RamingoBrand(modifier: Modifier = Modifier) {
