@Composable
private fun TripDateCalendarDialog(
    language: String,
    month: YearMonth,
    startDate: LocalDate?,
    endDate: LocalDate?,
    selectingEnd: Boolean,
    onMonthChange: (YearMonth) -> Unit,
    onDateSelected: (LocalDate) -> Unit,
    onStartClick: () -> Unit,
    onEndClick: () -> Unit,
    onDismiss: () -> Unit,
    onConfirm: () -> Unit,
) {
    val calendarDays = buildList<LocalDate?> {
        repeat(month.atDay(1).dayOfWeek.value - 1) { add(null) }
        for (day in 1..month.lengthOfMonth()) add(month.atDay(day))
    }
    val weekdays = tripCalendarWeekdays(language)
    val canConfirm = startDate != null && endDate != null && !endDate.isBefore(startDate)

    androidx.compose.ui.window.Dialog(
        onDismissRequest = onDismiss,
        properties = androidx.compose.ui.window.DialogProperties(
            usePlatformDefaultWidth = false,
            decorFitsSystemWindows = false,
        ),
    ) {
        val dialogWindow = (LocalView.current.parent as? androidx.compose.ui.window.DialogWindowProvider)?.window
        DisposableEffect(dialogWindow) {
            if (dialogWindow == null) {
                return@DisposableEffect onDispose { }
            }
            val previousStatusBarColor = dialogWindow.statusBarColor
            val previousNavigationBarColor = dialogWindow.navigationBarColor
            val previousDimAmount = dialogWindow.attributes.dimAmount
            val insetsController = WindowCompat.getInsetsController(dialogWindow, dialogWindow.decorView)
            val previousLightStatusBars = insetsController.isAppearanceLightStatusBars
            val previousLightNavigationBars = insetsController.isAppearanceLightNavigationBars

            dialogWindow.addFlags(android.view.WindowManager.LayoutParams.FLAG_DIM_BEHIND)
            dialogWindow.setDimAmount(1f)
            dialogWindow.statusBarColor = android.graphics.Color.BLACK
            dialogWindow.navigationBarColor = android.graphics.Color.BLACK
            WindowCompat.setDecorFitsSystemWindows(dialogWindow, false)
            insetsController.isAppearanceLightStatusBars = false
            insetsController.isAppearanceLightNavigationBars = false

            onDispose {
                dialogWindow.setDimAmount(previousDimAmount)
                dialogWindow.statusBarColor = previousStatusBarColor
                dialogWindow.navigationBarColor = previousNavigationBarColor
                WindowCompat.setDecorFitsSystemWindows(dialogWindow, true)
                insetsController.isAppearanceLightStatusBars = previousLightStatusBars
                insetsController.isAppearanceLightNavigationBars = previousLightNavigationBars
            }
        }
        Box(
            modifier = Modifier
                .fillMaxSize()
                .background(Color(0x660F0F19)),
            contentAlignment = Alignment.Center,
        ) {
            Column(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(horizontal = 18.dp, vertical = 22.dp)
                    .clip(RoundedCornerShape(24.dp))
                    .background(cardSurfaceColor())
                    .padding(18.dp),
                verticalArrangement = Arrangement.spacedBy(14.dp),
            ) {
                Row(verticalAlignment = Alignment.Top, horizontalArrangement = Arrangement.spacedBy(10.dp), modifier = Modifier.fillMaxWidth()) {
                    Column(modifier = Modifier.weight(1f)) {
                        Text(
                            localized("ДАТЫ ПОЕЗДКИ", "TRIP DATES", "FECHAS DEL VIAJE", "REISEDATEN"),
                            color = secondaryTextColor(),
                            fontFamily = Manrope,
                            fontWeight = FontWeight.W800,
                            fontSize = 10.sp,
                            letterSpacing = 0.8.sp,
                        )
                        Text(
                            localized("Выбрать даты", "Choose dates", "Elegir fechas", "Daten auswählen"),
                            color = contentTextColor(),
                            fontFamily = Manrope,
                            fontWeight = FontWeight.W800,
                            fontSize = 21.sp,
                            lineHeight = 24.sp,
                            modifier = Modifier.padding(top = 3.dp),
                        )
                    }
                    Box(
                        contentAlignment = Alignment.Center,
                        modifier = Modifier
                            .size(34.dp)
                            .clip(RoundedCornerShape(10.dp))
                            .background(secondarySurfaceColor())
                            .clickable(onClick = onDismiss),
                    ) {
                        Icon(Icons.Filled.Close, contentDescription = localized("Закрыть", "Close", "Cerrar", "Schließen"), tint = secondaryTextColor(), modifier = Modifier.size(17.dp))
                    }
                }
                Row(horizontalArrangement = Arrangement.spacedBy(8.dp), modifier = Modifier.fillMaxWidth()) {
                    TripCalendarRangeChip(
                        label = localized("Начало", "Start", "Inicio", "Beginn"),
                        date = startDate,
                        selected = !selectingEnd,
                        language = language,
                        modifier = Modifier.weight(1f),
                        onClick = onStartClick,
                    )
                    TripCalendarRangeChip(
                        label = localized("Окончание", "End", "Fin", "Ende"),
                        date = endDate,
                        selected = selectingEnd,
                        language = language,
                        modifier = Modifier.weight(1f),
                        onClick = onEndClick,
                    )
                }
                Text(
                    if (selectingEnd) localized("Теперь выберите дату окончания", "Now choose the end date", "Ahora elija la fecha de fin", "Wählen Sie jetzt das Ende")
                    else localized("Выберите дату начала поездки", "Choose the start date", "Elija la fecha de inicio", "Wählen Sie den Beginn"),
                    color = secondaryTextColor(),
                    fontFamily = Manrope,
                    fontWeight = FontWeight.W700,
                    fontSize = 12.sp,
                )
                Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.SpaceBetween, modifier = Modifier.fillMaxWidth()) {
                    Box(
                        contentAlignment = Alignment.Center,
                        modifier = Modifier
                            .size(40.dp)
                            .clip(RoundedCornerShape(12.dp))
                            .background(secondarySurfaceColor())
                            .clickable { onMonthChange(month.minusMonths(1)) },
                    ) {
                        Icon(Icons.Outlined.ArrowBack, contentDescription = localized("Предыдущий месяц", "Previous month", "Mes anterior", "Vorheriger Monat"), tint = contentTextColor(), modifier = Modifier.size(20.dp))
                    }
                    Text(tripCalendarMonthLabel(month, language), color = contentTextColor(), fontFamily = Manrope, fontWeight = FontWeight.W800, fontSize = 15.sp)
                    Box(
                        contentAlignment = Alignment.Center,
                        modifier = Modifier
                            .size(40.dp)
                            .clip(RoundedCornerShape(12.dp))
                            .background(secondarySurfaceColor())
                            .clickable { onMonthChange(month.plusMonths(1)) },
                    ) {
                        Icon(Icons.Outlined.ArrowBack, contentDescription = localized("Следующий месяц", "Next month", "Mes siguiente", "Nächster Monat"), tint = contentTextColor(), modifier = Modifier.size(20.dp).graphicsLayer(rotationZ = 180f))
                    }
                }
                Row(modifier = Modifier.fillMaxWidth()) {
                    weekdays.forEach { weekday ->
                        Box(contentAlignment = Alignment.Center, modifier = Modifier.weight(1f).height(24.dp)) {
                            Text(weekday, color = secondaryTextColor(), fontFamily = Manrope, fontWeight = FontWeight.W800, fontSize = 11.sp)
                        }
                    }
                }
                calendarDays.chunked(7).forEach { week ->
                    Row(modifier = Modifier.fillMaxWidth()) {
                        week.forEach { date ->
                            val isStart = date != null && date == startDate
                            val isEnd = date != null && date == endDate
                            val inRange = date != null && startDate != null && endDate != null && date.isAfter(startDate) && date.isBefore(endDate)
                            val enabled = date != null && (!selectingEnd || startDate == null || !date.isBefore(startDate))
                            Box(
                                contentAlignment = Alignment.Center,
                                modifier = Modifier
                                    .weight(1f)
                                    .height(42.dp)
                                    .clip(RoundedCornerShape(12.dp))
                                    .background(
                                        when {
                                            isStart || isEnd -> primaryColor()
                                            inRange -> tintedSurfaceColor()
                                            else -> Color.Transparent
                                        },
                                    )
                                    .clickable(enabled = enabled) { date?.let(onDateSelected) },
                            ) {
                                date?.let {
                                    Text(
                                        it.dayOfMonth.toString(),
                                        color = when {
                                            isStart || isEnd -> primaryContentColor()
                                            !enabled -> secondaryTextColor().copy(alpha = 0.35f)
                                            else -> contentTextColor()
                                        },
                                        fontFamily = Manrope,
                                        fontWeight = if (isStart || isEnd) FontWeight.W800 else FontWeight.W700,
                                        fontSize = 14.sp,
                                    )
                                }
                            }
                        }
                        repeat(7 - week.size) {
                            Spacer(Modifier.weight(1f).height(42.dp))
                        }
                    }
                }
                Row(horizontalArrangement = Arrangement.spacedBy(9.dp), modifier = Modifier.fillMaxWidth()) {
                    Button(
                        onClick = onDismiss,
                        colors = ButtonDefaults.buttonColors(containerColor = secondarySurfaceColor(), contentColor = contentTextColor()),
                        shape = RoundedCornerShape(12.dp),
                        modifier = Modifier.weight(1f).height(46.dp),
                    ) { Text(localized("Отмена", "Cancel", "Cancelar", "Abbrechen"), fontFamily = Manrope, fontWeight = FontWeight.W800, fontSize = 14.sp) }
                    Button(
                        onClick = onConfirm,
                        enabled = canConfirm,
                        colors = ButtonDefaults.buttonColors(containerColor = primaryColor(), contentColor = primaryContentColor(), disabledContainerColor = secondarySurfaceColor(), disabledContentColor = secondaryTextColor()),
                        shape = RoundedCornerShape(12.dp),
                        modifier = Modifier.weight(1f).height(46.dp),
                    ) { Text(localized("Готово", "Done", "Listo", "Fertig"), fontFamily = Manrope, fontWeight = FontWeight.W800, fontSize = 14.sp) }
                }
            }
        }
    }
}

@Composable
private fun EditTripPanel(
    trip: TripCard,
    onClose: () -> Unit,
    onSaved: (TripCard) -> Unit,
    onDeleted: (String) -> Unit,
) {
    val language = LocalLanguage.current
    val displayedTitle = localizedTripTitle(trip.title)
    val displayedCities = localizedCityList(trip.cities, language)
    val displayedDates = localizedTripDateText(trip.dates, language)
    var title by remember(trip.id, language) { mutableStateOf(displayedTitle) }
    var cities by remember(trip.id, language) { mutableStateOf(displayedCities) }
    var dates by remember(trip.id, language) { mutableStateOf(displayedDates) }
    var status by remember(trip.id) { mutableStateOf(trip.status) }
    var saving by remember { mutableStateOf(false) }
    var deleting by remember { mutableStateOf(false) }
    var leaving by remember { mutableStateOf(false) }
    var deleteDialogOpen by remember { mutableStateOf(false) }
    var leaveDialogOpen by remember { mutableStateOf(false) }
    var message by remember { mutableStateOf<String?>(null) }
    var dateShiftWarningDays by remember { mutableStateOf<Int?>(null) }
    val scope = rememberCoroutineScope()
    var tripCalendarOpen by remember { mutableStateOf(false) }
    var tripCalendarStep by remember { mutableStateOf("start") }
    var tripCalendarMonth by remember { mutableStateOf(YearMonth.now()) }
    var tripCalendarStart by remember { mutableStateOf<LocalDate?>(null) }
    var tripCalendarEnd by remember { mutableStateOf<LocalDate?>(null) }

    fun openTripDatePicker() {
        val fallbackStart = LocalDate.now()
        val currentRange = parseTripDateRange(dates) ?: parseTripDateRange(trip.dates)
        val currentStart = currentRange?.first ?: fallbackStart
        tripCalendarStart = currentStart
        tripCalendarEnd = currentRange?.second ?: currentStart.plusDays(1)
        tripCalendarMonth = YearMonth.from(currentStart)
        tripCalendarStep = "start"
        tripCalendarOpen = true
    }

    fun deleteTrip() {
        deleteDialogOpen = false
        scope.launch {
            deleting = true
            message = null
            runCatching {
                SupabaseTripRepository(SupabaseProvider.clientForCurrentAuthFlow()).deleteTrip(trip.id)
            }
                .onSuccess { onDeleted(trip.id) }
                .onFailure {
                    message = localizedFailure(language, it, localized(
                        language,
                        "Не удалось удалить путешествие",
                        "Could not delete trip",
                        "No se pudo eliminar el viaje",
                        "Reise konnte nicht gelöscht werden",
                    ))
                }
            deleting = false
        }
    }

    fun leaveTrip() {
        leaveDialogOpen = false
        scope.launch {
            leaving = true
            message = null
            runCatching {
                SupabaseTripRepository(SupabaseProvider.clientForCurrentAuthFlow()).leaveTrip(trip.id)
            }
                .onSuccess { onDeleted(trip.id) }
                .onFailure {
                    message = localizedFailure(language, it, localized(
                        language,
                        "Не удалось выйти из путешествия",
                        "Could not leave trip",
                        "No se pudo salir del viaje",
                        "Die Reise konnte nicht verlassen werden",
                    ))
                }
            leaving = false
        }
    }

    fun saveTrip(allowRouteDayArchive: Boolean = false) {
        scope.launch {
            saving = true
            message = null
            val savedTitle = title.trim().takeUnless { it == displayedTitle } ?: trip.title.trim()
            val savedCities = cities.trim().takeUnless { it == displayedCities } ?: trip.cities.trim()
            val savedDates = dates.trim().takeUnless { it == displayedDates } ?: trip.dates.trim()
            val repository = SupabaseTripRepository(SupabaseProvider.clientForCurrentAuthFlow())
            val routeShapeChanged = savedDates != trip.dates.trim() || savedCities != trip.cities.trim()
            if (!allowRouteDayArchive && routeShapeChanged) {
                val daysAtRisk = runCatching {
                    repository.countRouteDaysAtRisk(trip.id, savedDates, savedCities)
                }.getOrElse {
                    message = localizedFailure(language, it, localized(language, "Не удалось проверить дни маршрута", "Could not check the route days", "No se pudieron comprobar los días de la ruta", "Die Routentage konnten nicht geprüft werden"))
                    saving = false
                    return@launch
                }
                if (daysAtRisk > 0) {
                    dateShiftWarningDays = daysAtRisk
                    saving = false
                    return@launch
                }
            }
            runCatching {
                repository.updateTripDetails(trip.id, savedTitle, savedDates, savedCities)
                repository.updateTripSection(trip.id, "status", JsonPrimitive(status))
            }
                .onSuccess { onSaved(trip.copy(title = savedTitle, cities = savedCities, dates = savedDates, status = status)) }
                .onFailure { message = localizedFailure(language, it, localized(language, "Не удалось сохранить изменения", "Could not save changes", "No se pudieron guardar los cambios", "Änderungen konnten nicht gespeichert werden")) }
            saving = false
        }
    }

    val summaryTitle = when {
        status.contains("чернов", ignoreCase = true) || status.equals("draft", ignoreCase = true) -> localized("Черновик путешествия", "Draft trip", "Borrador de viaje", "Reiseentwurf")
        status.contains("прошед", ignoreCase = true) || status.contains("заверш", ignoreCase = true) || status.equals("past", ignoreCase = true) || status.equals("completed", ignoreCase = true) -> localized("Завершённое путешествие", "Completed trip", "Viaje completado", "Abgeschlossene Reise")
        else -> localized("Предстоящее путешествие", "Upcoming trip", "Próximo viaje", "Bevorstehende Reise")
    }

    Column(
        modifier = Modifier
            .fillMaxWidth()
            .clip(RoundedCornerShape(22.dp))
            .background(cardSurfaceColor())
            .padding(15.dp),
        verticalArrangement = Arrangement.spacedBy(8.dp),
    ) {
        Row(
            horizontalArrangement = Arrangement.spacedBy(10.dp),
            verticalAlignment = Alignment.Top,
            modifier = Modifier.fillMaxWidth(),
        ) {
            Column(modifier = Modifier.weight(1f)) {
                Text(
                    localized("НАСТРОЙКИ ПОЕЗДКИ", "TRIP SETTINGS", "AJUSTES DEL VIAJE", "REISEEINSTELLUNGEN"),
                    color = secondaryTextColor(),
                    fontFamily = Manrope,
                    fontWeight = FontWeight.W800,
                    fontSize = 10.sp,
                    letterSpacing = 0.8.sp,
                )
                Text(
                    displayedTitle,
                    color = contentTextColor(),
                    fontFamily = Manrope,
                    fontWeight = FontWeight.W800,
                    fontSize = 21.sp,
                    lineHeight = 24.sp,
                    maxLines = 2,
                    overflow = TextOverflow.Ellipsis,
                    modifier = Modifier.padding(top = 3.dp),
                )
            }
            Box(
                contentAlignment = Alignment.Center,
                modifier = Modifier
                    .size(34.dp)
                    .clip(RoundedCornerShape(10.dp))
                    .background(secondarySurfaceColor())
                    .clickable(onClick = onClose),
            ) {
                Icon(
                    Icons.Filled.Close,
                    contentDescription = localized("Закрыть", "Close", "Cerrar", "Schließen"),
                    tint = secondaryTextColor(),
                    modifier = Modifier.size(17.dp),
                )
            }
        }
        Spacer(Modifier.fillMaxWidth().height(1.dp).background(contentBorderColor()))
        Row(
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.spacedBy(11.dp),
            modifier = Modifier
                .fillMaxWidth()
                .clip(RoundedCornerShape(15.dp))
                .background(tintedSurfaceColor())
                .padding(12.dp),
        ) {
            Box(
                contentAlignment = Alignment.Center,
                modifier = Modifier
                    .size(36.dp)
                    .clip(RoundedCornerShape(11.dp))
                    .background(primaryColor()),
            ) {
                Text("R", color = primaryContentColor(), fontFamily = Manrope, fontWeight = FontWeight.W800, fontSize = 17.sp)
            }
            Column(modifier = Modifier.weight(1f)) {
                Text(summaryTitle, color = contentTextColor(), fontFamily = Manrope, fontWeight = FontWeight.W800, fontSize = 14.sp, maxLines = 1, overflow = TextOverflow.Ellipsis)
                Text(localizedTripDateText(dates, language), color = secondaryTextColor(), fontFamily = Manrope, fontWeight = FontWeight.W700, fontSize = 11.sp, maxLines = 1, overflow = TextOverflow.Ellipsis, modifier = Modifier.padding(top = 3.dp))
            }
        }
        Text(
            localized("ОСНОВНОЕ", "MAIN DETAILS", "DATOS PRINCIPALES", "GRUNDDATEN"),
            color = secondaryTextColor(),
            fontFamily = Manrope,
            fontWeight = FontWeight.W800,
            fontSize = 11.sp,
            letterSpacing = 0.8.sp,
            modifier = Modifier.padding(top = 1.dp),
        )
        CompactTripEditField(
            localized("Название путешествия", "Trip name", "Nombre del viaje", "Name der Reise"),
            title,
        ) { title = it }
        CompactTripEditField(
            localized("Маршрут", "Route", "Ruta", "Route"),
            cities,
            Icons.Outlined.LocationOn,
        ) { cities = it }
        CompactTripDateField(
            localized("Даты поездки", "Trip dates", "Fechas del viaje", "Reisedaten"),
            localizedTripDateText(dates, language),
            ::openTripDatePicker,
        )
        Text(
            localized("Статус", "Status", "Estado", "Status"),
            color = contentTextColor(),
            fontFamily = Manrope,
            fontWeight = FontWeight.W800,
            fontSize = 12.sp,
            modifier = Modifier.padding(top = 1.dp),
        )
        Row(
            horizontalArrangement = Arrangement.spacedBy(4.dp),
            modifier = Modifier
                .fillMaxWidth()
                .clip(RoundedCornerShape(13.dp))
                .background(secondarySurfaceColor())
                .padding(4.dp),
        ) {
            listOf(
                "Предстоящее" to localized("Предстоящие", "Upcoming", "Próximos", "Bevorstehend"),
                "Черновик" to localized("Черновики", "Drafts", "Borradores", "Entwürfe"),
                "Прошедшее" to localized("Прошедшие", "Past", "Pasados", "Vergangen"),
            ).forEach { (value, label) ->
                val selected = when (value) {
                    "Предстоящее" -> status.contains("предст", ignoreCase = true) || status.equals("upcoming", ignoreCase = true)
                    "Черновик" -> status.contains("чернов", ignoreCase = true) || status.equals("draft", ignoreCase = true)
                    else -> status.contains("прошед", ignoreCase = true) || status.contains("заверш", ignoreCase = true) || status.equals("past", ignoreCase = true) || status.equals("completed", ignoreCase = true)
                }
                Box(
                    contentAlignment = Alignment.Center,
                    modifier = Modifier
                        .weight(1f)
                        .height(34.dp)
                        .clip(RoundedCornerShape(9.dp))
                        .background(if (selected) cardSurfaceColor() else Color.Transparent)
                        .clickable { status = value },
                ) {
                    Text(label, color = if (selected) contentTextColor() else secondaryTextColor(), fontFamily = Manrope, fontWeight = FontWeight.W800, fontSize = 11.sp, maxLines = 1, overflow = TextOverflow.Ellipsis)
                }
            }
        }
        if (message != null) Text(message!!, color = Color(0xFFE0524B), fontFamily = Manrope, fontWeight = FontWeight.W700, fontSize = 12.sp)
        Row(horizontalArrangement = Arrangement.spacedBy(9.dp), modifier = Modifier.fillMaxWidth()) {
            Button(onClick = onClose, colors = ButtonDefaults.buttonColors(containerColor = secondarySurfaceColor(), contentColor = contentTextColor()), shape = RoundedCornerShape(12.dp), modifier = Modifier.weight(1f).height(46.dp), contentPadding = androidx.compose.foundation.layout.PaddingValues(horizontal = 8.dp)) { Text(localized("Отмена", "Cancel", "Cancelar", "Abbrechen"), fontFamily = Manrope, fontWeight = FontWeight.W800, fontSize = 14.sp) }
            Button(onClick = { saveTrip() }, enabled = !saving && !deleting && !leaving, colors = ButtonDefaults.buttonColors(containerColor = primaryColor(), contentColor = primaryContentColor()), shape = RoundedCornerShape(12.dp), modifier = Modifier.weight(1f).height(46.dp), contentPadding = androidx.compose.foundation.layout.PaddingValues(horizontal = 8.dp)) { Text(if (saving) localized("Сохраняем…", "Saving…", "Guardando…", "Wird gespeichert…") else localized("Сохранить", "Save", "Guardar", "Speichern"), fontFamily = Manrope, fontWeight = FontWeight.W800, fontSize = 14.sp) }
        }
        Row(
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.spacedBy(9.dp),
            modifier = Modifier
                .fillMaxWidth()
                .clip(RoundedCornerShape(14.dp))
                .border(
                    1.dp,
                    if (LocalDarkTheme.current) Color(0xFF7A3B42) else Color(0xFFF1D0CF),
                    RoundedCornerShape(14.dp),
                )
                .background(dangerSurfaceColor())
                .clickable(enabled = !saving && !deleting && !leaving) {
                    if (trip.isOwner) deleteDialogOpen = true else leaveDialogOpen = true
                }
                .padding(11.dp),
        ) {
            Box(
                contentAlignment = Alignment.Center,
                modifier = Modifier
                    .size(28.dp)
                    .clip(RoundedCornerShape(9.dp))
                    .background(dangerSurfaceColor()),
            ) {
                Icon(if (trip.isOwner) Icons.Outlined.Delete else Icons.Outlined.Logout, contentDescription = null, tint = Color(0xFFD9534F), modifier = Modifier.size(17.dp))
            }
            Column(modifier = Modifier.weight(1f)) {
                Text(
                    if (trip.isOwner) localized("Удалить путешествие", "Delete trip", "Eliminar viaje", "Reise löschen")
                    else localized("Выйти из путешествия", "Leave trip", "Salir del viaje", "Reise verlassen"),
                    color = Color(0xFFD9534F),
                    fontFamily = Manrope,
                    fontWeight = FontWeight.W800,
                    fontSize = 13.sp,
                )
                Text(
                    if (trip.isOwner) localized("Удаление нельзя отменить", "This cannot be undone", "No se puede deshacer", "Das kann nicht rückgängig gemacht werden")
                    else localized("Поездка останется у остальных участников", "The trip will remain for the other members", "El viaje permanecerá para los demás participantes", "Die Reise bleibt für die anderen Mitglieder erhalten"),
                    color = Color(0xFFB78380),
                    fontFamily = Manrope,
                    fontWeight = FontWeight.W600,
                    fontSize = 11.sp,
                    modifier = Modifier.padding(top = 2.dp),
                )
            }
        }
    }
    if (tripCalendarOpen) {
        TripDateCalendarDialog(
            language = language,
            month = tripCalendarMonth,
            startDate = tripCalendarStart,
            endDate = tripCalendarEnd,
            selectingEnd = tripCalendarStep == "end",
            onMonthChange = { tripCalendarMonth = it },
            onDateSelected = { selectedDate ->
                if (tripCalendarStep == "start") {
                    tripCalendarStart = selectedDate
                    tripCalendarEnd = tripCalendarEnd?.takeIf { !it.isBefore(selectedDate) }
                    tripCalendarMonth = YearMonth.from(tripCalendarEnd ?: selectedDate)
                    tripCalendarStep = "end"
                } else if (tripCalendarStart == null || !selectedDate.isBefore(tripCalendarStart)) {
                    tripCalendarEnd = selectedDate
                }
            },
            onStartClick = {
                tripCalendarStep = "start"
                tripCalendarStart?.let { tripCalendarMonth = YearMonth.from(it) }
            },
            onEndClick = {
                tripCalendarStep = "end"
                tripCalendarEnd?.let { tripCalendarMonth = YearMonth.from(it) }
            },
            onDismiss = { tripCalendarOpen = false },
            onConfirm = {
                val selectedStart = tripCalendarStart
                val selectedEnd = tripCalendarEnd
                if (selectedStart != null && selectedEnd != null && !selectedEnd.isBefore(selectedStart)) {
                    dates = "$selectedStart — $selectedEnd"
                    tripCalendarOpen = false
                }
            },
        )
    }
    dateShiftWarningDays?.let { daysAtRisk ->
        val dayLabel = localizedCountWord(
            daysAtRisk,
            language,
            "день",
            "дня",
            "дней",
            "day",
            "days",
            "día",
            "días",
            "Tag",
            "Tage",
        )
        AlertDialog(
            onDismissRequest = { dateShiftWarningDays = null },
            title = {
                Text(
                    localized("Изменение дат скроет дни маршрута", "Changing dates will hide route days", "Cambiar las fechas ocultará días de la ruta", "Die Datumsänderung blendet Reisetage aus"),
                    fontFamily = Manrope,
                    fontWeight = FontWeight.W800,
                )
            },
            text = {
                Text(
                    localized(
                        "$daysAtRisk $dayLabel выйдут за новые даты и будут скрыты из маршрута. Они останутся в архиве.",
                        "$daysAtRisk $dayLabel will fall outside the new dates and be hidden from the route. They will remain archived.",
                        "$daysAtRisk $dayLabel quedarán fuera de las nuevas fechas y se ocultarán de la ruta. Permanecerán archivados.",
                        "$daysAtRisk $dayLabel liegen außerhalb der neuen Daten und werden aus der Route ausgeblendet. Sie bleiben archiviert.",
                    ),
                    fontFamily = Manrope,
                    fontWeight = FontWeight.W600,
                )
            },
            dismissButton = {
                TextButton(onClick = { dateShiftWarningDays = null }) {
                    Text(localized("Отмена", "Cancel", "Cancelar", "Abbrechen"), fontFamily = Manrope, fontWeight = FontWeight.W800)
                }
            },
            confirmButton = {
                TextButton(onClick = { dateShiftWarningDays = null; saveTrip(allowRouteDayArchive = true) }) {
                    Text(localized("Продолжить", "Continue", "Continuar", "Fortfahren"), color = primaryColor(), fontFamily = Manrope, fontWeight = FontWeight.W800)
                }
            },
        )
    }
    if (deleteDialogOpen) {
        AlertDialog(
            onDismissRequest = { if (!deleting) deleteDialogOpen = false },
            title = {
                Text(localized("Удалить путешествие?", "Delete trip?", "¿Eliminar viaje?", "Reise löschen?"), fontFamily = Manrope, fontWeight = FontWeight.W800)
            },
            text = {
                Text(
                    localized(
                        "Путешествие, его фотографии и данные будут удалены без возможности восстановления.",
                        "This trip, its photos, and all of its data will be permanently deleted.",
                        "Este viaje, sus fotos y todos sus datos se eliminarán de forma permanente.",
                        "Diese Reise, ihre Fotos und alle Daten werden dauerhaft gelöscht.",
                    ),
                    fontFamily = Manrope,
                    fontWeight = FontWeight.W600,
                )
            },
            dismissButton = {
                TextButton(onClick = { deleteDialogOpen = false }, enabled = !deleting) {
                    Text(localized("Отмена", "Cancel", "Cancelar", "Abbrechen"), fontFamily = Manrope, fontWeight = FontWeight.W800)
                }
            },
            confirmButton = {
                TextButton(
                    onClick = ::deleteTrip,
                    enabled = !deleting,
                    colors = ButtonDefaults.textButtonColors(contentColor = Color(0xFFD9534F)),
                ) {
                    Text(
                        if (deleting) localized("Удаляем…", "Deleting…", "Eliminando…", "Wird gelöscht…")
                        else localized("Удалить", "Delete", "Eliminar", "Löschen"),
                        fontFamily = Manrope,
                        fontWeight = FontWeight.W800,
                    )
                }
            },
        )
    }
    if (leaveDialogOpen) {
        AlertDialog(
            onDismissRequest = { if (!leaving) leaveDialogOpen = false },
            title = {
                Text(localized("Выйти из путешествия?", "Leave trip?", "¿Salir del viaje?", "Reise verlassen?"), fontFamily = Manrope, fontWeight = FontWeight.W800)
            },
            text = {
                Text(
                    localized(
                        "Вы перестанете видеть это путешествие. У создателя и остальных участников оно останется.",
                        "You will stop seeing this trip. It will remain with the owner and other members.",
                        "Dejarás de ver este viaje. Permanecerá para el creador y los demás participantes.",
                        "Sie sehen diese Reise danach nicht mehr. Für den Ersteller und die anderen Mitglieder bleibt sie erhalten.",
                    ),
                    fontFamily = Manrope,
                    fontWeight = FontWeight.W600,
                )
            },
            dismissButton = {
                TextButton(onClick = { leaveDialogOpen = false }, enabled = !leaving) {
                    Text(localized("Остаться", "Stay", "Quedarse", "Bleiben"), fontFamily = Manrope, fontWeight = FontWeight.W800)
                }
            },
            confirmButton = {
                TextButton(
                    onClick = ::leaveTrip,
                    enabled = !leaving,
                    colors = ButtonDefaults.textButtonColors(contentColor = Color(0xFFD9534F)),
                ) {
                    Text(
                        if (leaving) localized("Выходим…", "Leaving…", "Saliendo…", "Wird verlassen…")
                        else localized("Выйти", "Leave", "Salir", "Verlassen"),
                        fontFamily = Manrope,
                        fontWeight = FontWeight.W800,
                    )
                }
            },
        )
    }
}

@Composable
@OptIn(ExperimentalMaterial3Api::class)
private fun CreateTripScreen(
    onBack: () -> Unit,
    onCreated: (TripCard) -> Unit,
    onAuthRequired: () -> Unit,
) {
    val darkTheme = LocalDarkTheme.current
    val language = LocalLanguage.current
    val context = LocalContext.current
    var title by remember { mutableStateOf("") }
    var startDate by remember { mutableStateOf("") }
    var endDate by remember { mutableStateOf("") }
    var cities by remember { mutableStateOf("") }
    var cityDialogOpen by remember { mutableStateOf(false) }
    var datePickerTarget by remember { mutableStateOf<String?>(null) }
    var citySearch by remember { mutableStateOf("") }
    var citySearchResults by remember { mutableStateOf(cityCatalog) }
    var citySearchLoading by remember { mutableStateOf(false) }
    var selectedCatalogEntries by remember { mutableStateOf<Map<String, CityCatalogEntry>>(emptyMap()) }
    val cityCatalogContext = LocalContext.current
    val cityCatalogRepository = remember(cityCatalogContext) { CityCatalogRepository(cityCatalogContext.assets) }
    val cityList = remember(cities) {
        cities.split(",").map(String::trim).filter(String::isNotBlank)
    }
    val selectedCityKeys = remember(cityList, selectedCatalogEntries) {
        (selectedCatalogEntries.keys + cityList.mapNotNull { cityCatalogEntry(it)?.key }).toSet()
    }
    val normalizedCitySearch = citySearch
        .trim()
        .lowercase(Locale.ROOT)
        .replace('ё', 'е')
    val filteredCatalogCities = remember(citySearchResults, selectedCityKeys) {
        citySearchResults.sortedByDescending { entry -> entry.key in selectedCityKeys }
    }
    val duplicateCityNames = remember(filteredCatalogCities, language) {
        filteredCatalogCities
            .groupingBy { normalizeCityAlias(it.localized(language)) }
            .eachCount()
            .filterValues { count -> count > 1 }
            .keys
    }
    val duplicateCityCountryNames = remember(filteredCatalogCities, language) {
        filteredCatalogCities
            .groupingBy { entry ->
                "${normalizeCityAlias(entry.localized(language))}|${entry.countryCode.uppercase(Locale.ROOT)}"
            }
            .eachCount()
            .filterValues { count -> count > 1 }
            .keys
    }
    var saving by remember { mutableStateOf(false) }
    var message by remember { mutableStateOf<String?>(null) }
    var newTripPhotos by remember { mutableStateOf<List<NewTripPhoto>>(emptyList()) }
    val scope = rememberCoroutineScope()
    val newTripPhotoPicker = rememberLauncherForActivityResult(ActivityResultContracts.GetMultipleContents()) { uris ->
        val knownUris = newTripPhotos.mapTo(mutableSetOf()) { it.uri.toString() }
        newTripPhotos = newTripPhotos + uris
            .filter { knownUris.add(it.toString()) }
            .map(::NewTripPhoto)
        message = null
    }

    LaunchedEffect(cityDialogOpen, normalizedCitySearch, language) {
        if (!cityDialogOpen) return@LaunchedEffect
        delay(220)
        citySearchLoading = true
        try {
            citySearchResults = cityCatalogRepository.search(citySearch, language)
        } catch (error: CancellationException) {
            throw error
        } catch (_: Throwable) {
            citySearchResults = emptyList()
        } finally {
            citySearchLoading = false
        }
    }

    fun storedValueFor(entry: CityCatalogEntry): String = entry.selectionValue(language)

    fun entryForStoredCity(value: String): CityCatalogEntry? = selectedCatalogEntries.values.firstOrNull { entry ->
        val cityPart = value.substringBefore(" — ").trim()
        entry.aliases.contains(normalizeCityAlias(cityPart)) ||
            listOf(entry.russian, entry.english, entry.spanish, entry.german).any { name ->
                name.equals(cityPart, ignoreCase = true)
            }
    } ?: cityCatalogEntry(value)

    fun toggleCatalogCity(entry: CityCatalogEntry) {
        val existingCity = cityList.firstOrNull { entryForStoredCity(it)?.key == entry.key }
        cities = if (existingCity != null) {
            selectedCatalogEntries = selectedCatalogEntries - entry.key
            cityList.filterNot { entryForStoredCity(it)?.key == entry.key }.joinToString(", ")
        } else {
            selectedCatalogEntries = selectedCatalogEntries + (entry.key to entry)
            (cityList + storedValueFor(entry)).joinToString(", ")
        }
        message = null
    }

    fun openCityPicker() {
        citySearch = ""
        message = null
        cityDialogOpen = true
    }

    fun save() {
        when (validateCreateTripRequiredFields(title, startDate, endDate, cityList)) {
            CreateTripValidationError.TITLE_REQUIRED -> {
                message = localized(
                    language,
                    "Введите название путешествия",
                    "Enter a trip name",
                    "Escriba el nombre del viaje",
                    "Geben Sie einen Reisenamen ein",
                )
                return
            }
            CreateTripValidationError.DATES_REQUIRED -> {
                message = localized(
                    language,
                    "Выберите даты начала и окончания",
                    "Choose start and end dates",
                    "Elija las fechas de inicio y fin",
                    "Wählen Sie Start- und Enddatum",
                )
                return
            }
            CreateTripValidationError.CITIES_REQUIRED -> {
                message = localized(
                    language,
                    "Добавьте хотя бы один город",
                    "Add at least one city",
                    "Añada al menos una ciudad",
                    "Fügen Sie mindestens eine Stadt hinzu",
                )
                return
            }
            null -> Unit
        }
        title = title.trim()
        val unsupportedCity = cityList.firstOrNull { entryForStoredCity(it) == null }
        if (unsupportedCity != null) {
            message = localized(
                language,
                "Выберите город из каталога",
                "Choose a city from the catalog",
                "Elija una ciudad del catálogo",
                "Wählen Sie eine Stadt aus dem Katalog",
            )
            return
        }
        if (
            startDate.isNotBlank() &&
            endDate.isNotBlank() &&
            parseRouteDate(startDate)?.let { start ->
                parseRouteDate(endDate)?.let { end -> end.timeInMillis < start.timeInMillis }
            } == true
        ) {
            message = localized(language, "Дата окончания не может быть раньше даты начала", "The end date cannot be before the start date", "La fecha de finalización no puede ser anterior a la de inicio", "Das Enddatum darf nicht vor dem Startdatum liegen")
            return
        }
        val selectedPhotoItems = newTripPhotos
        scope.launch {
            saving = true
            message = null
            val cityCoordinates = cityList.mapNotNull { city ->
                entryForStoredCity(city)?.let { entry ->
                    city to CityLocation(entry.latitude, entry.longitude)
                }
            }.toMap()
            if (!SupabaseProvider.ensureActiveSession()) {
                onAuthRequired()
                saving = false
                return@launch
            }
            runCatching {
                val repository = SupabaseTripRepository(SupabaseProvider.clientForCurrentAuthFlow())
                val created = repository.createTrip(title, startDate, endDate, cities, cityCoordinates)
                try {
                    selectedPhotoItems.forEach { photo ->
                        val bytes = context.contentResolver.openInputStream(photo.uri)?.use { it.readBytes() }
                            ?: error(localized(language, "\u041d\u0435 \u0443\u0434\u0430\u043b\u043e\u0441\u044c \u043f\u0440\u043e\u0447\u0438\u0442\u0430\u0442\u044c \u0438\u0437\u043e\u0431\u0440\u0430\u0436\u0435\u043d\u0438\u0435", "Could not read the image", "No se pudo leer la imagen", "Das Bild konnte nicht gelesen werden"))
                        repository.addCoverPhoto(created.id, bytes, photo.city)
                    }
                } catch (photoError: Throwable) {
                    runCatching { repository.deleteTrip(created.id) }
                    throw photoError
                }
                created
            }.onSuccess { onCreated(it) }.onFailure { error ->
                if (error is AuthSessionRequiredException) {
                    onAuthRequired()
                } else {
                    message = localizedFailure(language, error, localized(language, "Не удалось создать путешествие", "Could not create trip", "No se pudo crear el viaje", "Reise konnte nicht erstellt werden"))
                }
            }
            saving = false
        }
    }

    Column(
        modifier = Modifier
            .fillMaxSize()
            .background(if (darkTheme) OdysseyDarkBackground else OdysseyBackground)
            .padding(WindowInsets.statusBars.asPaddingValues()),
    ) {
        Row(
            verticalAlignment = Alignment.CenterVertically,
            modifier = Modifier.fillMaxWidth().height(54.dp).padding(horizontal = 16.dp),
        ) {
            Box(
                contentAlignment = Alignment.Center,
                modifier = Modifier.size(40.dp).clickable { onBack() },
            ) {
                Icon(Icons.Outlined.Menu, contentDescription = localized("Назад", "Back", "Atrás", "Zurück"), tint = contentTextColor(), modifier = Modifier.size(22.dp))
            }
            Box(contentAlignment = Alignment.Center, modifier = Modifier.weight(1f)) {
                RamingoBrand()
            }
            Spacer(Modifier.size(40.dp))
        }

        Column(
            modifier = Modifier
                .weight(1f)
                .verticalScroll(rememberScrollState())
                .imePadding()
                .padding(start = 18.dp, top = 18.dp, end = 18.dp, bottom = 30.dp + WindowInsets.navigationBars.asPaddingValues().calculateBottomPadding()),
        ) {
            Text(
                localized("Новое путешествие", "New trip", "Nuevo viaje", "Neue Reise"),
                color = contentTextColor(),
                fontFamily = Manrope,
                fontWeight = FontWeight.W800,
                fontSize = 30.sp,
                lineHeight = 31.sp,
                modifier = Modifier.fillMaxWidth(),
            )
            Text(
                localized("Заполните данные путешествия", "Fill in your trip details", "Complete los datos del viaje", "Füllen Sie die Reisedaten aus"),
                color = secondaryTextColor(),
                fontFamily = Manrope,
                fontWeight = FontWeight.W500,
                fontSize = 13.sp,
                lineHeight = 18.sp,
                modifier = Modifier.padding(top = 8.dp),
            )

            CreateTripCoverPhoto(
                language = language,
                photoUris = newTripPhotos.map { it.uri },
                onPickPhoto = { if (!saving) newTripPhotoPicker.launch("image/*") },
                onRemovePhoto = { uri -> newTripPhotos = newTripPhotos.filterNot { it.uri == uri } },
            )

            Column(
                verticalArrangement = Arrangement.spacedBy(16.dp),
                modifier = Modifier.padding(top = 20.dp),
            ) {
                TripCreateField(
                    label = localized("Название поездки", "Trip name", "Nombre del viaje", "Name der Reise"),
                    placeholder = localized("Введите название", "Enter trip name", "Escriba el nombre del viaje", "Reisename eingeben"),
                    value = title,
                    onValueChange = { title = it },
                )
                Row(horizontalArrangement = Arrangement.spacedBy(12.dp), modifier = Modifier.fillMaxWidth()) {
                    TripCreateDateField(
                        label = localized("Начало", "Start", "Inicio", "Beginn"),
                        placeholder = localized("Выберите дату", "Choose date", "Elija una fecha", "Datum auswählen"),
                        value = startDate,
                        onClick = { datePickerTarget = "start" },
                        modifier = Modifier.weight(1f),
                    )
                    TripCreateDateField(
                        label = localized("Конец", "End", "Fin", "Ende"),
                        placeholder = localized("Выберите дату", "Choose date", "Elija una fecha", "Datum auswählen"),
                        value = endDate,
                        onClick = { datePickerTarget = "end" },
                        modifier = Modifier.weight(1f),
                    )
                }
                Column {
                    Text(
                        localized("Города", "Cities", "Ciudades", "Städte"),
                        color = secondaryTextColor(),
                        fontFamily = Manrope,
                        fontWeight = FontWeight.W700,
                        fontSize = 12.sp,
                        modifier = Modifier.padding(bottom = 7.dp),
                    )
                    Box(
                        modifier = Modifier
                            .fillMaxWidth()
                            .heightIn(min = 49.dp)
                            .clip(RoundedCornerShape(13.dp))
                            .border(1.5.dp, if (darkTheme) OdysseyDarkBorder else contentBorderColor(), RoundedCornerShape(13.dp))
                            .clickable(onClick = ::openCityPicker),
                    ) {
                        Row(
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.spacedBy(8.dp),
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(11.dp)
                                .horizontalScroll(rememberScrollState()),
                        ) {
                            cityList.forEach { city ->
                                TripCityChip(city) {
                                    val removedCityKey = entryForStoredCity(city)?.key
                                    removedCityKey?.let { key ->
                                        selectedCatalogEntries = selectedCatalogEntries - key
                                    }
                                    cities = cityList.filterNot { it == city }.joinToString(", ")
                                    newTripPhotos = newTripPhotos.map { photo ->
                                        if (photo.city == city || (removedCityKey != null && entryForStoredCity(photo.city)?.key == removedCityKey)) {
                                            photo.copy(city = "")
                                        } else {
                                            photo
                                        }
                                    }
                                }
                            }
                            Text(
                                localized("+ добавить…", "+ add…", "+ add…", "+ hinzufügen…"),
                                color = secondaryTextColor(),
                                fontFamily = Manrope,
                                fontWeight = FontWeight.W600,
                                fontSize = 14.sp,
                            )
                        }
                    }
                }
            }

            CreateTripPhotoCityAssignments(
                language = language,
                photos = newTripPhotos,
                cityOptions = cityList,
                onCityChange = { uri, city ->
                    newTripPhotos = newTripPhotos.map { photo ->
                        if (photo.uri == uri) photo.copy(city = city) else photo
                    }
                },
            )

            if (message != null) {
                Text(message!!, color = Color(0xFFE0524B), fontFamily = Manrope, fontWeight = FontWeight.W700, fontSize = 13.sp, modifier = Modifier.padding(top = 12.dp))
            }
            Button(
                onClick = ::save,
                enabled = !saving && validateCreateTripRequiredFields(title, startDate, endDate, cityList) == null,
                colors = ButtonDefaults.buttonColors(containerColor = primaryColor(), contentColor = primaryContentColor()),
                shape = RoundedCornerShape(15.dp),
                contentPadding = androidx.compose.foundation.layout.PaddingValues(),
                modifier = Modifier.fillMaxWidth().padding(top = 26.dp).height(54.dp),
            ) {
                Text(if (saving) localized("Создаём…", "Creating…", "Creando…", "Wird erstellt…") else localized("Создать путешествие", "Create trip", "Crear viaje", "Reise erstellen"), fontFamily = Manrope, fontWeight = FontWeight.W800, fontSize = 16.sp)
            }
        }
    }

    if (cityDialogOpen) {
        ModalBottomSheet(
            onDismissRequest = {
                cityDialogOpen = false
                citySearch = ""
            },
            sheetState = rememberModalBottomSheetState(skipPartiallyExpanded = true),
            containerColor = cardSurfaceColor(),
            tonalElevation = 0.dp,
            dragHandle = {
                Box(
                    modifier = Modifier
                        .padding(vertical = 12.dp)
                        .width(43.dp)
                        .height(5.dp)
                        .clip(RoundedCornerShape(999.dp))
                        .background(if (darkTheme) OdysseyDarkMuted else Color(0xFF9996A5)),
                )
            },
        ) {
            Column(
                modifier = Modifier
                    .fillMaxWidth()
                    .fillMaxHeight()
                    .windowInsetsPadding(WindowInsets.navigationBars)
                    .imePadding()
                    .padding(start = 18.dp, end = 18.dp, bottom = 18.dp),
            ) {
                Row(verticalAlignment = Alignment.CenterVertically, modifier = Modifier.fillMaxWidth()) {
                    Column(modifier = Modifier.weight(1f)) {
                        Text(
                            localized("Выберите города", "Choose cities", "Elige ciudades", "Städte auswählen"),
                            color = contentTextColor(),
                            fontFamily = Manrope,
                            fontWeight = FontWeight.W800,
                            fontSize = 22.sp,
                        )
                        Text(
                            localized("Добавьте один или несколько городов", "Add one or more cities", "Añade una o varias ciudades", "Fügen Sie eine oder mehrere Städte hinzu"),
                            color = secondaryTextColor(),
                            fontFamily = Manrope,
                            fontWeight = FontWeight.W500,
                            fontSize = 12.sp,
                            modifier = Modifier.padding(top = 3.dp),
                        )
                    }
                    Box(
                        contentAlignment = Alignment.Center,
                        modifier = Modifier
                            .size(36.dp)
                            .clip(CircleShape)
                            .background(if (darkTheme) OdysseyDarkTint else Color(0xFFEEEDF4))
                            .clickable {
                                cityDialogOpen = false
                                citySearch = ""
                            },
                    ) {
                        Icon(
                            Icons.Filled.Close,
                            contentDescription = localized("Закрыть", "Close", "Cerrar", "Schließen"),
                            tint = secondaryTextColor(),
                            modifier = Modifier.size(19.dp),
                        )
                    }
                }

                OutlinedTextField(
                    value = citySearch,
                    onValueChange = { citySearch = it },
                    singleLine = true,
                    placeholder = {
                        Text(
                            localized("Поиск города", "Search city", "Buscar ciudad", "Stadt suchen"),
                            color = secondaryTextColor(),
                            fontFamily = Manrope,
                            fontWeight = FontWeight.W500,
                        )
                    },
                    shape = RoundedCornerShape(13.dp),
                    colors = OutlinedTextFieldDefaults.colors(
                        focusedBorderColor = primaryColor(),
                        unfocusedBorderColor = contentBorderColor(),
                        focusedContainerColor = cardSurfaceColor(),
                        unfocusedContainerColor = cardSurfaceColor(),
                    ),
                    modifier = Modifier.fillMaxWidth().padding(top = 16.dp),
                )

                if (citySearchLoading) {
                    Box(
                        contentAlignment = Alignment.Center,
                        modifier = Modifier.fillMaxWidth().height(150.dp),
                    ) {
                        CircularProgressIndicator(color = primaryColor(), strokeWidth = 2.5.dp)
                    }
                } else if (filteredCatalogCities.isEmpty()) {
                    Text(
                        localized("Ничего не найдено", "No cities found", "No se encontraron ciudades", "Keine Städte gefunden"),
                        color = secondaryTextColor(),
                        fontFamily = Manrope,
                        fontWeight = FontWeight.W600,
                        fontSize = 14.sp,
                        modifier = Modifier.padding(vertical = 28.dp),
                    )
                } else {
                    LazyColumn(
                        verticalArrangement = Arrangement.spacedBy(7.dp),
                        modifier = Modifier
                            .fillMaxWidth()
                            .weight(1f)
                            .padding(top = 14.dp),
                    ) {
                        items(filteredCatalogCities, key = { it.key }) { entry ->
                            val selected = entry.key in selectedCityKeys
                            val localizedName = entry.localized(language)
                            val normalizedName = normalizeCityAlias(localizedName)
                            val countryLabel = entry.countryName.ifBlank { entry.countryCode }
                            val sameName = normalizedName in duplicateCityNames
                            val sameNameAndCountry = "${normalizedName}|${entry.countryCode.uppercase(Locale.ROOT)}" in duplicateCityCountryNames
                            val displayName = if (sameName && countryLabel.isNotBlank()) {
                                "$localizedName — $countryLabel"
                            } else {
                                localizedName
                            }
                            val secondaryLabel = if (sameNameAndCountry) {
                                val coordinates = String.format(Locale.US, "%.3f, %.3f", entry.latitude, entry.longitude)
                                listOf(countryLabel, coordinates).filter(String::isNotBlank).joinToString(" · ")
                            } else if (!sameName) {
                                countryLabel
                            } else {
                                ""
                            }
                            Row(
                                verticalAlignment = Alignment.CenterVertically,
                                horizontalArrangement = Arrangement.spacedBy(11.dp),
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .clip(RoundedCornerShape(13.dp))
                                    .background(if (selected) tintedSurfaceColor() else cardSurfaceColor())
                                    .border(1.dp, if (selected) primaryColor().copy(alpha = 0.45f) else contentBorderColor(), RoundedCornerShape(13.dp))
                                    .clickable { toggleCatalogCity(entry) }
                                    .padding(horizontal = 12.dp, vertical = 10.dp),
                            ) {
                                Text(countryFlag(entry.countryCode) ?: cityFlag(entry.russian), fontSize = 20.sp)
                                Column(modifier = Modifier.weight(1f)) {
                                    Text(
                                        displayName,
                                        color = contentTextColor(),
                                        fontFamily = Manrope,
                                        fontWeight = FontWeight.W700,
                                        fontSize = 14.sp,
                                    )
                                    if (secondaryLabel.isNotBlank()) {
                                        Text(
                                            secondaryLabel,
                                            color = secondaryTextColor(),
                                            fontFamily = Manrope,
                                            fontWeight = FontWeight.W500,
                                            fontSize = 11.sp,
                                            maxLines = 1,
                                            overflow = TextOverflow.Ellipsis,
                                        )
                                    }
                                }
                                if (selected) {
                                    Box(
                                        contentAlignment = Alignment.Center,
                                        modifier = Modifier
                                            .size(23.dp)
                                            .clip(CircleShape)
                                            .background(primaryColor()),
                                    ) {
                                        Icon(Icons.Filled.Check, contentDescription = null, tint = primaryContentColor(), modifier = Modifier.size(15.dp))
                                    }
                                } else {
                                    Text("+", color = primaryColor(), fontFamily = Manrope, fontWeight = FontWeight.W800, fontSize = 22.sp)
                                }
                            }
                        }
                    }
                }

                Button(
                    onClick = {
                        cityDialogOpen = false
                        citySearch = ""
                    },
                    colors = ButtonDefaults.buttonColors(containerColor = primaryColor(), contentColor = primaryContentColor()),
                    shape = RoundedCornerShape(14.dp),
                    contentPadding = androidx.compose.foundation.layout.PaddingValues(),
                    modifier = Modifier.fillMaxWidth().padding(top = 16.dp).height(52.dp),
                ) {
                    Text(
                        localized("Готово", "Done", "Listo", "Fertig"),
                        fontFamily = Manrope,
                        fontWeight = FontWeight.W800,
                        fontSize = 15.sp,
                    )
                }
                Text(
                    "Данные городов: Countries States Cities Database · ODbL 1.0",
                    color = secondaryTextColor(),
                    fontFamily = Manrope,
                    fontWeight = FontWeight.W500,
                    fontSize = 9.sp,
                    modifier = Modifier.padding(top = 8.dp),
                )
            }
        }
    }
    datePickerTarget?.let { target ->
        val pickingStart = target == "start"
        TripCreationCalendarDialog(
            title = localized("Выберите дату", "Choose date", "Elige una fecha", "Datum auswählen"),
            initialValue = if (pickingStart) startDate else endDate.ifBlank { startDate },
            minimumDate = if (pickingStart) null else parseRouteDate(startDate),
            onDismiss = { datePickerTarget = null },
            onConfirm = { selectedDate ->
                if (pickingStart) startDate = selectedDate else endDate = selectedDate
                datePickerTarget = null
            },
        )
    }
}

@Composable
private fun CreateTripPhotoCityAssignments(
    language: String,
    photos: List<NewTripPhoto>,
    cityOptions: List<String>,
    onCityChange: (Uri, String) -> Unit,
) {
    if (photos.isEmpty()) return

    val darkTheme = LocalDarkTheme.current
    var expandedPhoto by remember { mutableStateOf<Uri?>(null) }
    val rowShape = RoundedCornerShape(14.dp)

    Column(modifier = Modifier.padding(top = 16.dp)) {
        Text(
            localized(language, "Фото по городам", "Photos by city", "Fotos por ciudad", "Fotos nach Stadt"),
            color = secondaryTextColor(),
            fontFamily = Manrope,
            fontWeight = FontWeight.W700,
            fontSize = 12.sp,
        )
        Text(
            localized(
                language,
                "Укажите город для фото — оно появится в карточке погоды этого города",
                "Choose a city for each photo — it will appear on that city's weather card",
                "Elige una ciudad para cada foto: aparecerá en la tarjeta del tiempo de esa ciudad",
                "Wähle für jedes Foto eine Stadt — es erscheint auf der Wetterkarte dieser Stadt",
            ),
            color = secondaryTextColor(),
            fontFamily = Manrope,
            fontWeight = FontWeight.W500,
            fontSize = 10.sp,
            lineHeight = 14.sp,
            modifier = Modifier.padding(top = 4.dp, bottom = 8.dp),
        )
        photos.forEachIndexed { index, photo ->
            Box(
                modifier = Modifier
                    .fillMaxWidth()
                    .clip(rowShape)
                    .background(if (darkTheme) OdysseyDarkSurface else cardSurfaceColor())
                    .border(1.dp, if (darkTheme) OdysseyDarkBorder else contentBorderColor(), rowShape)
                    .padding(9.dp),
            ) {
                Row(verticalAlignment = Alignment.CenterVertically) {
                    AsyncImage(
                        model = photo.uri,
                        contentDescription = localized(language, "Фото путешествия", "Trip photo", "Foto del viaje", "Reisefoto"),
                        contentScale = androidx.compose.ui.layout.ContentScale.Crop,
                        modifier = Modifier.size(56.dp).clip(RoundedCornerShape(10.dp)),
                    )
                    Column(modifier = Modifier.weight(1f).padding(start = 10.dp)) {
                        Text(
                            if (index == 0) {
                                localized(language, "Обложка путешествия", "Trip cover", "Portada del viaje", "Reisetitelbild")
                            } else {
                                localized(language, "Фото ${index + 1}", "Photo ${index + 1}", "Foto ${index + 1}", "Foto ${index + 1}")
                            },
                            color = contentTextColor(),
                            fontFamily = Manrope,
                            fontWeight = FontWeight.W700,
                            fontSize = 12.sp,
                        )
                        Box {
                            Row(
                                verticalAlignment = Alignment.CenterVertically,
                                modifier = Modifier
                                    .padding(top = 5.dp)
                                    .clip(RoundedCornerShape(9.dp))
                                    .background(if (darkTheme) OdysseyDarkTint else tintedSurfaceColor())
                                    .clickable(enabled = cityOptions.isNotEmpty()) { expandedPhoto = photo.uri }
                                    .padding(horizontal = 9.dp, vertical = 6.dp),
                            ) {
                                Text(
                                    photo.city.ifBlank {
                                        if (cityOptions.isEmpty()) {
                                            localized(language, "Сначала добавьте города", "Add cities first", "Añade ciudades primero", "Füge zuerst Städte hinzu")
                                        } else {
                                            localized(language, "Выбрать город", "Choose a city", "Elegir ciudad", "Stadt auswählen")
                                        }
                                    },
                                    color = if (photo.city.isBlank()) secondaryTextColor() else primaryColor(),
                                    fontFamily = Manrope,
                                    fontWeight = FontWeight.W700,
                                    fontSize = 11.sp,
                                    maxLines = 1,
                                    overflow = TextOverflow.Ellipsis,
                                )
                                if (cityOptions.isNotEmpty()) {
                                    Icon(
                                        Icons.Outlined.KeyboardArrowDown,
                                        contentDescription = localized(language, "Выбрать город", "Choose a city", "Elegir ciudad", "Stadt auswählen"),
                                        tint = primaryColor(),
                                        modifier = Modifier.size(16.dp).padding(start = 2.dp),
                                    )
                                }
                            }
                            DropdownMenu(
                                expanded = expandedPhoto == photo.uri,
                                onDismissRequest = { expandedPhoto = null },
                            ) {
                                cityOptions.forEach { city ->
                                    DropdownMenuItem(
                                        text = { Text(city, fontFamily = Manrope, fontWeight = FontWeight.W600) },
                                        onClick = {
                                            onCityChange(photo.uri, city)
                                            expandedPhoto = null
                                        },
                                    )
                                }
                            }
                        }
                    }
                }
            }
            if (index < photos.lastIndex) Spacer(Modifier.height(7.dp))
        }
    }
}

