@Composable
private fun TripCityChip(city: String, onRemove: () -> Unit) {
    Row(
        verticalAlignment = Alignment.CenterVertically,
        horizontalArrangement = Arrangement.spacedBy(6.dp),
        modifier = Modifier
            .clip(RoundedCornerShape(9.dp))
            .background(tintedSurfaceColor())
            .padding(horizontal = 11.dp, vertical = 6.dp),
    ) {
        Text(city, color = primaryColor(), fontFamily = Manrope, fontWeight = FontWeight.W700, fontSize = 13.sp, lineHeight = 17.sp)
        Text("×", color = primaryColor().copy(alpha = 0.6f), fontFamily = Manrope, fontWeight = FontWeight.W800, fontSize = 14.sp, modifier = Modifier.clickable(onClick = onRemove))
    }
}

@Composable
private fun TripOverviewScreen(tripId: String, onBack: () -> Unit, onSettings: () -> Unit) {
    val darkTheme = LocalDarkTheme.current
    val language = LocalLanguage.current
    val cityCatalogContext = LocalContext.current
    val cityCatalogRepository = remember(cityCatalogContext) { CityCatalogRepository(cityCatalogContext.assets) }
    var overview by remember { mutableStateOf<TripOverview?>(null) }
    var weather by remember { mutableStateOf<Map<String, WeatherSnapshot>>(emptyMap()) }
    var loading by remember { mutableStateOf(true) }
    var tab by remember { mutableStateOf("overview") }
    var overviewEditMode by remember { mutableStateOf(false) }
    var sectionMenuOpen by remember { mutableStateOf(false) }
    var refresh by remember { mutableStateOf(0) }
    var loadError by remember { mutableStateOf<String?>(null) }
    val weatherRepository = remember { WeatherRepository() }

    DisposableEffect(weatherRepository) {
        onDispose { weatherRepository.close() }
    }

    LaunchedEffect(tripId, refresh) {
        val hadOverview = overview != null
        if (!hadOverview) loading = true
        loadError = null
        val loadedOverview = runCatching {
            SupabaseTripRepository(SupabaseProvider.clientForCurrentAuthFlow()).loadTripOverview(tripId)
        }.onFailure { loadError = it.message }.getOrNull()
        if (loadedOverview == null) {
            if (!hadOverview) overview = null
            loading = false
            return@LaunchedEffect
        }

        overview = loadedOverview
        loading = false

        loadedOverview.let { trip ->
            val routeCities = trip.overviewMapPoints.ifEmpty {
                trip.routeLegs.flatMap { listOf(it.from, it.to) }.distinct()
            }.distinct()
            val cities = trip.overviewWeatherCities.ifEmpty { routeCities }.distinct()
            val unresolvedCities = cities.filter { city ->
                trip.cityCoordinates[city] == null && cityCatalogEntry(city) == null
            }
            val catalogCoordinates = runCatching {
                cityCatalogRepository.findExact(unresolvedCities).mapValues { (_, entry) ->
                    CityLocation(entry.latitude, entry.longitude)
                }
            }.getOrDefault(emptyMap())
            weather = runCatching {
                weatherRepository.loadCurrent(cities, trip.dates, catalogCoordinates + trip.cityCoordinates)
            }.getOrDefault(emptyMap())
        }
    }

    Box(modifier = Modifier.fillMaxSize()) {
        Column(
            modifier = Modifier
                .fillMaxSize()
                .background(if (darkTheme) OdysseyDarkBackground else OdysseyBackground)
                .padding(WindowInsets.statusBars.asPaddingValues()),
        ) {
        BoxWithConstraints(modifier = Modifier.fillMaxSize()) {
            val pixelPerfectTab = tab == "restaurants" || tab == "accommodation" || tab == "budget" || tab == "pets"
            val pageScale = if (pixelPerfectTab) (maxWidth.value / 368f) else 1f
            val pageWidth = if (pixelPerfectTab) 368.dp else maxWidth
            val pageHeight = if (pixelPerfectTab) maxHeight / pageScale else maxHeight
            Column(
                modifier = Modifier
                    .width(pageWidth)
                    .height(pageHeight)
                    .offset(y = if (pixelPerfectTab) (-2).dp else 0.dp)
                    .graphicsLayer {
                        scaleX = pageScale
                        scaleY = pageScale
                        transformOrigin = TransformOrigin(0f, 0f)
                    },
            ) {
        val menuContentDescription = localized("Открыть меню", "Open menu", "Abrir menú", "Menü öffnen")
        val overviewEditContentDescription = if (overviewEditMode) {
            localized("Завершить редактирование главного экрана", "Finish editing the overview", "Finalizar la edición del inicio", "Bearbeitung der Übersicht beenden")
        } else {
            localized("Редактировать главный экран", "Edit overview", "Editar inicio", "Übersicht bearbeiten")
        }
        Row(
            verticalAlignment = Alignment.CenterVertically,
            modifier = Modifier.fillMaxWidth().height(54.dp).padding(horizontal = 16.dp),
        ) {
            Box(
                modifier = Modifier
                    .size(48.dp)
                    .offset(x = (-6).dp)
                    .semantics {
                        contentDescription = menuContentDescription
                        role = Role.Button
                    }
                    .clickable { sectionMenuOpen = true },
                contentAlignment = Alignment.Center,
            ) {
                Icon(Icons.Outlined.Menu, contentDescription = null, tint = contentTextColor(), modifier = Modifier.size(24.dp))
                }
            Column(
                horizontalAlignment = Alignment.CenterHorizontally,
                modifier = Modifier.weight(1f),
            ) {
                Text(
                    text = localizedTripTitle(overview?.title.orEmpty()),
                    color = secondaryTextColor(),
                    fontFamily = Manrope,
                    fontWeight = FontWeight.W700,
                    fontSize = 10.sp,
                    lineHeight = 14.sp,
                    style = androidx.compose.ui.text.TextStyle(platformStyle = OdysseyNoFontPadding),
                    maxLines = 1,
                    softWrap = false,
                )
                Row(verticalAlignment = Alignment.CenterVertically) {
                    Text(
                        when (tab) {
                            "overview" -> localized("Главная", "Overview", "Inicio", "Übersicht")
                            "route" -> localized("Маршрут", "Route", "Ruta", "Route")
                            "sights" -> localized("Достопримечательности", "Sights", "Lugares", "Sehenswürdigkeiten")
                            "restaurants" -> localized("Рестораны", "Restaurants", "Restaurantes", "Restaurants")
                            "accommodation" -> localized("Жильё", "Lodging", "Alojamiento", "Unterkunft")
                            "budget" -> localized("Бюджет", "Budget", "Presupuesto", "Budget")
                            "members" -> localized("Участники", "Members", "Participantes", "Teilnehmer")
                            "pets" -> localized("Питомцы", "Pets", "Mascotas", "Haustiere")
                            else -> localized("Фото", "Photos", "Fotos", "Fotos")
                        },
                        color = contentTextColor(),
                        fontFamily = Manrope,
                        fontWeight = FontWeight.W800,
                        fontSize = 15.sp,
                        lineHeight = 21.sp,
                        style = androidx.compose.ui.text.TextStyle(platformStyle = OdysseyNoFontPadding),
                        maxLines = 1,
                        softWrap = false,
                    )
                    Spacer(Modifier.width(5.dp))
                }
            }
            if (tab == "overview" && overview?.canEdit == true) {
                val editButtonShape = RoundedCornerShape(12.dp)
                val editButtonBackground = if (overviewEditMode) {
                    primaryColor()
                } else if (darkTheme) {
                    Color(0xFF2A2D3B)
                } else {
                    OdysseySurface2
                }
                val editButtonBorder = if (overviewEditMode) {
                    primaryColor()
                } else if (darkTheme) {
                    Color(0xFF3A3D4C)
                } else {
                    OdysseyBorder
                }
                val editButtonIcon = if (overviewEditMode) primaryContentColor() else Color(0xFF8E7BF5)
                Box(
                    modifier = Modifier
                        .size(48.dp)
                        .semantics {
                            contentDescription = overviewEditContentDescription
                            role = Role.Button
                        }
                        .clickable { overviewEditMode = !overviewEditMode },
                    contentAlignment = Alignment.Center,
                ) {
                    Box(
                        modifier = Modifier
                            .size(40.dp)
                            .clip(editButtonShape)
                            .background(editButtonBackground)
                            .border(1.dp, editButtonBorder, editButtonShape),
                        contentAlignment = Alignment.Center,
                    ) {
                        Icon(
                            imageVector = if (overviewEditMode) Icons.Filled.Check else Icons.Outlined.Edit,
                            contentDescription = null,
                            tint = editButtonIcon,
                            modifier = Modifier.size(19.dp),
                        )
                    }
                }
            } else {
                Spacer(Modifier.width(48.dp))
            }
        }

        if (loading) {
            TripOverviewLoading()
        } else if (overview == null) {
            Text(
                text = loadError ?: localized("Путешествие не найдено", "Trip not found", "Viaje no encontrado", "Reise nicht gefunden"),
                color = Color(0xFFE0524B),
                fontFamily = Manrope,
                fontWeight = FontWeight.W700,
                modifier = Modifier.padding(18.dp),
            )
        } else {
            when (tab) {
                "overview" -> OverviewContent(
                    tripId = tripId,
                    overview = overview!!,
                    weather = weather,
                    editMode = overviewEditMode,
                    onChanged = { refresh++ },
                )
                "route" -> TripRouteContent(tripId, overview!!, canEdit = overview!!.canEdit) { refresh++ }
                "sights" -> SightsContent(tripId, overview!!, canEdit = overview!!.canEdit) { refresh++ }
                "restaurants" -> RestaurantsContent(tripId, overview!!, canEdit = overview!!.canEdit) { refresh++ }
                "accommodation" -> AccommodationContent(tripId, overview!!, canEdit = overview!!.canEdit) { refresh++ }
                "pets" -> PetsContent(tripId, overview!!, canEdit = overview!!.canEdit) { refresh++ }
                "budget" -> BudgetContent(
                    tripId = tripId,
                    overview = overview!!,
                    canEdit = overview!!.canEdit,
                    onExpenseAdded = { refresh++ },
                    onCurrencyChanged = { selectedCurrency -> overview = overview?.copy(budgetCurrency = selectedCurrency) },
                )
                "members" -> MembersContent(tripId, overview!!, canEdit = overview!!.currentUserRole == "Владелец") { refresh++ }
                else -> PhotosContent(tripId, overview!!, canEdit = overview!!.canEdit) { refresh++ }
            }
        }
            }
        }
        }

        val closeSectionMenuDescription = localized("Закрыть меню разделов", "Close sections menu", "Cerrar menú de secciones", "Bereichsmenü schließen")
        if (sectionMenuOpen) {
            val sectionMenuShape = RoundedCornerShape(topEnd = 26.dp, bottomEnd = 26.dp)
            Box(modifier = Modifier.fillMaxSize()) {
                Box(modifier = Modifier.fillMaxSize().background(Color(0x66000000)).semantics { contentDescription = closeSectionMenuDescription; role = Role.Button }.clickable { sectionMenuOpen = false })
                Column(
                    modifier = Modifier
                        .fillMaxHeight()
                        .width(310.dp)
                        .shadow(16.dp, sectionMenuShape, clip = false, ambientColor = Color(0x24000000), spotColor = Color(0x24000000))
                        .clip(sectionMenuShape)
                        .background(cardSurfaceColor())
                        .windowInsetsPadding(WindowInsets.statusBars)
                        .windowInsetsPadding(WindowInsets.navigationBars)
                        .padding(start = 18.dp, top = 22.dp, end = 18.dp, bottom = 32.dp),
                ) {
                    Row(verticalAlignment = Alignment.CenterVertically) {
                        Box(contentAlignment = Alignment.Center, modifier = Modifier.size(44.dp).background(primaryColor(), RoundedCornerShape(13.dp))) {
                            Icon(Icons.Outlined.Explore, contentDescription = null, tint = primaryContentColor(), modifier = Modifier.size(22.dp))
                        }
                        Column(modifier = Modifier.weight(1f).padding(start = 10.dp, top = 7.dp)) {
                            Text(localizedTripTitle(overview?.title.orEmpty()), color = contentTextColor(), fontFamily = Manrope, fontWeight = FontWeight.W800, fontSize = 17.sp, maxLines = 1, overflow = TextOverflow.Ellipsis)
                        }
                    }
                    Spacer(Modifier.fillMaxWidth().height(1.dp).background(contentBorderColor()))
                    Spacer(Modifier.height(12.dp))
                    Column(modifier = Modifier.fillMaxWidth(), verticalArrangement = Arrangement.spacedBy(2.dp)) {
                        listOf(
                        Triple("overview", Icons.Outlined.Explore, localized("Главная", "Overview", "Inicio", "Übersicht")),
                        Triple("route", Icons.Outlined.Share, localized("Маршрут", "Route", "Ruta", "Route")),
                        Triple("sights", Icons.Outlined.LocationOn, localized("Достопримечательности", "Sights", "Lugares", "Sehenswürdigkeiten")),
                        Triple("restaurants", Icons.Outlined.Restaurant, localized("Рестораны", "Restaurants", "Restaurantes", "Restaurants")),
                        Triple("accommodation", Icons.Outlined.Hotel, localized("Жильё", "Lodging", "Alojamiento", "Unterkunft")),
                        Triple("pets", Icons.Outlined.FavoriteBorder, localized("Питомцы", "Pets", "Mascotas", "Haustiere")),
                        Triple("budget", Icons.Outlined.AccountBalanceWallet, localized("Бюджет", "Budget", "Presupuesto", "Budget")),
                        Triple("members", Icons.Outlined.Group, localized("Участники", "Members", "Participantes", "Teilnehmer")),
                        Triple("photos", Icons.Outlined.Image, localized("Фото", "Photos", "Fotos", "Fotos")),
                        ).forEach { (entry, icon, label) ->
                        val selected = tab == entry
                        Row(verticalAlignment = Alignment.CenterVertically, modifier = Modifier.fillMaxWidth().background(if (selected) tintedSurfaceColor() else Color.Transparent, RoundedCornerShape(14.dp)).clickable { tab = entry; overviewEditMode = false; sectionMenuOpen = false }.padding(horizontal = 14.dp, vertical = 13.dp)) {
                            Icon(icon, contentDescription = null, tint = if (selected) primaryColor() else secondaryTextColor(), modifier = Modifier.size(20.dp))
                            Text(label, color = if (selected) primaryColor() else contentTextColor(), fontFamily = Manrope, fontWeight = if (selected) FontWeight.W800 else FontWeight.W700, fontSize = 14.5.sp, maxLines = 1, softWrap = false, overflow = TextOverflow.Ellipsis, modifier = Modifier.padding(start = 14.dp))
                        }
                    }
                    Spacer(Modifier.weight(1f))
                    Row(
                        verticalAlignment = Alignment.CenterVertically,
                        modifier = Modifier
                            .fillMaxWidth()
                            .clip(RoundedCornerShape(14.dp))
                            .background(tintedSurfaceColor())
                            .clickable { sectionMenuOpen = false; onBack() }
                            .padding(horizontal = 14.dp, vertical = 13.dp),
                    ) {
                        Text("↩", color = primaryColor(), fontFamily = Manrope, fontWeight = FontWeight.W700, fontSize = 22.sp, lineHeight = 22.sp, modifier = Modifier.width(20.dp))
                        Text(localized("Мои путешествия", "My trips", "Mis viajes", "Meine Reisen"), color = primaryColor(), fontFamily = Manrope, fontWeight = FontWeight.W800, fontSize = 15.5.sp, modifier = Modifier.padding(start = 14.dp))
                    }
                    Spacer(Modifier.height(5.dp))
                    Row(
                        verticalAlignment = Alignment.CenterVertically,
                        modifier = Modifier
                            .fillMaxWidth()
                            .clip(RoundedCornerShape(14.dp))
                            .clickable { sectionMenuOpen = false; onSettings() }
                            .padding(horizontal = 14.dp, vertical = 13.dp),
                    ) {
                        Icon(Icons.Outlined.Settings, contentDescription = null, tint = secondaryTextColor(), modifier = Modifier.size(20.dp))
                        Text(localized("Настройки", "Settings", "Ajustes", "Einstellungen"), color = contentTextColor(), fontFamily = Manrope, fontWeight = FontWeight.W700, fontSize = 15.5.sp, modifier = Modifier.padding(start = 14.dp))
                    }
                    }
                }
            }
        }
    }
}

@Composable
private fun TripTabs(selected: String, onSelect: (String) -> Unit) {
    val darkTheme = LocalDarkTheme.current
    val activeColor = primaryColor()
    Row(
        horizontalArrangement = Arrangement.spacedBy(20.dp),
        modifier = Modifier.fillMaxWidth().background(if (darkTheme) OdysseyDarkSurface else Color(0xFFEEF0F3)).horizontalScroll(rememberScrollState()).padding(horizontal = 18.dp),
    ) {
        listOf(
            "overview" to localized("Главная", "Overview", "Inicio", "Übersicht"),
            "route" to localized("Маршрут", "Route", "Ruta", "Route"),
            "sights" to localized("Достопримечательности", "Sights", "Lugares", "Sehenswürdigkeiten"),
            "restaurants" to localized("Рестораны", "Restaurants", "Restaurantes", "Restaurants"),
            "accommodation" to localized("Жильё", "Lodging", "Alojamiento", "Unterkunft"),
            "pets" to localized("Питомцы", "Pets", "Mascotas", "Haustiere"),
            "budget" to localized("Бюджет", "Budget", "Presupuesto", "Budget"),
            "members" to localized("Участники", "Members", "Participantes", "Teilnehmer"),
            "photos" to localized("Фото", "Photos", "Fotos", "Fotos"),
        ).forEach { (id, label) ->
            val active = selected == id
            Text(
                text = label,
                color = if (active) contentTextColor() else secondaryTextColor(),
                fontFamily = Manrope,
                fontWeight = FontWeight.W800,
                fontSize = 13.sp,
                modifier = Modifier
                    .clickable { onSelect(id) }
                    .drawBehind {
                        if (active) drawLine(activeColor, Offset(0f, size.height - 1.dp.toPx()), Offset(size.width, size.height - 1.dp.toPx()), strokeWidth = 3.dp.toPx())
                    }
                    .padding(horizontal = 3.dp, vertical = 13.dp),
            )
        }
    }
}

@Composable
@OptIn(ExperimentalMaterial3Api::class)
private fun SightsContent(tripId: String, overview: TripOverview, canEdit: Boolean = true, onSightUpdated: () -> Unit) {
    val clipboard = androidx.compose.ui.platform.LocalClipboardManager.current
    val darkTheme = LocalDarkTheme.current
    val language = LocalLanguage.current
    val sights = overview.sights.sortedWith(compareBy<com.odyssey.travelplanner.data.Sight> { sightRouteDay(it.walkDay) }.thenBy { it.walkOrder })
    val initialRouteCity = listOf(
        sights.firstOrNull()?.city,
        overview.routeLegs.firstOrNull()?.to,
        overview.cities.firstOrNull(),
        overview.overviewMapPoints.firstOrNull(),
    ).firstOrNull { !it.isNullOrBlank() }.orEmpty()
    var routeDay by remember(tripId) { mutableStateOf(sights.firstOrNull()?.walkDay?.let(::sightRouteDay) ?: 1) }
    var dayMenuOpen by remember { mutableStateOf(false) }
    var creatingDay by remember { mutableStateOf(false) }
    val dayCities = remember(sights, overview.routeLegs, initialRouteCity) {
        val totalDays = maxOf(
            sights.maxOfOrNull { sightRouteDay(it.walkDay) } ?: 1,
            overview.routeDayCount,
            overview.routeLegs.maxOfOrNull { routeLegDayNumber(it, overview.routeLegs) } ?: overview.routeLegs.size,
        )
        (1..totalDays).map { day ->
            sights.firstOrNull { sightRouteDay(it.walkDay) == day }?.city?.takeIf(String::isNotBlank)
                ?: overview.routeLegs.firstOrNull { routeLegDayNumber(it, overview.routeLegs) == day }?.to
                ?: initialRouteCity
        }
    }
    val selectedDayCity = dayCities.getOrNull(routeDay - 1).orEmpty().ifBlank { initialRouteCity }
    val visibleSights = sights.filter { sightRouteDay(it.walkDay) == routeDay }
    var selectedSightId by remember(tripId, routeDay) { mutableStateOf<String?>(null) }
    val selectedLeg = overview.routeLegs.firstOrNull { routeLegDayNumber(it, overview.routeLegs) == routeDay }
    val mapCities = selectedLeg?.let { listOf(it.from, it.to) } ?: listOf(selectedDayCity)
    val sightRoutePoints = visibleSights.mapNotNull { sight -> sight.longitude?.let { longitude -> sight.latitude?.let { latitude -> Point.fromLngLat(longitude, latitude) } } }
    val sightMapEntries = visibleSights.mapNotNull { sight ->
        val point = sight.longitude?.let { longitude -> sight.latitude?.let { latitude -> Point.fromLngLat(longitude, latitude) } }
            ?: mapCoordinate(sight.city)
        point?.let { sight.id to it }
    }
    val sightMapPoints = sightMapEntries.map { it.second }
    val selectedSightMapIndex = sightMapEntries.indexOfFirst { it.first == selectedSightId }.takeIf { it >= 0 }
    val routeShareUrl = if (sightRoutePoints.size > 1) {
        val stops = sightRoutePoints.map { "${it.latitude()},${it.longitude()}" }
        "https://www.google.com/maps/dir/?api=1&origin=${stops.first()}&destination=${stops.last()}&waypoints=${stops.drop(1).dropLast(1).joinToString("|")}" 
    } else "https://www.google.com/maps/search/?api=1&query=${Uri.encode(selectedDayCity)}"
    var editingSight by remember { mutableStateOf<com.odyssey.travelplanner.data.Sight?>(null) }
    var fullScreenSight by remember { mutableStateOf<com.odyssey.travelplanner.data.Sight?>(null) }
    var editingDay by remember { mutableStateOf(false) }
    val missingSightDescriptionKey = remember(sights) {
        sights
            .filter { isPlaceholderSightDescription(it.description) }
            .map { sightDescriptionLookupKey(it.city, it.name) }
            .sorted()
            .joinToString("|")
    }
    var sightDescriptionOverrides by remember(tripId, language) { mutableStateOf<Map<String, String>>(emptyMap()) }
    LaunchedEffect(tripId, language, missingSightDescriptionKey) {
        sightDescriptionOverrides = emptyMap()
        if (missingSightDescriptionKey.isBlank()) return@LaunchedEffect

        val missingSights = sights.filter { isPlaceholderSightDescription(it.description) }
        val repository = SightCatalogRepository(SupabaseProvider.clientForCurrentAuthFlow())
        val resolved = mutableMapOf<String, String>()
        missingSights
            .groupBy { catalogCityName(it.city) }
            .filterKeys(String::isNotBlank)
            .forEach { (cityName, citySights) ->
                val entries = runCatching {
                    repository.searchWithLiveRatings(city = cityName, query = "", language = language, limit = 60).entries
                }.getOrElse { emptyList() }
                entries.forEach { entry ->
                    val description = entry.description(language).trim()
                    if (isPlaceholderSightDescription(description)) return@forEach
                    citySights.firstOrNull { sight -> sightDescriptionNameMatches(sight.name, entry) }
                        ?.let { sight -> resolved[sightDescriptionLookupKey(sight.city, sight.name)] = description }
                }
            }
        sightDescriptionOverrides = resolved
    }
    val visibleSightCatalogKey = visibleSights.joinToString("|") { "${it.id}:${it.name}:${it.city}" }
    var sightCatalogEntries by remember(tripId, language) { mutableStateOf<List<SightCatalogEntry>>(emptyList()) }
    LaunchedEffect(tripId, language, selectedDayCity, visibleSightCatalogKey) {
        sightCatalogEntries = emptyList()
        if (selectedDayCity.isBlank() || visibleSights.isEmpty()) return@LaunchedEffect

        val repository = SightCatalogRepository(SupabaseProvider.clientForCurrentAuthFlow())
        sightCatalogEntries = runCatching {
            repository.searchWithLiveRatings(
                city = selectedDayCity,
                query = "",
                language = language,
                limit = 60,
            ).entries
        }.getOrElse { emptyList() }
    }
    val visibleSightsWithDescriptions = visibleSights.map { sight ->
        val override = sightDescriptionOverrides[sightDescriptionLookupKey(sight.city, sight.name)]
        if (isPlaceholderSightDescription(sight.description) && !override.isNullOrBlank()) {
            sight.copy(description = override)
        } else {
            sight
        }
    }
    val sightCatalogById = visibleSightsWithDescriptions.associate { sight ->
        sight.id to sightCatalogEntries.firstOrNull { entry -> sightDescriptionNameMatches(sight.name, entry) }
    }
    LazyColumn(
        contentPadding = androidx.compose.foundation.layout.PaddingValues(
            start = 18.dp,
            top = 18.dp,
            end = 18.dp,
            bottom = 30.dp + WindowInsets.navigationBars.asPaddingValues().calculateBottomPadding(),
        ),
        verticalArrangement = Arrangement.spacedBy(12.dp),
        modifier = Modifier.fillMaxSize(),
    ) {
        item {
            Text(
                "${localizedCityName(selectedDayCity).uppercase()} · ${localized("ДЕНЬ", "DAY", "DÍA", "TAG")} $routeDay",
                color = primaryColor(),
                fontFamily = Manrope,
                fontWeight = FontWeight.W800,
                fontSize = 11.sp,
                lineHeight = 14.sp,
                letterSpacing = 0.66.sp,
                style = androidx.compose.ui.text.TextStyle(platformStyle = OdysseyNoFontPadding),
            )
            Spacer(Modifier.height(16.dp))
            Box(modifier = Modifier.fillMaxWidth()) {
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .height(68.dp)
                    .shadow(4.dp, RoundedCornerShape(17.dp), clip = false, ambientColor = Color(0x0D141428), spotColor = Color(0x0D141428))
                    .clip(RoundedCornerShape(17.dp))
                    .background(cardSurfaceColor())
                    .border(1.dp, contentBorderColor(), RoundedCornerShape(17.dp))
                    .padding(horizontal = 12.dp, vertical = 10.dp),
                verticalAlignment = Alignment.CenterVertically,
                horizontalArrangement = Arrangement.spacedBy(13.dp),
            ) {
                Box(modifier = Modifier.size(46.dp).shadow(4.dp, RoundedCornerShape(13.dp), clip = false, ambientColor = Color(0x4D6C5CE7), spotColor = Color(0x4D6C5CE7)).clip(RoundedCornerShape(13.dp)).background(primaryColor()), contentAlignment = Alignment.Center) {
                    Column(horizontalAlignment = Alignment.CenterHorizontally, verticalArrangement = Arrangement.Center) {
                        Text(
                            routeDay.toString(),
                            color = primaryContentColor(),
                            fontFamily = Manrope,
                            fontWeight = FontWeight.W800,
                            fontSize = 17.sp,
                            lineHeight = 17.sp,
                            style = androidx.compose.ui.text.TextStyle(platformStyle = OdysseyNoFontPadding),
                        )
                        Text(
                            localized("ДЕНЬ", "DAY", "DÍA", "TAG"),
                            color = primaryContentColor().copy(alpha = 0.8f),
                            fontFamily = Manrope,
                            fontWeight = FontWeight.W800,
                            fontSize = 7.sp,
                            lineHeight = 9.sp,
                            letterSpacing = 0.7.sp,
                            style = androidx.compose.ui.text.TextStyle(platformStyle = OdysseyNoFontPadding),
