                Text(pendingName, color = contentTextColor(), fontFamily = Manrope, fontWeight = FontWeight.W800, fontSize = 13.sp, lineHeight = 18.sp, style = androidx.compose.ui.text.TextStyle(platformStyle = OdysseyNoFontPadding), modifier = Modifier.weight(1f).padding(start = 12.dp), maxLines = 2, overflow = TextOverflow.Ellipsis)
                Row(horizontalArrangement = Arrangement.spacedBy(6.dp)) {
                    RouteOrderButton(Icons.Outlined.KeyboardArrowUp, index > 0, localized("Переместить вверх", "Move up", "Mover arriba", "Nach oben")) {
                        val reordered = placeNames.toMutableList()
                        val moved = reordered.removeAt(index)
                        reordered.add(index - 1, moved)
                        placeNames = reordered
                    }
                    RouteOrderButton(Icons.Outlined.KeyboardArrowDown, index < placeNames.lastIndex, localized("Переместить вниз", "Move down", "Mover abajo", "Nach unten")) {
                        val reordered = placeNames.toMutableList()
                        val moved = reordered.removeAt(index)
                        reordered.add(index + 1, moved)
                        placeNames = reordered
                    }
                    Text("×", color = Color(0xFFFF6B65), fontSize = 22.sp, modifier = Modifier.padding(start = 4.dp).clickable { placeNames = placeNames.filterIndexed { itemIndex, _ -> itemIndex != index } })
                }
            }
        }
        if (message != null) Text(message!!, color = Color(0xFFE0524B), fontFamily = Manrope, fontWeight = FontWeight.W700, fontSize = 12.sp)
        Button(onClick = {
            scope.launch {
                saving = true
                runCatching {
                    val repository = SupabaseTripRepository(SupabaseProvider.clientForCurrentAuthFlow())
                    val namesToAdd = daySightNamesToSave(placeNames, placeName)
                    require(namesToAdd.isNotEmpty()) {
                        localized(language, "Добавьте хотя бы одну достопримечательность", "Add at least one sight", "Añada al menos un lugar", "Fügen Sie mindestens einen Ort hinzu")
                    }
                    val targetDay = dayNumber.toIntOrNull()?.takeIf { it > 0 } ?: day
                    namesToAdd.forEach { sightName ->
                        repository.addSightDetails(tripId, sightName, city, "достопримечательности", "", targetDay, link = "")
                    }
                }.onSuccess { onSaved(); onClose() }.onFailure {
                    message = localizedFailure(language, it, localized(language, "Не удалось сохранить день", "Could not save day", "No se pudo guardar el día", "Tag konnte nicht gespeichert werden"))
                }
                saving = false
            }
        }, enabled = !saving && city.isNotBlank(), modifier = Modifier.fillMaxWidth().height(54.dp).padding(bottom = 5.dp), colors = ButtonDefaults.buttonColors(containerColor = primaryColor(), contentColor = primaryContentColor()), shape = RoundedCornerShape(14.dp)) { Text(if (saving) localized("Сохраняем…", "Saving…", "Guardando…", "Wird gespeichert…") else localized("Сохранить день", "Save day", "Guardar día", "Tag speichern"), fontFamily = Manrope, fontWeight = FontWeight.W800) }
    }
}

@Composable
@OptIn(ExperimentalMaterial3Api::class)
private fun EditDaySheet(
    tripId: String,
    day: Int,
    city: String,
    sights: List<Sight>,
    allSights: List<Sight>,
    darkTheme: Boolean,
    onClose: () -> Unit,
    onSaved: () -> Unit,
    onDeleted: () -> Unit,
) {
    var addingSight by remember { mutableStateOf(false) }
    var catalogOpen by remember { mutableStateOf(false) }
    var deletingSightId by remember { mutableStateOf<String?>(null) }
    var deleteDayDialogOpen by remember { mutableStateOf(false) }
    var deletingDay by remember { mutableStateOf(false) }
    var deleteDayError by remember { mutableStateOf<String?>(null) }
    var message by remember { mutableStateOf<String?>(null) }
    var orderedSights by remember(day, sights) { mutableStateOf(sights) }
    var reorderingSightId by remember { mutableStateOf<String?>(null) }
    val language = LocalLanguage.current
    val scope = rememberCoroutineScope()
    val sheetContentTextColor = if (darkTheme) OdysseyDarkText else OdysseyText
    val sheetSecondaryTextColor = if (darkTheme) OdysseyDarkSubtext else OdysseySubtext
    val sheetSecondarySurfaceColor = if (darkTheme) OdysseyDarkSurface2 else OdysseySurface2
    Column(
        modifier = Modifier
            .fillMaxWidth()
            .fillMaxHeight(0.94f)
            .windowInsetsPadding(WindowInsets.navigationBars)
            .imePadding(),
    ) {
        Column(
            modifier = Modifier
                .weight(1f)
                .fillMaxWidth()
                .verticalScroll(rememberScrollState())
                .padding(horizontal = 16.dp, vertical = 6.dp),
            verticalArrangement = Arrangement.spacedBy(10.dp),
        ) {
        Row(verticalAlignment = Alignment.CenterVertically) {
            Text(localized("Редактировать день", "Edit day", "Editar día", "Tag bearbeiten"), color = sheetContentTextColor, fontFamily = Manrope, fontWeight = FontWeight.W800, fontSize = 22.5.sp)
            Spacer(Modifier.weight(1f))
            Box(modifier = Modifier.size(36.dp).clip(CircleShape).background(sheetSecondarySurfaceColor).clickable { onClose() }, contentAlignment = Alignment.Center) { Icon(Icons.Filled.Close, contentDescription = localized("Закрыть", "Close", "Cerrar", "Schließen"), tint = sheetSecondaryTextColor, modifier = Modifier.size(18.dp)) }
        }
        Row(horizontalArrangement = Arrangement.spacedBy(12.dp)) {
            RouteEditorField(localized("День №", "Day no.", "Día nº", "Tag Nr."), day.toString(), {}, Modifier.width(74.dp))
            RouteEditorField(localized("Город", "City", "Ciudad", "Stadt"), localizedCityName(city), {}, Modifier.weight(1f))
        }
        Text(localized("ДОСТОПРИМЕЧАТЕЛЬНОСТИ", "SIGHTS", "LUGARES", "SEHENSWÜRDIGKEITEN"), color = sheetSecondaryTextColor, fontFamily = Manrope, fontWeight = FontWeight.W800, fontSize = 10.7.sp, modifier = Modifier.padding(top = 6.dp))
        if (orderedSights.size > 1) {
            Row(
                verticalAlignment = Alignment.CenterVertically,
                modifier = Modifier
                    .fillMaxWidth()
                    .clip(RoundedCornerShape(14.dp))
                    .background(tintedSurfaceColor())
                    .padding(horizontal = 14.dp, vertical = 11.dp),
            ) {
                Text("↕", color = primaryColor(), fontFamily = Manrope, fontWeight = FontWeight.W800, fontSize = 22.sp, lineHeight = 22.sp)
                Column(modifier = Modifier.weight(1f).padding(start = 11.dp)) {
                    Text(
                        localized("Изменить порядок мест", "Change place order", "Cambiar orden de lugares", "Reihenfolge der Orte ändern"),
                        color = sheetContentTextColor,
                        fontFamily = Manrope,
                        fontWeight = FontWeight.W800,
                        fontSize = 13.sp,
                    )
                    Text(
                        localized("Переместите достопримечательности внутри дня", "Move sights within this day", "Mueva los lugares dentro del día", "Orte innerhalb des Tages verschieben"),
                        color = sheetSecondaryTextColor,
                        fontFamily = Manrope,
                        fontWeight = FontWeight.W600,
                        fontSize = 11.sp,
                        modifier = Modifier.padding(top = 2.dp),
                    )
                }
            }
        }
        if (message != null) {
            Text(message!!, color = Color(0xFFE0524B), fontFamily = Manrope, fontWeight = FontWeight.W700, fontSize = 12.sp)
        }
        orderedSights.forEachIndexed { index, sight ->
            Row(modifier = Modifier.fillMaxWidth().height(72.dp).clip(RoundedCornerShape(14.dp)).background(sheetSecondarySurfaceColor).padding(10.dp), verticalAlignment = Alignment.CenterVertically) {
                SightPhoto(sight, Modifier.size(52.dp).clip(RoundedCornerShape(11.dp)))
                Column(modifier = Modifier.weight(1f).padding(start = 11.dp)) { Text(localizedSightName(sight.name), color = sheetContentTextColor, fontFamily = Manrope, fontWeight = FontWeight.W800, fontSize = 14.sp, maxLines = 1, overflow = TextOverflow.Ellipsis); Text(localizedSightInfo(sight.name, sight.description, sight.category), color = sheetSecondaryTextColor, fontFamily = Manrope, fontWeight = FontWeight.W600, fontSize = 12.8.sp, maxLines = 1) }
                Row(horizontalArrangement = Arrangement.spacedBy(4.dp)) {
                    RouteOrderButton(
                        Icons.Outlined.KeyboardArrowUp,
                        enabled = index > 0 && reorderingSightId == null && deletingSightId == null,
                        contentDescription = localized("Переместить вверх", "Move up", "Mover arriba", "Nach oben"),
                    ) {
                        val reordered = orderedSights.toMutableList().apply { add(index - 1, removeAt(index)) }
                        orderedSights = reordered
                        reorderingSightId = sight.id
                        message = null
                        scope.launch {
                            runCatching {
                                SupabaseTripRepository(SupabaseProvider.clientForCurrentAuthFlow()).reorderSights(
                                    tripId,
                                    reordered.map(Sight::id),
                                )
                            }.onSuccess {
                                onSaved()
                            }.onFailure {
                                orderedSights = sights
                                message = localizedFailure(language, it, localized(language, "Не удалось изменить порядок мест", "Could not change the order of sights", "No se pudo cambiar el orden de los lugares", "Die Reihenfolge der Orte konnte nicht geändert werden"))
                            }
                            reorderingSightId = null
                        }
                    }
                    RouteOrderButton(
                        Icons.Outlined.KeyboardArrowDown,
                        enabled = index < orderedSights.lastIndex && reorderingSightId == null && deletingSightId == null,
                        contentDescription = localized("Переместить вниз", "Move down", "Mover abajo", "Nach unten"),
                    ) {
                        val reordered = orderedSights.toMutableList().apply { add(index + 1, removeAt(index)) }
                        orderedSights = reordered
                        reorderingSightId = sight.id
                        message = null
                        scope.launch {
                            runCatching {
                                SupabaseTripRepository(SupabaseProvider.clientForCurrentAuthFlow()).reorderSights(
                                    tripId,
                                    reordered.map(Sight::id),
                                )
                            }.onSuccess {
                                onSaved()
                            }.onFailure {
                                orderedSights = sights
                                message = localizedFailure(language, it, localized(language, "Не удалось изменить порядок мест", "Could not change the order of sights", "No se pudo cambiar el orden de los lugares", "Die Reihenfolge der Orte konnte nicht geändert werden"))
                            }
                            reorderingSightId = null
                        }
                    }
                }
                Box(modifier = Modifier.size(36.dp).clip(RoundedCornerShape(10.dp)).background(dangerSurfaceColor()).clickable(enabled = deletingSightId == null && reorderingSightId == null) {
                    deletingSightId = sight.id
                    message = null
                    scope.launch {
                        runCatching { SupabaseTripRepository(SupabaseProvider.clientForCurrentAuthFlow()).deleteTripItem(tripId, "sights", sight.id) }
                            .onSuccess { onSaved() }
                            .onFailure {
                                message = localizedFailure(language, it, localized(language, "Не удалось удалить достопримечательность", "Could not delete sight", "No se pudo eliminar el lugar", "Ort konnte nicht gelöscht werden"))
                            }
                        deletingSightId = null
                    }
                }, contentAlignment = Alignment.Center) {
                    Icon(Icons.Outlined.Delete, contentDescription = localized("Удалить", "Delete", "Eliminar", "Löschen"), tint = Color(0xFFFF6B65), modifier = Modifier.size(18.dp))
                }
            }
        }
        Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(8.dp)) {
            Text(
                localized("＋  Из каталога", "＋  From catalog", "＋  Del catálogo", "＋  Aus Katalog"),
                color = primaryColor(),
                fontFamily = Manrope,
                fontWeight = FontWeight.W800,
                fontSize = 12.5.sp,
                textAlign = TextAlign.Center,
                modifier = Modifier
                    .weight(1f)
                    .height(50.dp)
                    .clip(RoundedCornerShape(14.dp))
                    .border(1.dp, primaryColor().copy(alpha = 0.45f), RoundedCornerShape(14.dp))
                    .background(primaryColor().copy(alpha = 0.08f))
                    .clickable { catalogOpen = true }
                    .padding(top = 15.dp),
            )
            Text(
                localized("＋  Вручную", "＋  Manually", "＋  Manualmente", "＋  Manuell"),
                color = primaryColor(),
                fontFamily = Manrope,
                fontWeight = FontWeight.W800,
                fontSize = 12.5.sp,
                textAlign = TextAlign.Center,
                modifier = Modifier
                    .weight(1f)
                    .height(50.dp)
                    .clip(RoundedCornerShape(14.dp))
                    .border(1.dp, contentBorderColor(), RoundedCornerShape(14.dp))
                    .background(tintedSurfaceColor())
                    .clickable { addingSight = true }
                    .padding(top = 15.dp),
            )
        }
        if (sights.isNotEmpty()) {
            Box(
                modifier = Modifier
                    .fillMaxWidth()
                    .clip(RoundedCornerShape(14.dp))
                    .background(dangerSurfaceColor())
                    .clickable(enabled = deletingSightId == null && !deletingDay) {
                        deleteDayError = null
                        deleteDayDialogOpen = true
                    }
                    .padding(vertical = 14.dp),
                contentAlignment = Alignment.Center,
            ) {
                Row(horizontalArrangement = Arrangement.spacedBy(8.dp), verticalAlignment = Alignment.CenterVertically) {
                    Icon(Icons.Outlined.Delete, contentDescription = localized("Удалить день", "Delete day", "Eliminar día", "Tag löschen"), tint = Color(0xFFFF6B65), modifier = Modifier.size(18.dp))
                    Text(localized("Удалить день", "Delete day", "Eliminar día", "Tag löschen"), color = Color(0xFFFF6B65), fontFamily = Manrope, fontWeight = FontWeight.W800, fontSize = 13.sp)
                }
            }
        }
        }
        Button(
            onClick = onClose,
            modifier = Modifier
                .fillMaxWidth()
                .height(54.dp)
                .padding(start = 16.dp, end = 16.dp, bottom = 5.dp),
            colors = ButtonDefaults.buttonColors(containerColor = primaryColor(), contentColor = primaryContentColor()),
            shape = RoundedCornerShape(14.dp),
        ) {
            Text(localized("Сохранить", "Save", "Guardar", "Speichern"), fontFamily = Manrope, fontWeight = FontWeight.W800)
        }
    }
    if (catalogOpen) {
        ModalBottomSheet(
            onDismissRequest = { catalogOpen = false },
            sheetState = rememberModalBottomSheetState(skipPartiallyExpanded = true),
            containerColor = cardSurfaceColor(),
            dragHandle = null,
        ) {
            SightCatalogSheet(
                tripId = tripId,
                city = city,
                day = day,
                existingSights = allSights,
                onClose = { catalogOpen = false },
                onSaved = onSaved,
            )
        }
    }
    if (addingSight) {
        ModalBottomSheet(onDismissRequest = { addingSight = false }, containerColor = cardSurfaceColor()) {
            AddSightSheet(tripId, city, day, onClose = { addingSight = false }, onSaved = onSaved)
        }
    }
    if (deleteDayDialogOpen) {
        AlertDialog(
            onDismissRequest = { if (!deletingDay) deleteDayDialogOpen = false },
            title = {
                Text(
                    localized("Удалить день?", "Delete day?", "¿Eliminar día?", "Tag löschen?"),
                    fontFamily = Manrope,
                    fontWeight = FontWeight.W800,
                )
            },
            text = {
                Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                    Text(
                        localized(
                            "Все достопримечательности этого дня будут удалены из поездки.",
                            "All sights from this day will be removed from the trip.",
                            "Todos los lugares de este día se eliminarán del viaje.",
                            "Alle Sehenswürdigkeiten dieses Tages werden aus der Reise entfernt.",
                        ),
                        fontFamily = Manrope,
                    )
                    deleteDayError?.let { error ->
                        Text(error, color = Color(0xFFE0524B), fontFamily = Manrope, fontWeight = FontWeight.W700, fontSize = 12.sp)
                    }
                }
            },
            dismissButton = {
                TextButton(onClick = { deleteDayDialogOpen = false }, enabled = !deletingDay) {
                    Text(localized("Отмена", "Cancel", "Cancelar", "Abbrechen"), fontFamily = Manrope, fontWeight = FontWeight.W800)
                }
            },
            confirmButton = {
                TextButton(
                    onClick = {
                        scope.launch {
                            deletingDay = true
                            deleteDayError = null
                            runCatching {
                                SupabaseTripRepository(SupabaseProvider.clientForCurrentAuthFlow()).deleteSightDay(tripId, day)
                            }.onSuccess {
                                deleteDayDialogOpen = false
                                onDeleted()
                            }.onFailure {
                                deleteDayError = localizedFailure(language, it, localized(language, "Не удалось удалить день", "Could not delete day", "No se pudo eliminar el día", "Tag konnte nicht gelöscht werden"))
                            }
                            deletingDay = false
                        }
                    },
                    enabled = !deletingDay,
                    colors = ButtonDefaults.textButtonColors(contentColor = Color(0xFFD9534F)),
                ) {
                    Text(
                        if (deletingDay) localized("Удаляем…", "Deleting…", "Eliminando…", "Wird gelöscht…")
                        else localized("Удалить", "Delete", "Eliminar", "Löschen"),
                        fontFamily = Manrope,
                        fontWeight = FontWeight.W800,
                    )
                }
            },
        )
    }
}

private fun catalogSightAlreadyAdded(
    entry: SightCatalogEntry,
    city: String,
    existingSights: List<Sight>,
): Boolean {
    val cityKey = normalizeCatalogText(catalogCityName(city))
    val entryNames = entry.allNames().map(::normalizeCatalogText).filter(String::isNotBlank).toSet()
    return existingSights.any { sight ->
        val sightCity = normalizeCatalogText(catalogCityName(sight.city))
        val sightName = normalizeCatalogText(sight.name)
        sightCity == cityKey && sightName in entryNames
    }
}

@Composable
@OptIn(ExperimentalMaterial3Api::class)
private fun SightCatalogSheet(
    tripId: String,
    city: String,
    day: Int,
    existingSights: List<Sight>,
    onClose: () -> Unit,
    onSaved: () -> Unit,
) {
    val language = LocalLanguage.current
    val scope = rememberCoroutineScope()
    val catalogRepository = remember { SightCatalogRepository(SupabaseProvider.clientForCurrentAuthFlow()) }
    var query by remember { mutableStateOf("") }
    var entries by remember { mutableStateOf<List<SightCatalogEntry>>(emptyList()) }
    var selectedIds by remember { mutableStateOf<Set<String>>(emptySet()) }
    var loading by remember { mutableStateOf(true) }
    var saving by remember { mutableStateOf(false) }
    var message by remember { mutableStateOf<String?>(null) }
    var liveRatingsAvailable by remember { mutableStateOf(false) }
    val deviceLocation = LocalDeviceLocation.current
    val entriesForDisplay = remember(entries, deviceLocation) {
        if (deviceLocation == null) {
            entries
        } else {
            entries.sortedWith(
                compareBy<SightCatalogEntry> { entry ->
                    distanceMeters(deviceLocation, entry.latitude, entry.longitude) ?: Double.MAX_VALUE
                }.thenBy { it.sortOrder },
            )
        }
    }
    val selectedEntries = entries.filter { it.id in selectedIds && !catalogSightAlreadyAdded(it, city, existingSights) }
    val liveRatingsUnavailableMessage = localized(
        "Фото и рейтинг достопримечательностей временно недоступны — показан базовый каталог",
        "Sight photos and ratings are temporarily unavailable — showing the base catalog",
        "Las fotos y valoraciones no están disponibles temporalmente — se muestra el catálogo base",
        "Fotos und Bewertungen sind vorübergehend nicht verfügbar — der Basiskatalog wird angezeigt",
    )

    LaunchedEffect(city, query, language) {
        loading = true
        message = null
        delay(180)
        runCatching { catalogRepository.searchWithLiveRatings(city = city, query = query, language = language) }
            .onSuccess { result ->
                entries = result.entries
                liveRatingsAvailable = result.liveRatingsAvailable
                if (!result.liveRatingsAvailable && result.entries.isNotEmpty()) {
                    message = liveRatingsUnavailableMessage
                }
                selectedIds = selectedIds.intersect(result.entries.map(SightCatalogEntry::id).toSet())
                if (result.liveRatingsAvailable) {
                    val photoNames = result.entries
                        .filter { it.photoUrl.isNullOrBlank() && it.photoName.isNotBlank() }
                        .map(SightCatalogEntry::photoName)
                        .take(12)
                    if (photoNames.isNotEmpty()) {
                        val photos = runCatching { catalogRepository.resolveSightPhotos(photoNames) }
                            .getOrElse { error ->
                                if (error is CancellationException) throw error
                                emptyMap()
                            }
                        if (photos.isNotEmpty()) {
                            entries = entries.map { entry ->
                                val photo = photos[entry.photoName]
                                if (photo == null) entry else entry.copy(
                                    photoUrl = photo.photoUrl ?: entry.photoUrl,
                                    photoAttribution = photo.photoAttribution ?: entry.photoAttribution,
                                )
                            }
                        }
                    }
                }
            }
            .onFailure { error ->
                if (error is CancellationException) throw error
                entries = emptyList()
                liveRatingsAvailable = false
                message = localizedFailure(language, error, localized(language, "Не удалось загрузить каталог", "Could not load the catalog", "No se pudo cargar el catálogo", "Katalog konnte nicht geladen werden"))
            }
        loading = false
    }

    Column(
        modifier = Modifier
            .fillMaxWidth()
            .fillMaxHeight(0.94f)
            .windowInsetsPadding(WindowInsets.navigationBars)
            .imePadding()
            .padding(horizontal = 16.dp, vertical = 7.dp),
        verticalArrangement = Arrangement.spacedBy(10.dp),
    ) {
        Row(verticalAlignment = Alignment.CenterVertically) {
            Column(modifier = Modifier.weight(1f)) {
                Text(
                    localized("Достопримечательности", "Sights", "Lugares", "Sehenswürdigkeiten"),
                    color = contentTextColor(),
                    fontFamily = Manrope,
                    fontWeight = FontWeight.W800,
                    fontSize = 22.sp,
                )
                Text(
                    localizedCityName(city),
                    color = secondaryTextColor(),
                    fontFamily = Manrope,
                    fontWeight = FontWeight.W600,
                    fontSize = 13.sp,
                )
            }
            Box(
                modifier = Modifier.size(36.dp).clip(CircleShape).background(secondarySurfaceColor()).clickable { onClose() },
                contentAlignment = Alignment.Center,
            ) {
                Icon(Icons.Filled.Close, contentDescription = localized("Закрыть", "Close", "Cerrar", "Schließen"), tint = secondaryTextColor(), modifier = Modifier.size(18.dp))
            }
        }
        OutlinedTextField(
            value = query,
            onValueChange = { query = it },
            modifier = Modifier.fillMaxWidth(),
            singleLine = true,
            shape = RoundedCornerShape(14.dp),
            placeholder = { Text(localized("Поиск по названию", "Search by name", "Buscar por nombre", "Nach Namen suchen"), color = secondaryTextColor(), fontFamily = Manrope, fontSize = 13.sp) },
            leadingIcon = { Text("⌕", color = primaryColor(), fontSize = 23.sp) },
            colors = OutlinedTextFieldDefaults.colors(focusedBorderColor = primaryColor(), unfocusedBorderColor = contentBorderColor()),
        )
        if (liveRatingsAvailable) {
            Text(
                localized("Фото и рейтинг из Google Maps", "Photos and ratings from Google Maps", "Fotos y valoraciones de Google Maps", "Fotos und Bewertungen aus Google Maps"),
                color = secondaryTextColor(),
                fontFamily = Manrope,
                fontWeight = FontWeight.W600,
                fontSize = 10.sp,
            )
        }
        if (deviceLocation != null) {
            Text(
                localized("Сначала ближайшие к вам", "Closest places first", "Primero los lugares más cercanos", "Nächstgelegene Orte zuerst"),
                color = primaryColor(),
                fontFamily = Manrope,
                fontWeight = FontWeight.W700,
                fontSize = 10.sp,
            )
        }
        if (!loading && entries.isNotEmpty()) {
            Row(
                modifier = Modifier.fillMaxWidth(),
                verticalAlignment = Alignment.CenterVertically,
                horizontalArrangement = Arrangement.SpaceBetween,
            ) {
                Text(
                    localized("Популярные места", "Popular places", "Lugares populares", "Beliebte Orte"),
                    color = contentTextColor(),
                    fontFamily = Manrope,
                    fontWeight = FontWeight.W800,
                    fontSize = 14.sp,
                )
                Text(
                    localized("${entries.size} мест", "${entries.size} places", "${entries.size} lugares", "${entries.size} Orte"),
                    color = secondaryTextColor(),
                    fontFamily = Manrope,
                    fontWeight = FontWeight.W700,
                    fontSize = 11.sp,
                )
            }
        }
        if (message != null) {
            Text(message!!, color = Color(0xFFE0524B), fontFamily = Manrope, fontWeight = FontWeight.W700, fontSize = 12.sp)
        }
        if (loading) {
            Box(modifier = Modifier.weight(1f).fillMaxWidth(), contentAlignment = Alignment.Center) {
                CircularProgressIndicator(color = primaryColor(), strokeWidth = 3.dp, modifier = Modifier.size(30.dp))
            }
        } else if (entries.isEmpty()) {
            Box(modifier = Modifier.weight(1f).fillMaxWidth(), contentAlignment = Alignment.Center) {
                Text(
                    localized("Для этого города пока нет мест в каталоге", "There are no catalog sights for this city yet", "Todavía no hay lugares para esta ciudad", "Für diese Stadt gibt es noch keine Orte"),
                    color = secondaryTextColor(),
                    fontFamily = Manrope,
                    fontWeight = FontWeight.W600,
                    fontSize = 13.sp,
                    textAlign = TextAlign.Center,
                    modifier = Modifier.padding(horizontal = 22.dp),
                )
            }
        } else {
            LazyColumn(
                modifier = Modifier.weight(1f).fillMaxWidth(),
                verticalArrangement = Arrangement.spacedBy(8.dp),
            ) {
                items(entriesForDisplay, key = { it.id }) { entry ->
                    if (entry.photoUrl.isNullOrBlank()) {
                        LaunchedEffect(entry.id, entry.photoName, entry.name(language), entry.cityNameEn, language) {
                            val googlePhoto = if (entry.photoName.isBlank()) {
                                null
                            } else {
                                try {
                                    sightPhotoLoadGate.withPermit {
                                        catalogRepository.resolveSightPhoto(entry.photoName)
                                    }
                                } catch (error: CancellationException) {
                                    throw error
                                } catch (_: Throwable) {
                                    null
                                }
                            }
                            val photoUrl = googlePhoto?.photoUrl ?: sightPhotoLoadGate.withPermit {
                                cachedSightPhotoUrl(
                                    "catalog:${entry.id}",
                                    entry.name(language),
                                    "${entry.nameEn} ${entry.cityNameEn}",
                                    "${entry.nameRu} ${entry.cityNameRu}",
                                )
                            }
                            if (!photoUrl.isNullOrBlank()) {
                                entries = entries.map { current ->
                                    if (current.id == entry.id &&
                                        current.photoName == entry.photoName &&
                                        current.photoUrl.isNullOrBlank()
                                    ) {
                                        current.copy(
                                            photoUrl = photoUrl,
                                            photoAttribution = googlePhoto?.photoAttribution ?: current.photoAttribution,
                                        )
                                    } else {
                                        current
                                    }
                                }
                            }
                        }
                    }
                    val alreadyAdded = catalogSightAlreadyAdded(entry, city, existingSights)
                    val selected = entry.id in selectedIds
                    val cardShape = RoundedCornerShape(18.dp)
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .clip(cardShape)
                            .background(if (selected) primaryColor().copy(alpha = 0.08f) else secondarySurfaceColor())
                            .border(1.dp, if (selected) primaryColor().copy(alpha = 0.52f) else contentBorderColor(), cardShape)
                            .clickable(enabled = !alreadyAdded && !saving) {
                                selectedIds = if (selected) selectedIds - entry.id else selectedIds + entry.id
                            }
                            .padding(8.dp),
                        verticalAlignment = Alignment.CenterVertically,
                    ) {
                        Box(
                            modifier = Modifier
                                .size(width = 96.dp, height = 112.dp)
                                .clip(RoundedCornerShape(14.dp))
                                .background(tintedSurfaceColor()),
                            contentAlignment = Alignment.Center,
                        ) {
                            if (!entry.photoUrl.isNullOrBlank()) {
                                FastCatalogImage(
                                    url = entry.photoUrl,
                                    contentDescription = entry.name(language),
                                    contentScale = androidx.compose.ui.layout.ContentScale.Crop,
                                    modifier = Modifier.fillMaxSize(),
                                )
                            } else {
                                Icon(
                                    Icons.Outlined.LocationOn,
                                    contentDescription = null,
                                    tint = primaryColor().copy(alpha = 0.72f),
                                    modifier = Modifier.size(28.dp),
                                )
                            }
                        }
                        Spacer(modifier = Modifier.width(11.dp))
                        Column(modifier = Modifier.weight(1f)) {
                            Text(
                                entry.category.ifBlank { localized("Достопримечательность", "Attraction", "Atracción", "Sehenswürdigkeit") }.uppercase(Locale.ROOT),
                                color = primaryColor(),
                                fontFamily = Manrope,
                                fontWeight = FontWeight.W800,
                                fontSize = 9.5.sp,
                                maxLines = 1,
                                overflow = TextOverflow.Ellipsis,
                            )
                            Text(
                                entry.name(language),
                                color = contentTextColor(),
                                fontFamily = Manrope,
                                fontWeight = FontWeight.W800,
                                fontSize = 15.sp,
                                lineHeight = 18.sp,
                                maxLines = 2,
                                overflow = TextOverflow.Ellipsis,
                                modifier = Modifier.padding(top = 2.dp),
                            )
                            if (entry.rating != null || entry.ratingCount != null) {
                                Row(
                                    modifier = Modifier.padding(top = 5.dp),
                                    verticalAlignment = Alignment.CenterVertically,
                                    horizontalArrangement = Arrangement.spacedBy(4.dp),
                                ) {
                                    Text("★", color = Color(0xFFFFB52E), fontSize = 14.sp, fontWeight = FontWeight.W800)
                                    entry.rating?.let {
                                        Text(
                                            String.format(Locale.ROOT, "%.1f", it),
                                            color = contentTextColor(),
                                            fontFamily = Manrope,
                                            fontWeight = FontWeight.W800,
                                            fontSize = 11.5.sp,
                                        )
                                    }
                                    entry.ratingCount?.let {
                                        Text(
                                            "· ${catalogRatingCountLabel(it, language)}",
                                            color = secondaryTextColor(),
                                            fontFamily = Manrope,
                                            fontWeight = FontWeight.W600,
                                            fontSize = 10.5.sp,
                                            maxLines = 1,
                                            overflow = TextOverflow.Ellipsis,
                                        )
                                    }
                                }
                            }
                            entry.description(language).takeIf(String::isNotBlank)?.let { description ->
                                Text(
                                    description,
                                    color = secondaryTextColor(),
                                    fontFamily = Manrope,
                                    fontWeight = FontWeight.W600,
                                    fontSize = 11.5.sp,
                                    lineHeight = 15.sp,
                                    maxLines = 2,
                                    overflow = TextOverflow.Ellipsis,
                                    modifier = Modifier.padding(top = 4.dp),
                                )
                            }
                        }
                        Box(
                            modifier = Modifier
                                .padding(start = 10.dp)
                                .size(34.dp)
                                .clip(CircleShape)
                                .background(if (alreadyAdded || selected) primaryColor() else tintedSurfaceColor()),
                            contentAlignment = Alignment.Center,
                        ) {
                            if (alreadyAdded) {
                                Icon(Icons.Filled.Check, contentDescription = localized("Уже добавлено", "Already added", "Ya añadido", "Bereits hinzugefügt"), tint = primaryContentColor(), modifier = Modifier.size(18.dp))
                            } else {
                                Text(if (selected) "✓" else "+", color = if (selected) primaryContentColor() else primaryColor(), fontFamily = Manrope, fontWeight = FontWeight.W800, fontSize = 20.sp)
                            }
                        }
                    }
                }
            }
        }
        Text(
            text = "© OpenStreetMap contributors",
            color = secondaryTextColor(),
            fontFamily = Manrope,
            fontWeight = FontWeight.W600,
            fontSize = 10.sp,
            textAlign = TextAlign.Center,
            modifier = Modifier.fillMaxWidth(),
        )
        Button(
            onClick = {
                scope.launch {
                    saving = true
                    message = null
                    runCatching {
                        SupabaseTripRepository(SupabaseProvider.clientForCurrentAuthFlow()).addCatalogSights(
                            id = tripId,
                            city = city,
                            language = language,
                            walkDay = day,
                            entries = selectedEntries,
                        )
                    }.onSuccess {
                        onSaved()
                        onClose()
                    }.onFailure { error ->
                        message = localizedFailure(language, error, localized(language, "Не удалось добавить места", "Could not add sights", "No se pudieron añadir los lugares", "Orte konnten nicht hinzugefügt werden"))
                    }
                    saving = false
                }
            },
            enabled = selectedEntries.isNotEmpty() && !saving,
            modifier = Modifier.fillMaxWidth().height(54.dp).padding(bottom = 5.dp),
            colors = ButtonDefaults.buttonColors(containerColor = primaryColor(), contentColor = primaryContentColor()),
            shape = RoundedCornerShape(14.dp),
        ) {
            Text(
                if (saving) localized("Добавляем…", "Adding…", "Añadiendo…", "Wird hinzugefügt…")
                else localized("Добавить выбранные", "Add selected", "Añadir seleccionados", "Auswahl hinzufügen") + if (selectedEntries.isNotEmpty()) " (${selectedEntries.size})" else "",
                fontFamily = Manrope,
                fontWeight = FontWeight.W800,
            )
        }
    }
}

private fun catalogRatingCountLabel(count: Int, language: String): String {
    val formatted = String.format(Locale.ROOT, "%,d", count).replace(',', ' ')
    return when (language.trim().uppercase(Locale.ROOT).substringBefore('-')) {
        "EN" -> "$formatted reviews"
        "ES" -> "$formatted reseñas"
        "DE" -> "$formatted Bewertungen"
        else -> "$formatted отзывов"
    }
}

@Composable
private fun FastCatalogImage(
    url: String,
    contentDescription: String?,
    contentScale: androidx.compose.ui.layout.ContentScale,
    modifier: Modifier,
) {
    val context = LocalContext.current
    val request = remember(url) {
        ImageRequest.Builder(context)
            .data(url)
            .size(480, 360)
            .build()
    }
    AsyncImage(
        model = request,
        contentDescription = contentDescription,
        contentScale = contentScale,
        modifier = modifier,
    )
}

@Composable
@OptIn(ExperimentalMaterial3Api::class)
private fun AddSightSheet(tripId: String, city: String, day: Int, onClose: () -> Unit, onSaved: () -> Unit) {
    val context = LocalContext.current
    val language = LocalLanguage.current
    val scope = rememberCoroutineScope()
    var name by remember { mutableStateOf("") }
    var description by remember { mutableStateOf("") }
    var link by remember { mutableStateOf("") }
    var photoUri by remember { mutableStateOf<Uri?>(null) }
    var selectedPoint by remember { mutableStateOf<Point?>(null) }
    var locationPickerOpen by remember { mutableStateOf(false) }
    var saving by remember { mutableStateOf(false) }
    var message by remember { mutableStateOf<String?>(null) }
    val photoPicker = rememberLauncherForActivityResult(ActivityResultContracts.GetContent()) { uri -> photoUri = uri }
    val navigationBarInset = WindowInsets.navigationBars.asPaddingValues().calculateBottomPadding()
    Column(
        modifier = Modifier
            .fillMaxWidth()
            .verticalScroll(rememberScrollState())
            .padding(horizontal = 16.dp, vertical = 6.dp)
            .padding(bottom = navigationBarInset),
        verticalArrangement = Arrangement.spacedBy(14.dp),
    ) {
        Row(verticalAlignment = Alignment.CenterVertically) {
            Column(modifier = Modifier.weight(1f)) {
                Text("${localizedCityName(city).uppercase()} · ${localized("ДЕНЬ", "DAY", "DÍA", "TAG")} $day", color = primaryColor(), fontFamily = Manrope, fontWeight = FontWeight.W800, fontSize = 10.sp)
                Text(localized("Добавить\nдостопримечательность", "Add\nsight", "Añadir\nlugar", "Sehenswürdigkeit\nhinzufügen"), color = contentTextColor(), fontFamily = Manrope, fontWeight = FontWeight.W800, fontSize = 24.sp, lineHeight = 27.sp)
            }
            Box(modifier = Modifier.size(36.dp).clip(CircleShape).background(secondarySurfaceColor()).clickable { onClose() }, contentAlignment = Alignment.Center) { Icon(Icons.Filled.Close, contentDescription = localized("Закрыть", "Close", "Cerrar", "Schließen"), tint = secondaryTextColor(), modifier = Modifier.size(18.dp)) }
        }
        RouteEditorField(localized("Главная достопримечательность", "Main sight", "Lugar principal", "Hauptsehenswürdigkeit"), name, { name = it }, Modifier.fillMaxWidth(), placeholder = localized("Напр. Две башни", "E.g. Two towers", "P. ej. Dos torres", "Z. B. Zwei Türme"))
        Row(horizontalArrangement = Arrangement.spacedBy(12.dp)) {
            OutlinedTextField(value = description, onValueChange = { description = it }, placeholder = { Text(localized("Описание объекта: что\nважно увидеть, время\nпосещения, заметки...", "Description", "Descripción", "Beschreibung"), color = secondaryTextColor(), fontFamily = Manrope, fontSize = 13.sp, lineHeight = 20.sp, style = androidx.compose.ui.text.TextStyle(platformStyle = OdysseyNoFontPadding)) }, shape = RoundedCornerShape(14.dp), colors = OutlinedTextFieldDefaults.colors(focusedBorderColor = contentBorderColor(), unfocusedBorderColor = contentBorderColor()), modifier = Modifier.weight(1f).height(122.dp))
            Box(modifier = Modifier.width(132.dp).height(122.dp).clip(RoundedCornerShape(14.dp)).border(1.dp, contentBorderColor(), RoundedCornerShape(14.dp)).background(tintedSurfaceColor()).clickable { photoPicker.launch("image/*") }, contentAlignment = Alignment.Center) {
                if (photoUri != null) AsyncImage(model = photoUri, contentDescription = localized("Выбранное фото", "Selected photo", "Foto seleccionada", "Ausgewähltes Foto"), contentScale = androidx.compose.ui.layout.ContentScale.Crop, modifier = Modifier.fillMaxSize()) else Column(horizontalAlignment = Alignment.CenterHorizontally, verticalArrangement = Arrangement.spacedBy(1.dp)) {
                    Text("⇧", color = primaryColor(), fontSize = 25.sp, lineHeight = 28.sp, style = androidx.compose.ui.text.TextStyle(platformStyle = OdysseyNoFontPadding))
                    Text(localized("Фото объекта", "Photo", "Foto", "Foto"), color = primaryColor(), fontFamily = Manrope, fontWeight = FontWeight.W800, fontSize = 10.sp, lineHeight = 13.sp, style = androidx.compose.ui.text.TextStyle(platformStyle = OdysseyNoFontPadding))
                    Text(localized("Выберите\nфайл", "Choose file", "Elige archivo", "Datei wählen"), color = primaryColor(), fontFamily = Manrope, fontWeight = FontWeight.W800, fontSize = 12.sp, lineHeight = 15.sp, textAlign = TextAlign.Center, style = androidx.compose.ui.text.TextStyle(platformStyle = OdysseyNoFontPadding))
                }
            }
        }
        RouteEditorField(
            label = localized("Ссылка на достопримечательность", "Sight link", "Enlace del lugar", "Link zur Sehenswürdigkeit"),
            value = link,
            onValueChange = { value ->
                link = value
                sightLinkPoint(value)?.let { selectedPoint = it }
                if (value.isBlank()) selectedPoint = null
            },
            modifier = Modifier.fillMaxWidth(),
            placeholder = "https://maps.app.goo.gl/...",
        )
        if (link.isNotBlank()) {
            Text(
                text = if (sightLinkPoint(link) != null) {
                    localized("Точка будет взята из ссылки", "The map point will be taken from the link", "El punto se tomará del enlace", "Der Kartenpunkt wird aus dem Link übernommen")
                } else {
                    localized("Если точка не определится автоматически, выберите её на карте ниже", "If the point cannot be detected automatically, choose it on the map below", "Si no se detecta el punto, selecciónelo en el mapa", "Wenn der Punkt nicht erkannt wird, wählen Sie ihn auf der Karte aus")
                },
                color = secondaryTextColor(),
                fontFamily = Manrope,
                fontWeight = FontWeight.W600,
                fontSize = 11.sp,
                lineHeight = 16.sp,
            )
        }
        SightLocationField(
            point = selectedPoint,
            onClick = { locationPickerOpen = true },
            modifier = Modifier.fillMaxWidth(),
        )
        if (message != null) Text(message!!, color = Color(0xFFE0524B), fontFamily = Manrope, fontWeight = FontWeight.W700, fontSize = 12.sp)
        Button(
            onClick = {
                scope.launch {
                    saving = true
                    var createdSightId: String? = null
                    runCatching {
                        val repository = SupabaseTripRepository(SupabaseProvider.clientForCurrentAuthFlow())
                        var savedPoint = selectedPoint
                        if (link.isNotBlank() && savedPoint == null) {
                            savedPoint = resolveSightLinkCoordinates(link)?.let { coordinates ->
                                Point.fromLngLat(coordinates.longitude, coordinates.latitude)
                            } ?: error(localized(language, "Не удалось определить точку по ссылке. Выберите точку на карте.", "Could not find a map point in this link. Choose a point on the map.", "No se pudo encontrar el punto en el enlace. Elija un punto en el mapa.", "Im Link wurde kein Kartenpunkt gefunden. Wählen Sie einen Punkt auf der Karte."))
                        }
                        val sightId = repository.addSightDetails(
                            id = tripId,
                            name = name,
                            city = city,
                            category = "достопримечательности",
                            description = description,
                            walkDay = day,
                            longitude = savedPoint?.longitude(),
                            latitude = savedPoint?.latitude(),
                            link = link.trim(),
                        )
                        createdSightId = sightId
                        photoUri?.let { uri ->
                            val bytes = context.contentResolver.openInputStream(uri)?.use { it.readBytes() }
                                ?: error("Не удалось прочитать изображение")
                            repository.addSightPhoto(tripId, sightId, bytes)
                        }
                    }.onSuccess { onSaved(); onClose() }.onFailure {
                        createdSightId?.let { sightId ->
                            runCatching {
                                SupabaseTripRepository(SupabaseProvider.clientForCurrentAuthFlow())
                                    .deleteTripItem(tripId, "sights", sightId)
                            }
                        }
                        message = localizedFailure(language, it, localized(language, "Не удалось сохранить место", "Could not save sight", "No se pudo guardar el lugar", "Ort konnte nicht gespeichert werden"))
                    }
                    saving = false
                }
            },
            enabled = !saving && name.isNotBlank(),
            modifier = Modifier.fillMaxWidth().height(54.dp).padding(bottom = 5.dp),
            colors = ButtonDefaults.buttonColors(containerColor = primaryColor(), contentColor = primaryContentColor()),
            shape = RoundedCornerShape(14.dp),
        ) { Text(if (saving) localized("Сохраняем…", "Saving…", "Guardando…", "Wird gespeichert…") else localized("Добавить место", "Add sight", "Añadir lugar", "Ort hinzufügen"), fontFamily = Manrope, fontWeight = FontWeight.W800) }
    }
    if (locationPickerOpen) {
        ModalBottomSheet(
            onDismissRequest = { locationPickerOpen = false },
            sheetState = rememberModalBottomSheetState(skipPartiallyExpanded = true),
            containerColor = cardSurfaceColor(),
            dragHandle = null,
        ) {
            SightLocationPickerSheet(
                city = city,
                initialPoint = selectedPoint,
                onClose = { locationPickerOpen = false },
                onConfirm = { point ->
                    selectedPoint = point
                    locationPickerOpen = false
                },
            )
        }
    }
}

@Composable
private fun SightLocationField(
    point: Point?,
    onClick: () -> Unit,
    modifier: Modifier = Modifier,
) {
    Column(modifier = modifier, verticalArrangement = Arrangement.spacedBy(5.dp)) {
        Text(
            localized("Точка на карте", "Map point", "Punto en el mapa", "Punkt auf der Karte"),
            color = contentTextColor(),
            fontFamily = Manrope,
            fontWeight = FontWeight.W800,
            fontSize = 12.sp,
            lineHeight = 16.sp,
            style = androidx.compose.ui.text.TextStyle(platformStyle = OdysseyNoFontPadding),
        )
        Box(
            modifier = Modifier
                .fillMaxWidth()
                .height(56.dp)
                .clip(RoundedCornerShape(14.dp))
                .background(cardSurfaceColor())
                .border(1.dp, contentBorderColor(), RoundedCornerShape(14.dp))
                .clickable(onClick = onClick)
                .padding(horizontal = 12.dp),
            contentAlignment = Alignment.CenterStart,
        ) {
            Row(
                modifier = Modifier.fillMaxWidth(),
                verticalAlignment = Alignment.CenterVertically,
                horizontalArrangement = Arrangement.spacedBy(9.dp),
            ) {
                Icon(
                    Icons.Outlined.LocationOn,
                    contentDescription = null,
                    tint = if (point == null) secondaryTextColor() else primaryColor(),
                    modifier = Modifier.size(19.dp),
                )
                Column(modifier = Modifier.weight(1f)) {
                    Text(
                        text = if (point == null) {
                            localized("Указать точку на карте", "Choose a point on the map", "Elegir un punto en el mapa", "Punkt auf der Karte wählen")
                        } else {
                            localized("Точка выбрана", "Point selected", "Punto seleccionado", "Punkt ausgewählt")
                        },
                        color = if (point == null) secondaryTextColor() else contentTextColor(),
                        fontFamily = Manrope,
                        fontWeight = FontWeight.W600,
                        fontSize = 14.sp,
                        lineHeight = 18.sp,
                        style = androidx.compose.ui.text.TextStyle(platformStyle = OdysseyNoFontPadding),
                        maxLines = 1,
                        overflow = TextOverflow.Ellipsis,
                    )
                    if (point != null) {
                        Text(
                            text = formatSightCoordinate(point),
                            color = secondaryTextColor(),
                            fontFamily = Manrope,
                            fontWeight = FontWeight.W600,
                            fontSize = 11.sp,
                            lineHeight = 14.sp,
                            style = androidx.compose.ui.text.TextStyle(platformStyle = OdysseyNoFontPadding),
                            maxLines = 1,
                        )
                    }
                }
                Icon(
                    Icons.Outlined.KeyboardArrowDown,
                    contentDescription = null,
                    tint = primaryColor(),
                    modifier = Modifier.size(20.dp),
                )
            }
        }
    }
}

@Composable
@OptIn(ExperimentalMaterial3Api::class)
private fun SightLocationPickerSheet(
    city: String,
    initialPoint: Point?,
    onClose: () -> Unit,
    onConfirm: (Point?) -> Unit,
) {
    val context = LocalContext.current
    val language = LocalLanguage.current
    val navigationBarInset = WindowInsets.navigationBars.asPaddingValues().calculateBottomPadding()
    val cityPoint = remember(city) { mapCoordinate(city) }
    val cameraPoint = initialPoint ?: cityPoint ?: Point.fromLngLat(10.0, 50.0)
    val cameraZoom = when {
        initialPoint != null -> 15.0
        cityPoint != null -> 11.5
        else -> 3.8
    }
    var selectedPoint by remember(city, initialPoint) { mutableStateOf(initialPoint) }
    var mapStyleReady by remember { mutableStateOf(false) }
    val attributionDescription = localized(
        "Информация об источниках карты",
        "Map attribution information",
        "Información de atribución del mapa",
        "Informationen zur Kartenquelle",
    )
    val mapView = remember(context, city, initialPoint) {
        MapView(
            context,
            MapInitOptions(
                context = context,
                textureView = true,
                styleUri = null,
            ),
        ).also {
            it.scalebar.enabled = false
            keepMapGesturesInsideMap(it)
            it.post { labelMapboxAccessibility(it, attributionDescription) }
        }
    }
    val annotationManager = remember(mapView) { mapView.annotations.createCircleAnnotationManager() }
    val mapClickListener = remember(mapView) {
        object : OnMapClickListener {
            override fun onMapClick(point: Point): Boolean {
                selectedPoint = point
                return true
            }
        }
    }

    LaunchedEffect(mapView) {
        mapStyleReady = false
        mapView.mapboxMap.loadStyle(Style.MAPBOX_STREETS) { style ->
            style.localizeLabels(mapLocale(language))
            mapStyleReady = true
        }
    }

    DisposableEffect(mapView, mapClickListener) {
        mapView.gestures.addOnMapClickListener(mapClickListener)
        onDispose {
            mapView.gestures.removeOnMapClickListener(mapClickListener)
        }
    }

    DisposableEffect(mapView, annotationManager) {
        onDispose {
            annotationManager.deleteAll()
        }
    }

    LaunchedEffect(mapStyleReady, language) {
        if (mapStyleReady) mapView.mapboxMap.style?.localizeLabels(mapLocale(language))
    }

    LaunchedEffect(mapStyleReady, cameraPoint) {
        if (mapStyleReady) {
            mapView.mapboxMap.setCamera(
                CameraOptions.Builder()
                    .center(cameraPoint)
                    .zoom(cameraZoom)
                    .build(),
            )
        }
    }

    LaunchedEffect(mapStyleReady, selectedPoint) {
        if (mapStyleReady) {
            annotationManager.deleteAll()
            selectedPoint?.let { point ->
                annotationManager.create(
                    CircleAnnotationOptions()
                        .withPoint(point)
                        .withCircleRadius(11.0)
                        .withCircleColor("#6C5CE7")
                        .withCircleStrokeColor("#FFFFFF")
                        .withCircleStrokeWidth(4.0),
                )
            }
        }
    }

    Column(
        modifier = Modifier
            .fillMaxWidth()
            .verticalScroll(rememberScrollState())
            .padding(horizontal = 16.dp, vertical = 8.dp)
            .padding(bottom = 16.dp + navigationBarInset),
        verticalArrangement = Arrangement.spacedBy(12.dp),
    ) {
        Row(verticalAlignment = Alignment.CenterVertically) {
            Column(modifier = Modifier.weight(1f)) {
                Text(
                    localized("ТОЧКА НА КАРТЕ", "MAP POINT", "PUNTO EN EL MAPA", "PUNKT AUF DER KARTE"),
                    color = primaryColor(),
                    fontFamily = Manrope,
                    fontWeight = FontWeight.W800,
                    fontSize = 10.sp,
                    lineHeight = 14.sp,
                    style = androidx.compose.ui.text.TextStyle(platformStyle = OdysseyNoFontPadding),
                )
                Text(
                    localized("Выберите место", "Choose a place", "Elige un lugar", "Ort auswählen"),
                    color = contentTextColor(),
                    fontFamily = Manrope,
                    fontWeight = FontWeight.W800,
                    fontSize = 23.sp,
                    lineHeight = 28.sp,
                    style = androidx.compose.ui.text.TextStyle(platformStyle = OdysseyNoFontPadding),
                )
            }
            Box(
                modifier = Modifier
                    .size(36.dp)
                    .clip(CircleShape)
                    .background(secondarySurfaceColor())
                    .clickable(onClick = onClose),
                contentAlignment = Alignment.Center,
            ) {
                Icon(
                    Icons.Filled.Close,
                    contentDescription = localized("Закрыть", "Close", "Cerrar", "Schließen"),
                    tint = secondaryTextColor(),
                    modifier = Modifier.size(18.dp),
                )
            }
        }
        Text(
            localizedCityName(city),
            color = secondaryTextColor(),
            fontFamily = Manrope,
            fontWeight = FontWeight.W700,
            fontSize = 13.sp,
            lineHeight = 17.sp,
            style = androidx.compose.ui.text.TextStyle(platformStyle = OdysseyNoFontPadding),
        )
        Box(
            modifier = Modifier
                .fillMaxWidth()
                .height(300.dp)
                .clip(RoundedCornerShape(18.dp)),
        ) {
            AndroidView(
                factory = { mapView },
                modifier = Modifier.fillMaxSize(),
            )
        }
        Text(
            localized(
                "Нажмите на карту, чтобы поставить точку. Карту можно двигать и приближать.",
                "Tap the map to place a point. You can pan and zoom the map.",
                "Toca el mapa para colocar un punto. Puedes moverlo y acercarlo.",
                "Tippen Sie auf die Karte, um einen Punkt zu setzen. Sie können die Karte verschieben und zoomen.",
            ),
            color = secondaryTextColor(),
            fontFamily = Manrope,
            fontWeight = FontWeight.W600,
            fontSize = 12.sp,
            lineHeight = 17.sp,
            style = androidx.compose.ui.text.TextStyle(platformStyle = OdysseyNoFontPadding),
        )
        if (selectedPoint != null) {
            Text(
                formatSightCoordinate(selectedPoint!!),
                color = contentTextColor(),
                fontFamily = Manrope,
                fontWeight = FontWeight.W800,
                fontSize = 13.sp,
                lineHeight = 17.sp,
                style = androidx.compose.ui.text.TextStyle(platformStyle = OdysseyNoFontPadding),
            )
        }
        Row(
            modifier = Modifier.fillMaxWidth(),
            horizontalArrangement = Arrangement.spacedBy(10.dp),
            verticalAlignment = Alignment.CenterVertically,
        ) {
            TextButton(
                onClick = { selectedPoint = null },
                enabled = selectedPoint != null,
            ) {
                Text(
                    localized("Очистить", "Clear", "Borrar", "Löschen"),
                    color = if (selectedPoint != null) Color(0xFFE0524B) else secondaryTextColor(),
                    fontFamily = Manrope,
                    fontWeight = FontWeight.W800,
                )
            }
            Button(
                onClick = { onConfirm(selectedPoint) },
                modifier = Modifier.weight(1f).height(52.dp),
                colors = ButtonDefaults.buttonColors(containerColor = primaryColor(), contentColor = primaryContentColor()),
                shape = RoundedCornerShape(14.dp),
            ) {
                Text(
                    localized("Готово", "Done", "Listo", "Fertig"),
                    fontFamily = Manrope,
                    fontWeight = FontWeight.W800,
                )
            }
        }
    }
}

@Composable
private fun SightCard(
    sight: com.odyssey.travelplanner.data.Sight,
    catalogEntry: SightCatalogEntry? = null,
    selected: Boolean,
    onSelect: () -> Unit,
    onOpenPhoto: () -> Unit,
    canEdit: Boolean = true,
    onEdit: () -> Unit,
) {
    val displayedName = localizedSightName(sight.name)
    val displayedCategory = localizedSightCategory(
        sight.category.trim().takeIf { it.isNotBlank() }
            ?: catalogEntry?.category?.trim().orEmpty(),
    ).uppercase(Locale.ROOT)
    val displayedRating = catalogEntry?.rating ?: sight.rating
    val displayedRatingCount = catalogEntry?.ratingCount
    val language = LocalLanguage.current
    val uriHandler = LocalUriHandler.current
    val cardShape = RoundedCornerShape(18.dp)
    Row(
        verticalAlignment = Alignment.CenterVertically,
        horizontalArrangement = Arrangement.spacedBy(11.dp),
        modifier = Modifier
            .fillMaxWidth()
            .clip(cardShape)
            .background(if (selected) primaryColor().copy(alpha = 0.08f) else secondarySurfaceColor())
            .border(if (selected) 2.dp else 1.dp, if (selected) primaryColor().copy(alpha = 0.52f) else contentBorderColor(), cardShape)
            .padding(8.dp),
    ) {
        Box(modifier = Modifier.size(width = 96.dp, height = 112.dp).clip(RoundedCornerShape(14.dp))) {
            SightPhoto(
                sight = sight,
                modifier = Modifier.fillMaxSize(),
                onClick = onOpenPhoto,
            )
        }
        Column(modifier = Modifier.weight(1f).clickable { onSelect() }) {
            Text(
                displayedCategory,
                color = primaryColor(),
                fontFamily = Manrope,
                fontWeight = FontWeight.W800,
                fontSize = 9.5.sp,
                lineHeight = 12.sp,
                letterSpacing = 0.2.sp,
                style = androidx.compose.ui.text.TextStyle(platformStyle = OdysseyNoFontPadding),
                maxLines = 1,
                overflow = TextOverflow.Ellipsis,
            )
            Text(
                displayedName,
                color = contentTextColor(),
                fontFamily = Manrope,
                fontWeight = FontWeight.W800,
                fontSize = 15.sp,
                lineHeight = 18.sp,
                style = androidx.compose.ui.text.TextStyle(platformStyle = OdysseyNoFontPadding),
                maxLines = 2,
                overflow = TextOverflow.Ellipsis,
                modifier = Modifier.padding(top = 2.dp),
            )
            if (displayedRating != null || displayedRatingCount != null) {
                Row(
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.spacedBy(4.dp),
                    modifier = Modifier.padding(top = 5.dp),
                ) {
                    Text("★", color = Color(0xFFFFB52E), fontSize = 14.sp, fontWeight = FontWeight.W800)
                    displayedRating?.let {
                        Text(
                            String.format(Locale.ROOT, "%.1f", it),
                            color = contentTextColor(),
                            fontFamily = Manrope,
                            fontWeight = FontWeight.W800,
                            fontSize = 11.5.sp,
                            lineHeight = 17.sp,
                            style = androidx.compose.ui.text.TextStyle(platformStyle = OdysseyNoFontPadding),
                            maxLines = 1,
                            overflow = TextOverflow.Ellipsis,
                        )
                    }
                    displayedRatingCount?.let {
                        Text(
                            "· ${catalogRatingCountLabel(it, language)}",
                            color = secondaryTextColor(),
                            fontFamily = Manrope,
                            fontWeight = FontWeight.W600,
                            fontSize = 10.5.sp,
                            lineHeight = 15.sp,
                            style = androidx.compose.ui.text.TextStyle(platformStyle = OdysseyNoFontPadding),
                            maxLines = 1,
                            overflow = TextOverflow.Ellipsis,
                        )
                    }
                }
            }
            Text(
                localizedSightInfo(sight.name, sight.description, sight.category),
                color = secondaryTextColor(),
                fontFamily = Manrope,
                fontWeight = FontWeight.W600,
                fontSize = 11.5.sp,
                lineHeight = 15.sp,
                style = androidx.compose.ui.text.TextStyle(platformStyle = OdysseyNoFontPadding),
                maxLines = 2,
                overflow = TextOverflow.Ellipsis,
                modifier = Modifier.padding(top = 4.dp),
            )
            if (sight.link.isNotBlank()) {
                Row(
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.spacedBy(4.dp),
                    modifier = Modifier
                        .padding(top = 6.dp)
                        .clickable { uriHandler.openUri(sight.link) },
                ) {
                    Icon(Icons.Outlined.OpenInNew, contentDescription = null, tint = primaryColor(), modifier = Modifier.size(13.dp))
                    Text(
                        localized("Открыть ссылку", "Open link", "Abrir enlace", "Link öffnen"),
                        color = primaryColor(),
                        fontFamily = Manrope,
                        fontWeight = FontWeight.W800,
                        fontSize = 11.sp,
                        maxLines = 1,
                    )
                }
            }
        }
        if (canEdit) {
            Box(
                modifier = Modifier
                    .size(34.dp)
                    .clip(CircleShape)
                    .background(tintedSurfaceColor())
                    .clickable(onClick = onEdit),
                contentAlignment = Alignment.Center,
            ) {
                Icon(
                    Icons.Outlined.Edit,
                    contentDescription = localized("Редактировать", "Edit", "Editar", "Bearbeiten"),
                    tint = primaryColor(),
                    modifier = Modifier.size(17.dp),
                )
            }
        }
    }
}
@Composable
@OptIn(ExperimentalMaterial3Api::class)
private fun EditSightPanel(
    sight: com.odyssey.travelplanner.data.Sight,
    tripId: String,
    dayCities: List<String>,
    onClose: () -> Unit,
    onSaved: () -> Unit,
    modifier: Modifier = Modifier,
) {
    val context = LocalContext.current
    val language = LocalLanguage.current
    val displayedName = localizedSightName(sight.name)
    val displayedDescription = localizedSightDescription(sight.description)
    var name by remember(sight.id, language) { mutableStateOf(displayedName) }
    var description by remember(sight.id, language) { mutableStateOf(displayedDescription) }
    var link by remember(sight.id, language) { mutableStateOf(sight.link) }
    var selectedDay by remember(sight.id) { mutableStateOf(sight.walkDay.coerceAtLeast(1)) }
    var routeDayMenuOpen by remember(sight.id) { mutableStateOf(false) }
    val routeDayOptions = remember(dayCities) {
        dayCities.mapIndexed { index, dayCity -> index + 1 to dayCity }
    }
    val effectiveSelectedDay = selectedDay.takeIf { it in 1..routeDayOptions.size } ?: sight.walkDay.coerceAtLeast(1)
    val selectedDayCity = routeDayOptions.firstOrNull { it.first == effectiveSelectedDay }?.second
        .orEmpty()
        .ifBlank { sight.city }
    var selectedPoint by remember(sight.id) {
        mutableStateOf(
            sight.longitude?.let { longitude ->
                sight.latitude?.let { latitude -> Point.fromLngLat(longitude, latitude) }
            },
        )
    }
    var locationChanged by remember(sight.id) { mutableStateOf(false) }
    var locationPickerOpen by remember(sight.id) { mutableStateOf(false) }
    var selectedPhotoUri by remember(sight.id) { mutableStateOf<Uri?>(null) }
    var saving by remember { mutableStateOf(false) }
    var message by remember { mutableStateOf<String?>(null) }
    val scope = rememberCoroutineScope()
    val photoPicker = rememberLauncherForActivityResult(ActivityResultContracts.GetContent()) { uri ->
        if (uri != null) selectedPhotoUri = uri
    }
    Column(modifier = modifier.fillMaxWidth().clip(RoundedCornerShape(18.dp)).background(cardSurfaceColor()).padding(16.dp), verticalArrangement = Arrangement.spacedBy(10.dp)) {
        Text(localized("Редактировать место", "Edit sight", "Editar lugar", "Ort bearbeiten"), color = contentTextColor(), fontFamily = Manrope, fontWeight = FontWeight.W800, fontSize = 17.sp)
        AuthField(localized("Название", "Name", "Nombre", "Name"), localized("Название", "Name", "Nombre", "Name"), name) { name = it }
        SightRouteDayField(
            selectedDay = effectiveSelectedDay,
            selectedCity = selectedDayCity,
            options = routeDayOptions,
            expanded = routeDayMenuOpen,
            onExpandedChange = { routeDayMenuOpen = it },
            onDaySelected = {
                if (it != effectiveSelectedDay) {
                    selectedPoint = null
                    locationChanged = true
                }
                selectedDay = it
            },
        )
        SightLocationField(
            point = selectedPoint,
            onClick = { locationPickerOpen = true },
            modifier = Modifier.fillMaxWidth(),
        )
        AuthField(localized("Описание", "Description", "Descripción", "Beschreibung"), localized("Что важно увидеть", "What is important to see", "Qué es importante ver", "Was sehenswert ist"), description) { description = it }
        RouteEditorField(
            label = localized("Ссылка на достопримечательность", "Sight link", "Enlace del lugar", "Link zur Sehenswürdigkeit"),
            value = link,
            onValueChange = { value ->
                link = value
                sightLinkPoint(value)?.let {
                    selectedPoint = it
                    locationChanged = true
                }
                if (value.isBlank() && sight.link.isBlank()) selectedPoint = null
            },
            modifier = Modifier.fillMaxWidth(),
            placeholder = "https://maps.app.goo.gl/...",
        )
        Column(verticalArrangement = Arrangement.spacedBy(5.dp)) {
            Text(
                localized("Фото места", "Place photo", "Foto del lugar", "Foto des Ortes"),
                color = contentTextColor(),
                fontFamily = Manrope,
                fontWeight = FontWeight.W800,
                fontSize = 12.sp,
            )
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .height(78.dp)
                    .clip(RoundedCornerShape(14.dp))
                    .border(1.dp, contentBorderColor(), RoundedCornerShape(14.dp))
                    .background(cardSurfaceColor())
                    .clickable(enabled = !saving) { photoPicker.launch("image/*") }
                    .padding(7.dp),
                verticalAlignment = Alignment.CenterVertically,
                horizontalArrangement = Arrangement.spacedBy(12.dp),
            ) {
                Box(
                    modifier = Modifier
                        .size(64.dp)
                        .clip(RoundedCornerShape(10.dp))
                        .background(tintedSurfaceColor()),
                    contentAlignment = Alignment.Center,
                ) {
                    when {
                        selectedPhotoUri != null -> AsyncImage(
                            model = selectedPhotoUri,
                            contentDescription = localized("Выбранное фото", "Selected photo", "Foto seleccionada", "Ausgewähltes Foto"),
                            contentScale = androidx.compose.ui.layout.ContentScale.Crop,
                            modifier = Modifier.fillMaxSize(),
                        )
                        sight.photo.isNotBlank() -> SightPhoto(sight = sight, modifier = Modifier.fillMaxSize())
                        else -> Icon(Icons.Outlined.Image, contentDescription = null, tint = primaryColor(), modifier = Modifier.size(24.dp))
                    }
                }
                Column(modifier = Modifier.weight(1f)) {
                    Text(
                        if (sight.photo.isBlank() && selectedPhotoUri == null) {
                            localized("Добавить фото", "Add photo", "Añadir foto", "Foto hinzufügen")
                        } else {
                            localized("Заменить фото", "Replace photo", "Cambiar foto", "Foto ersetzen")
                        },
                        color = primaryColor(),
                        fontFamily = Manrope,
                        fontWeight = FontWeight.W800,
                        fontSize = 14.sp,
                    )
                    Text(
                        localized("Выберите изображение на устройстве", "Choose an image on your device", "Elige una imagen del dispositivo", "Bild auf dem Gerät auswählen"),
                        color = secondaryTextColor(),
                        fontFamily = Manrope,
                        fontWeight = FontWeight.W600,
                        fontSize = 11.sp,
                    )
                }
                Icon(Icons.Outlined.KeyboardArrowRight, contentDescription = null, tint = primaryColor(), modifier = Modifier.size(20.dp))
            }
        }
        if (message != null) Text(message!!, color = Color(0xFFE0524B), fontFamily = Manrope, fontWeight = FontWeight.W700, fontSize = 12.sp)
        Row(horizontalArrangement = Arrangement.spacedBy(10.dp)) {
            Button(onClick = onClose, colors = ButtonDefaults.buttonColors(containerColor = secondarySurfaceColor(), contentColor = contentTextColor()), shape = RoundedCornerShape(11.dp)) { Text(localized("Отмена", "Cancel", "Cancelar", "Abbrechen"), fontFamily = Manrope, fontWeight = FontWeight.W800) }
            Button(onClick = {
                scope.launch {
                    saving = true
                    val savedName = name.trim().takeUnless { it == displayedName } ?: sight.name.trim()
                    val savedCity = selectedDayCity.trim().ifBlank { sight.city.trim() }
                    val savedDescription = description.trim().takeUnless { it == displayedDescription } ?: sight.description.trim()
                    val savedLink = link.trim()
                    val linkChanged = savedLink != sight.link.trim()
                    var savedPoint = selectedPoint
                    if (linkChanged && savedLink.isNotBlank()) {
                        savedPoint = resolveSightLinkCoordinates(savedLink)?.let { coordinates ->
                            Point.fromLngLat(coordinates.longitude, coordinates.latitude)
                        } ?: error(localized(language, "Не удалось определить точку по ссылке. Выберите точку на карте.", "Could not find a map point in this link. Choose a point on the map.", "No se pudo encontrar el punto en el enlace. Elija un punto en el mapa.", "Im Link wurde kein Kartenpunkt gefunden. Wählen Sie einen Punkt auf der Karte."))
                        locationChanged = true
                    }
                    runCatching {
                        val repository = SupabaseTripRepository(SupabaseProvider.clientForCurrentAuthFlow())
                        repository.updateSightDetailsRich(
                            id = tripId,
                            sightId = sight.id,
                            name = savedName,
                            city = savedCity,
                            category = sight.category.trim(),
                            description = savedDescription,
                            walkDay = effectiveSelectedDay,
                            longitude = savedPoint?.longitude(),
                            latitude = savedPoint?.latitude(),
                            locationChanged = locationChanged,
                            link = savedLink,
                        )
                        selectedPhotoUri?.let { uri ->
                            val bytes = context.contentResolver.openInputStream(uri)?.use { it.readBytes() }
                                ?: error(localized(language, "Не удалось прочитать изображение", "Could not read the image", "No se pudo leer la imagen", "Das Bild konnte nicht gelesen werden"))
                            repository.addSightPhoto(tripId, sight.id, bytes)
                        }
                    }
                        .onSuccess { onSaved() }
                        .onFailure { message = localizedFailure(language, it, localized(language, "Не удалось сохранить место", "Could not save sight", "No se pudo guardar el lugar", "Ort konnte nicht gespeichert werden")) }
                    saving = false
                }
            }, enabled = !saving, colors = ButtonDefaults.buttonColors(containerColor = primaryColor(), contentColor = primaryContentColor()), shape = RoundedCornerShape(11.dp)) { Text(if (saving) localized("Сохраняем…", "Saving…", "Guardando…", "Wird gespeichert…") else localized("Сохранить", "Save", "Guardar", "Speichern"), fontFamily = Manrope, fontWeight = FontWeight.W800) }
        }
    }
    if (locationPickerOpen) {
        ModalBottomSheet(
            onDismissRequest = { locationPickerOpen = false },
            sheetState = rememberModalBottomSheetState(skipPartiallyExpanded = true),
            containerColor = cardSurfaceColor(),
            dragHandle = null,
        ) {
            SightLocationPickerSheet(
                city = selectedDayCity.ifBlank { sight.city },
                initialPoint = selectedPoint,
                onClose = { locationPickerOpen = false },
                onConfirm = { point ->
                    selectedPoint = point
                    locationChanged = true
                    locationPickerOpen = false
                },
            )
        }
    }
}

@Composable
private fun SightRouteDayField(
