    ModalBottomSheet(onDismissRequest = onDismiss, sheetState = rememberModalBottomSheetState(skipPartiallyExpanded = true), containerColor = cardSurfaceColor()) {
        Column(modifier = Modifier.fillMaxWidth().verticalScroll(rememberScrollState()).imePadding().padding(horizontal = 18.dp, vertical = 8.dp)) {
            Row(verticalAlignment = Alignment.CenterVertically, modifier = Modifier.fillMaxWidth()) { Text(if (initial == null) localized("Добавить место", "Add a place", "Añadir un lugar", "Ort hinzufügen") else localized("Редактировать место", "Edit place", "Editar lugar", "Ort bearbeiten"), color = contentTextColor(), fontFamily = Manrope, fontWeight = FontWeight.W800, fontSize = 20.sp, modifier = Modifier.weight(1f)); IconButton(onClick = onDismiss) { Icon(Icons.Filled.Close, contentDescription = null, tint = secondaryTextColor()) } }
            OutlinedTextField(value = name, onValueChange = { name = it }, modifier = Modifier.fillMaxWidth().padding(top = 10.dp), singleLine = true, label = { Text(localized("Название *", "Name *", "Nombre *", "Name *")) }, shape = RoundedCornerShape(12.dp))
            OutlinedTextField(value = city, onValueChange = { city = it }, modifier = Modifier.fillMaxWidth().padding(top = 9.dp), singleLine = true, label = { Text(localized("Город *", "City *", "Ciudad *", "Stadt *")) }, shape = RoundedCornerShape(12.dp))
            Text(localized("Тип", "Type", "Tipo", "Typ"), color = labelColor(), fontFamily = Manrope, fontWeight = FontWeight.W800, fontSize = 13.sp, modifier = Modifier.padding(top = 14.dp, bottom = 7.dp))
            Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) { PetChoiceChip(localized("Зоомагазин", "Pet shop", "Tienda", "Zoohandlung"), type == "shop") { type = "shop" }; PetChoiceChip(localized("Ветеринар", "Veterinarian", "Veterinario", "Tierarzt"), type == "vet") { type = "vet" } }
            OutlinedTextField(value = address, onValueChange = { address = it }, modifier = Modifier.fillMaxWidth().padding(top = 9.dp), singleLine = true, label = { Text(localized("Адрес", "Address", "Dirección", "Adresse")) }, shape = RoundedCornerShape(12.dp))
            OutlinedTextField(value = phone, onValueChange = { phone = it }, modifier = Modifier.fillMaxWidth().padding(top = 9.dp), singleLine = true, label = { Text(localized("Телефон", "Phone", "Teléfono", "Telefon")) }, shape = RoundedCornerShape(12.dp))
            OutlinedTextField(value = mapsUrl, onValueChange = { mapsUrl = it }, modifier = Modifier.fillMaxWidth().padding(top = 9.dp), singleLine = true, label = { Text(localized("Ссылка на Google Карты", "Google Maps link", "Enlace de Google Maps", "Google-Maps-Link")) }, shape = RoundedCornerShape(12.dp))
            OutlinedTextField(value = website, onValueChange = { website = it }, modifier = Modifier.fillMaxWidth().padding(top = 9.dp), singleLine = true, label = { Text(localized("Сайт", "Website", "Sitio web", "Website")) }, shape = RoundedCornerShape(12.dp))
            OutlinedTextField(value = note, onValueChange = { note = it }, modifier = Modifier.fillMaxWidth().padding(top = 9.dp), minLines = 2, label = { Text(localized("Заметка", "Note", "Nota", "Notiz")) }, shape = RoundedCornerShape(12.dp))
            Button(onClick = { if (name.isNotBlank() && city.isNotBlank()) onSave(PetPlaceInput(name = name, city = city, type = type, address = address, phone = phone, mapsUrl = mapsUrl, website = website, source = initial?.source ?: "manual", googlePlaceId = initial?.googlePlaceId.orEmpty(), photoName = initial?.photoName.orEmpty(), note = note, features = initial?.features.orEmpty())) }, enabled = !saving && name.isNotBlank() && city.isNotBlank(), modifier = Modifier.fillMaxWidth().padding(top = 18.dp, bottom = 18.dp), shape = RoundedCornerShape(13.dp), colors = ButtonDefaults.buttonColors(containerColor = primaryColor())) { Text(if (saving) localized("Сохраняем…", "Saving…", "Guardando…", "Speichern…") else localized("Сохранить", "Save", "Guardar", "Speichern"), color = primaryContentColor(), fontFamily = Manrope, fontWeight = FontWeight.W800) }
        }
    }
}

@Composable
@OptIn(ExperimentalMaterial3Api::class)
private fun RestaurantsContent(tripId: String, overview: TripOverview, canEdit: Boolean = true, onRestaurantAdded: () -> Unit) {
    val context = LocalContext.current
    val language = LocalLanguage.current
    val dashedBorderColor = contentBorderColor()
    var adding by remember { mutableStateOf(false) }
    var name by remember { mutableStateOf("") }
    var city by remember { mutableStateOf("") }
    var cuisine by remember { mutableStateOf("") }
    var dateTime by remember { mutableStateOf("") }
    var restaurantDatePickerOpen by remember { mutableStateOf(false) }
    var address by remember { mutableStateOf("") }
    var status by remember { mutableStateOf("хочу") }
    var priority by remember { mutableStateOf(false) }
    var price by remember { mutableStateOf("€€") }
    var newRestaurantPhotoUris by remember { mutableStateOf<List<Uri>>(emptyList()) }
    var saving by remember { mutableStateOf(false) }
    var message by remember { mutableStateOf<String?>(null) }
    var actionMessage by remember { mutableStateOf<String?>(null) }
    var savingRestaurantId by remember { mutableStateOf<String?>(null) }
    var editingRestaurant by remember { mutableStateOf<com.odyssey.travelplanner.data.Restaurant?>(null) }
    var cityPickerOpen by remember { mutableStateOf(false) }
    var restaurantCatalogOpen by remember { mutableStateOf(false) }
    var openCatalogAfterCitySelection by remember { mutableStateOf(false) }
    var uploadingRestaurantId by remember { mutableStateOf<String?>(null) }
    var selectedCity by remember { mutableStateOf("Все города") }
    var cityMenuOpen by remember { mutableStateOf(false) }
    var filterMenuOpen by remember { mutableStateOf(false) }
    var priceFilter by remember { mutableStateOf("") }
    var ratingFilter by remember { mutableStateOf("") }
    var appliedTypeFilter by remember { mutableStateOf("Ресторан") }
    var appliedFeatureFilters by remember { mutableStateOf(setOf<String>()) }
    var draftTypeFilter by remember { mutableStateOf("Ресторан") }
    var draftFeatureFilters by remember { mutableStateOf(emptySet<String>()) }
    var draftPriceFilter by remember { mutableStateOf("") }
    var draftRatingFilter by remember { mutableStateOf("") }
    val scope = rememberCoroutineScope()

    fun resetRestaurantForm() {
        name = ""
        city = ""
        cuisine = ""
        dateTime = ""
        restaurantDatePickerOpen = false
        address = ""
        status = "хочу"
        priority = false
        price = "€€"
        newRestaurantPhotoUris = emptyList()
        message = null
        cityPickerOpen = false
        restaurantCatalogOpen = false
        openCatalogAfterCitySelection = false
    }

    fun closeRestaurantForm() {
        adding = false
        resetRestaurantForm()
    }

    val tripCityOptions = (
        overview.cities +
            overview.routeLegs.flatMap { listOf(it.from, it.to) } +
        overview.sights.map { it.city } +
            overview.accommodations.map { it.city } +
            overview.restaurants.map { it.city }
        ).flatMap(::splitStoredCityList).map(String::trim).filter(String::isNotBlank).distinctBy(::cityFilterKey)
    val cityOptions = listOf("Все города") + tripCityOptions
    val cityCounts = cityOptions.associateWith { option ->
        if (option == cityOptions.first()) {
            overview.restaurants.size
        } else {
            overview.restaurants.count { restaurant -> cityFilterKey(restaurant.city) == cityFilterKey(option) }
        }
    }
    val visibleRestaurants = overview.restaurants.filter { restaurant ->
        val note = restaurant.note.lowercase()
        val typeMatches = when (appliedTypeFilter) {
            "Бар" -> note.contains("бар") || note.contains("bar")
            "Кафе" -> note.contains("кафе") || note.contains("cafe")
            else -> true
        }
        val featureMatches = appliedFeatureFilters.all { feature ->
            when (feature) {
                "priority" -> restaurant.priority || note.contains("приоритет") || note.contains("priority")
                "dog" -> note.contains("с собакой") || note.contains("dog")
                "reservation" -> restaurant.status == "бронь" || note.contains("бронь") || note.contains("reserv")
                "vegan" -> note.contains("веган") || note.contains("vegan")
                else -> true
            }
        }
        val ratingMatches = ratingFilter.isBlank() || (restaurant.rating ?: 0.0) >= (ratingFilter.removeSuffix("+").toDoubleOrNull() ?: 0.0)
        (selectedCity == "Все города" || cityFilterKey(restaurant.city) == cityFilterKey(selectedCity)) &&
            typeMatches &&
            featureMatches &&
            (priceFilter.isBlank() || restaurant.price == priceFilter) &&
            ratingMatches
    }
    val filterCount = listOf(
        appliedTypeFilter != "Ресторан",
        priceFilter.isNotBlank(),
        ratingFilter.isNotBlank(),
    ).count { it } + appliedFeatureFilters.size
    val photoPicker = rememberLauncherForActivityResult(ActivityResultContracts.GetMultipleContents()) { uris ->
        val restaurantId = uploadingRestaurantId ?: return@rememberLauncherForActivityResult
        if (uris.isEmpty()) {
            uploadingRestaurantId = null
            return@rememberLauncherForActivityResult
        }
        scope.launch {
            runCatching {
                val repository = SupabaseTripRepository(SupabaseProvider.clientForCurrentAuthFlow())
                uris.forEach { uri ->
                val bytes = context.contentResolver.openInputStream(uri)?.use { it.readBytes() }
                    ?: error("Не удалось прочитать изображение")
                repository.addRestaurantPhoto(tripId, restaurantId, bytes)
                }
            }.onSuccess {
                actionMessage = null
                onRestaurantAdded()
            }.onFailure {
                actionMessage = localizedFailure(language, it, localized(language, "Не удалось загрузить фото. Проверьте интернет и повторите попытку.", "Could not upload the photo. Check your connection and try again.", "No se pudo subir la foto. Comprueba la conexión e inténtalo de nuevo.", "Foto konnte nicht hochgeladen werden. Prüfen Sie die Verbindung und versuchen Sie es erneut."))
            }
            uploadingRestaurantId = null
        }
    }
    val newRestaurantPhotoPicker = rememberLauncherForActivityResult(ActivityResultContracts.GetMultipleContents()) { uris ->
        if (uris.isNotEmpty()) {
            newRestaurantPhotoUris = (newRestaurantPhotoUris + uris).distinctBy(Uri::toString)
        }
    }
    LazyColumn(
        contentPadding = androidx.compose.foundation.layout.PaddingValues(
            start = 18.dp,
            top = 18.dp,
            end = 18.dp,
            bottom = 30.dp + WindowInsets.navigationBars.asPaddingValues().calculateBottomPadding(),
        ),
        verticalArrangement = Arrangement.spacedBy(0.dp),
        modifier = Modifier.fillMaxSize(),
    ) {
        if (canEdit) item {
            Row(
                modifier = Modifier.fillMaxWidth().height(44.dp),
                horizontalArrangement = Arrangement.spacedBy(9.dp),
            ) {
                Row(
                    modifier = Modifier
                        .weight(1.31f)
                        .fillMaxHeight()
                        .shadow(5.dp, RoundedCornerShape(13.dp), clip = false, ambientColor = Color(0x476C5CE7), spotColor = Color(0x476C5CE7))
                        .clip(RoundedCornerShape(13.dp))
                        .background(Brush.linearGradient(listOf(primaryColor(), Color(0xFF7D6CF0))))
                        .clickable { cityMenuOpen = !cityMenuOpen }
                        .padding(horizontal = 13.dp, vertical = 11.dp),
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.spacedBy(8.dp),
                ) {
                    OdysseyLocationIcon(15.dp, primaryContentColor())
                    Text(
                        localizedCityFilter(selectedCity),
                        color = primaryContentColor(),
                        fontFamily = Manrope,
                        fontWeight = FontWeight.W800,
                        fontSize = 14.sp,
                        lineHeight = 19.sp,
                        style = androidx.compose.ui.text.TextStyle(platformStyle = OdysseyNoFontPadding),
                        maxLines = 1,
                        overflow = TextOverflow.Ellipsis,
                        modifier = Modifier.weight(1f),
                    )
                    OdysseyChevronDown(16.dp, primaryContentColor())
                }
                Row(
                    modifier = Modifier
                        .weight(1f)
                        .fillMaxHeight()
                        .clip(RoundedCornerShape(13.dp))
                        .background(cardSurfaceColor())
                        .border(1.dp, contentBorderColor(), RoundedCornerShape(13.dp))
                        .clickable {
                            cityMenuOpen = false
                            filterMenuOpen = true
                        }
                        .padding(horizontal = 13.dp, vertical = 11.dp),
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.spacedBy(7.dp),
                ) {
                    OdysseyFilterIcon(15.dp)
                    Text(
                        localized("Фильтры", "Filters", "Filtros", "Filter"),
                        color = labelColor(),
                        fontFamily = Manrope,
                        fontWeight = FontWeight.W800,
                        fontSize = 14.sp,
                        lineHeight = 19.sp,
                        style = androidx.compose.ui.text.TextStyle(platformStyle = OdysseyNoFontPadding),
                    )
                    Box(
                        modifier = Modifier.size(20.dp).clip(RoundedCornerShape(10.dp)).background(primaryColor()),
                        contentAlignment = Alignment.Center,
                    ) {
                        Text(
                            filterCount.toString(),
                            color = primaryContentColor(),
                            fontFamily = Manrope,
                            fontWeight = FontWeight.W800,
                            fontSize = 11.sp,
                            lineHeight = 14.sp,
                            style = androidx.compose.ui.text.TextStyle(platformStyle = OdysseyNoFontPadding),
                        )
                    }
                }
            }
        }
        item {
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(top = 12.dp)
                    .height(47.dp)
                    .clip(RoundedCornerShape(14.dp))
                    .background(tintedSurfaceColor())
                    .drawBehind {
                        val stroke = 1.5.dp.toPx()
                        drawRoundRect(
                            color = dashedBorderColor,
                            topLeft = Offset(stroke / 2f, stroke / 2f),
                            size = androidx.compose.ui.geometry.Size(size.width - stroke, size.height - stroke),
                            cornerRadius = CornerRadius(14.dp.toPx() - stroke / 2f),
                            style = Stroke(
                                width = stroke,
                                pathEffect = PathEffect.dashPathEffect(floatArrayOf(6.dp.toPx(), 4.dp.toPx())),
                            ),
                        )
                    }
                    .clickable { resetRestaurantForm(); adding = true; actionMessage = null },
                verticalAlignment = Alignment.CenterVertically,
                horizontalArrangement = Arrangement.Center,
            ) {
                OdysseyPlusIcon(18.dp)
                Text(
                    localized("Добавить ресторан", "Add restaurant", "Añadir restaurante", "Restaurant hinzufügen"),
                    color = primaryColor(),
                    fontFamily = Manrope,
                    fontWeight = FontWeight.W800,
                    fontSize = 14.5.sp,
                    lineHeight = 19.sp,
                    style = androidx.compose.ui.text.TextStyle(platformStyle = OdysseyNoFontPadding),
                    modifier = Modifier.padding(start = 8.dp),
                )
            }
        }
        if (actionMessage != null) {
            item {
                Text(actionMessage!!, color = Color(0xFFE0524B), fontFamily = Manrope, fontWeight = FontWeight.W700, fontSize = 12.sp, modifier = Modifier.padding(top = 10.dp))
            }
        }
        item {
            RestaurantMapCard(
                restaurants = visibleRestaurants,
                cityCoordinates = overview.cityCoordinates,
                modifier = Modifier.padding(top = 11.dp),
            )
        }
        if (visibleRestaurants.isEmpty()) {
            item {
                EmptyStateCard(
                    icon = Icons.Outlined.Restaurant,
                    title = if (overview.restaurants.isEmpty()) localized("Рестораны пока не добавлены", "No restaurants added yet", "Aún no se han añadido restaurantes", "Noch keine Restaurants hinzugefügt") else localized("Ничего не найдено", "Nothing found", "No se encontró nada", "Nichts gefunden"),
                    body = localized("Добавьте место или измените фильтры", "Add a place or change the filters", "Añada un lugar o cambie los filtros", "Fügen Sie einen Ort hinzu oder ändern Sie die Filter"),
                )
            }
        } else {
            itemsIndexed(visibleRestaurants, key = { _, restaurant -> restaurant.id }) { index, restaurant ->
                RestaurantCard(
                    restaurant,
                    savingRestaurantId == restaurant.id,
                    uploadingRestaurantId == restaurant.id,
                    canEdit = canEdit,
                    onEdit = { if (canEdit) editingRestaurant = restaurant },
                    onAddPhoto = { uploadingRestaurantId = restaurant.id; photoPicker.launch("image/*") },
                    modifier = Modifier.padding(top = if (index == 0) 16.dp else 13.dp),
                ) { status ->
                    scope.launch {
                        savingRestaurantId = restaurant.id
                        runCatching { SupabaseTripRepository(SupabaseProvider.clientForCurrentAuthFlow()).updateRestaurantStatus(tripId, restaurant.id, status) }
                            .onSuccess {
                                actionMessage = null
                                onRestaurantAdded()
                            }
                            .onFailure {
                                actionMessage = localizedFailure(language, it, localized(language, "Не удалось сохранить статус. Проверьте интернет и повторите попытку.", "Could not save the status. Check your connection and try again.", "No se pudo guardar el estado. Comprueba la conexión e inténtalo de nuevo.", "Status konnte nicht gespeichert werden. Prüfen Sie die Verbindung und versuchen Sie es erneut."))
                            }
                        savingRestaurantId = null
                    }
                }
            }
        }
    }
    if (cityMenuOpen) {
        ModalBottomSheet(
            onDismissRequest = { cityMenuOpen = false },
            sheetState = rememberModalBottomSheetState(skipPartiallyExpanded = true),
            containerColor = cardSurfaceColor(),
            tonalElevation = 0.dp,
            scrimColor = Color(0x730F0F19),
            shape = RoundedCornerShape(topStart = 26.dp, topEnd = 26.dp),
            dragHandle = null,
        ) {
            RestaurantCityFilterSheet(
                options = cityOptions,
                counts = cityCounts,
                selectedCity = selectedCity,
                onSelect = { option -> selectedCity = option; cityMenuOpen = false },
                onClose = { cityMenuOpen = false },
            )
        }
    }
    if (canEdit && editingRestaurant != null) {
        ModalBottomSheet(
            onDismissRequest = { editingRestaurant = null },
            sheetState = rememberModalBottomSheetState(skipPartiallyExpanded = true),
            containerColor = cardSurfaceColor(),
            tonalElevation = 0.dp,
            scrimColor = Color(0x730F0F19),
            shape = RoundedCornerShape(topStart = 29.dp, topEnd = 29.dp),
            dragHandle = null,
        ) {
            RestaurantEditSheet(
                restaurant = editingRestaurant!!,
                tripId = tripId,
                cityOptions = tripCityOptions,
                onClose = { editingRestaurant = null },
                onPhotosUpdated = onRestaurantAdded,
                onSaved = {
                    editingRestaurant = null
                    onRestaurantAdded()
                },
            )
        }
    }
    if (filterMenuOpen) {
        ModalBottomSheet(
            onDismissRequest = { filterMenuOpen = false },
            sheetState = rememberModalBottomSheetState(skipPartiallyExpanded = true),
            containerColor = cardSurfaceColor(),
            tonalElevation = 0.dp,
            scrimColor = Color(0x730F0F19),
            shape = RoundedCornerShape(topStart = 29.dp, topEnd = 29.dp),
            dragHandle = null,
        ) {
            RestaurantFilterSheet(
                type = draftTypeFilter,
                features = draftFeatureFilters,
                price = draftPriceFilter,
                rating = draftRatingFilter,
                onTypeChange = { draftTypeFilter = it },
                onFeatureToggle = { feature ->
                    draftFeatureFilters = if (feature in draftFeatureFilters) draftFeatureFilters - feature else draftFeatureFilters + feature
                },
                onPriceChange = { draftPriceFilter = it },
                onRatingChange = { draftRatingFilter = it },
                onReset = {
                    draftTypeFilter = "Ресторан"
                    draftFeatureFilters = emptySet()
                    draftPriceFilter = ""
                    draftRatingFilter = ""
                },
                onApply = {
                    appliedTypeFilter = draftTypeFilter
                    appliedFeatureFilters = draftFeatureFilters
                    priceFilter = draftPriceFilter
                    ratingFilter = draftRatingFilter
                    filterMenuOpen = false
                },
            )
        }
    }
    if (canEdit && adding) {
        ModalBottomSheet(
            onDismissRequest = ::closeRestaurantForm,
            sheetState = rememberModalBottomSheetState(skipPartiallyExpanded = true),
            containerColor = cardSurfaceColor(),
            tonalElevation = 0.dp,
            scrimColor = Color(0x730F0F19),
            shape = RoundedCornerShape(topStart = 29.dp, topEnd = 29.dp),
            dragHandle = null,
        ) {
            RestaurantAddSheet(
                name = name,
                city = city,
                cuisine = cuisine,
                dateTime = dateTime,
                price = price,
                address = address,
                status = status,
                priority = priority,
                photoUris = newRestaurantPhotoUris,
                saving = saving,
                message = message,
                onNameChange = { name = it },
                onCityChange = { city = it },
                onCityPickerOpen = {
                    openCatalogAfterCitySelection = false
                    cityPickerOpen = true
                },
                onDatePickerOpen = {
                    restaurantDatePickerOpen = true
                },
                onCuisineChange = { cuisine = it },
                onDateTimeChange = { dateTime = it },
                onPriceChange = { price = it },
                onAddressChange = { address = it },
                onStatusChange = { status = it },
                onPriorityChange = { priority = !priority },
                onPickPhoto = { newRestaurantPhotoPicker.launch("image/*") },
                onCatalogOpen = {
                    if (city.isBlank()) {
                        openCatalogAfterCitySelection = true
                        cityPickerOpen = true
                    } else {
                        openCatalogAfterCitySelection = false
                        restaurantCatalogOpen = true
                    }
                },
                onClose = ::closeRestaurantForm,
                onSave = {
                    scope.launch {
                        saving = true
                        var createdRestaurantId: String? = null
                        runCatching {
                            val repository = SupabaseTripRepository(SupabaseProvider.clientForCurrentAuthFlow())
                            val restaurantId = repository.addRestaurantDetails(
                                com.odyssey.travelplanner.data.RestaurantInput(
                                    name = name,
                                    city = city,
                                    status = status,
                                    note = cuisine,
                                    price = price,
                                    link = address,
                                    date = dateTime,
                                    priority = priority,
                                ),
                                tripId,
                            )
                            createdRestaurantId = restaurantId
                            newRestaurantPhotoUris.forEach { uri ->
                                val bytes = context.contentResolver.openInputStream(uri)?.use { it.readBytes() }
                                    ?: error("Не удалось прочитать изображение")
                                repository.addRestaurantPhoto(tripId, restaurantId, bytes)
                            }
                        }.onSuccess {
                            closeRestaurantForm()
                            onRestaurantAdded()
                        }.onFailure {
                            createdRestaurantId?.let { restaurantId ->
                                runCatching {
                                    SupabaseTripRepository(SupabaseProvider.clientForCurrentAuthFlow())
                                        .deleteTripItem(tripId, "restaurants", restaurantId)
                                }
                            }
                            message = localizedFailure(language, it, localized(language, "Не удалось сохранить ресторан", "Could not save restaurant", "No se pudo guardar el restaurante", "Restaurant konnte nicht gespeichert werden"))
                        }
                        saving = false
                    }
                },
            )
        }
    }
    if (canEdit && adding && restaurantDatePickerOpen) {
        AccommodationCalendarDialog(
            initialValue = dateTime,
            onDismiss = { restaurantDatePickerOpen = false },
            onConfirm = { selectedDate ->
                dateTime = selectedDate
                restaurantDatePickerOpen = false
            },
        )
    }
    if (canEdit && adding && cityPickerOpen) {
        ModalBottomSheet(
            onDismissRequest = { cityPickerOpen = false },
            sheetState = rememberModalBottomSheetState(skipPartiallyExpanded = true),
            containerColor = cardSurfaceColor(),
            tonalElevation = 0.dp,
            scrimColor = Color(0x730F0F19),
            shape = RoundedCornerShape(topStart = 29.dp, topEnd = 29.dp),
            dragHandle = null,
        ) {
            RestaurantAddCitySheet(
                options = tripCityOptions,
                selectedCity = city,
                onSelect = { option ->
                    city = option
                    cityPickerOpen = false
                    if (openCatalogAfterCitySelection) {
                        openCatalogAfterCitySelection = false
                        restaurantCatalogOpen = true
                    }
                },
                onClose = { cityPickerOpen = false },
            )
        }
    }
    if (canEdit && adding && restaurantCatalogOpen) {
        ModalBottomSheet(
            onDismissRequest = { restaurantCatalogOpen = false },
            sheetState = rememberModalBottomSheetState(skipPartiallyExpanded = true),
            containerColor = cardSurfaceColor(),
            tonalElevation = 0.dp,
            scrimColor = Color(0x730F0F19),
            shape = RoundedCornerShape(topStart = 29.dp, topEnd = 29.dp),
            dragHandle = null,
        ) {
            RestaurantCatalogSheet(
                city = city,
                onSelect = { entry ->
                    name = entry.name(language)
                    cuisine = entry.cuisine
                    address = entry.address
                    restaurantCatalogOpen = false
                    message = null
                },
                onClose = { restaurantCatalogOpen = false },
            )
        }
    }
}

@Composable
private fun RestaurantAddCitySheet(
    options: List<String>,
    selectedCity: String,
    onSelect: (String) -> Unit,
    onClose: () -> Unit,
) {
    val navigationBarInset = WindowInsets.navigationBars.asPaddingValues().calculateBottomPadding()
    BoxWithConstraints(Modifier.fillMaxWidth()) {
        val maxSheetHeight = maxHeight * 0.8f
        Column(
            modifier = Modifier
                .fillMaxWidth()
                .heightIn(max = maxSheetHeight)
                .verticalScroll(rememberScrollState())
                .padding(start = 16.dp, top = 20.dp, end = 16.dp, bottom = 18.dp + navigationBarInset),
            verticalArrangement = Arrangement.spacedBy(9.dp),
        ) {
            Box(
                modifier = Modifier
                    .align(Alignment.CenterHorizontally)
                    .size(40.dp, 4.dp)
                    .clip(RoundedCornerShape(2.dp))
                    .background(contentBorderColor()),
            )
            Row(
                modifier = Modifier.fillMaxWidth().padding(bottom = 14.dp),
                verticalAlignment = Alignment.CenterVertically,
                horizontalArrangement = Arrangement.SpaceBetween,
            ) {
                Text(
                    text = localized("\u0413\u043e\u0440\u043e\u0434", "City", "Ciudad", "Stadt"),
                    color = contentTextColor(),
                    fontFamily = Manrope,
                    fontWeight = FontWeight.W800,
                    fontSize = 22.sp,
                    lineHeight = 30.sp,
                    style = androidx.compose.ui.text.TextStyle(platformStyle = OdysseyNoFontPadding),
                )
                Box(
                    modifier = Modifier
                        .size(34.dp)
                        .clip(CircleShape)
                        .background(secondarySurfaceColor())
                        .clickable(onClick = onClose),
                    contentAlignment = Alignment.Center,
                ) {
                    Icon(
                        Icons.Filled.Close,
                        contentDescription = localized("\u0417\u0430\u043a\u0440\u044b\u0442\u044c", "Close", "Cerrar", "Schlie\u00dfen"),
                        tint = secondaryTextColor(),
                        modifier = Modifier.size(16.dp),
                    )
                }
            }
            if (options.isEmpty()) {
                Text(
                    text = localized("\u0412 \u043f\u043e\u0435\u0437\u0434\u043a\u0435 \u043f\u043e\u043a\u0430 \u043d\u0435\u0442 \u0433\u043e\u0440\u043e\u0434\u043e\u0432", "No cities in this trip yet", "Aún no hay ciudades en este viaje", "Noch keine Städte in dieser Reise"),
                    color = secondaryTextColor(),
                    fontFamily = Manrope,
                    fontWeight = FontWeight.W600,
                    fontSize = 14.sp,
                    lineHeight = 20.sp,
                    modifier = Modifier.padding(vertical = 8.dp),
                )
            } else {
                options.forEach { option ->
                    val active = option == selectedCity
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .clip(RoundedCornerShape(14.dp))
                            .background(if (active) tintedSurfaceColor() else cardSurfaceColor())
                            .border(1.6.dp, if (active) primaryColor() else contentBorderColor(), RoundedCornerShape(14.dp))
                            .clickable { onSelect(option) }
                            .padding(horizontal = 15.dp, vertical = 14.dp),
                        verticalAlignment = Alignment.CenterVertically,
                    ) {
                        Text(
                            text = localizedCityName(option),
                            color = if (active) primaryColor() else contentTextColor(),
                            fontFamily = Manrope,
                            fontWeight = FontWeight.W800,
                            fontSize = 15.5.sp,
                            lineHeight = 20.sp,
                            style = androidx.compose.ui.text.TextStyle(platformStyle = OdysseyNoFontPadding),
                            modifier = Modifier.weight(1f),
                        )
                        if (active) {
                            Box(
                                modifier = Modifier.size(22.dp).clip(CircleShape).background(primaryColor()),
                                contentAlignment = Alignment.Center,
                            ) {
                                Icon(Icons.Filled.Check, contentDescription = null, tint = primaryContentColor(), modifier = Modifier.size(14.dp))
                            }
                        }
                    }
                }
            }
        }
    }
}

@Composable
private fun OdysseySortIcon(tint: Color? = null) {
    val resolvedTint = tint ?: primaryColor()
    Canvas(modifier = Modifier.size(20.dp)) {
        val strokeWidth = 1.8.dp.toPx()
        val left = 2.dp.toPx()
        val right = size.width - 2.dp.toPx()
        val y1 = 4.dp.toPx()
        val y2 = 9.dp.toPx()
        val y3 = 14.dp.toPx()
        drawLine(resolvedTint, Offset(left, y1), Offset(right, y1), strokeWidth, StrokeCap.Round)
        drawLine(resolvedTint, Offset(left, y2), Offset(left + (right - left) * 0.72f, y2), strokeWidth, StrokeCap.Round)
        drawLine(resolvedTint, Offset(left, y3), Offset(left + (right - left) * 0.46f, y3), strokeWidth, StrokeCap.Round)
    }
}

@Composable
@OptIn(ExperimentalMaterial3Api::class)
private fun RestaurantCatalogSheet(
    city: String,
    onSelect: (RestaurantCatalogEntry) -> Unit,
    onClose: () -> Unit,
) {
    val language = LocalLanguage.current
    val uriHandler = LocalUriHandler.current
    val catalogRepository = remember { RestaurantCatalogRepository(SupabaseProvider.clientForCurrentAuthFlow()) }
    var query by remember { mutableStateOf("") }
    var entries by remember { mutableStateOf<List<RestaurantCatalogEntry>>(emptyList()) }
    var loading by remember { mutableStateOf(true) }
    var message by remember { mutableStateOf<String?>(null) }
    var liveRatingsAvailable by remember { mutableStateOf(false) }
    var fullScreenRestaurantPhoto by remember { mutableStateOf<Pair<String, String>?>(null) }
    var sortMenuOpen by remember(city) { mutableStateOf(false) }
    var sortMode by remember(city) { mutableStateOf("rating") }
    val deviceLocation = LocalDeviceLocation.current
    val sortRatingLabel = localized("По рейтингу", "By rating", "Por valoración", "Nach Bewertung")
    val sortPriceLabel = localized("По цене", "By price", "Por precio", "Nach Preis")
    val sortButtonLabel = localized("Сортировать", "Sort", "Ordenar", "Sortieren")
    val sortedEntries = when (sortMode) {
        "price" -> entries.sortedWith(
            compareBy<RestaurantCatalogEntry> { entry -> deviceLocation?.let { location -> distanceMeters(location, entry.latitude, entry.longitude) } ?: Double.MAX_VALUE }
                .thenBy { it.priceLevel ?: Int.MAX_VALUE }
                .thenByDescending { it.rating ?: -1.0 }
                .thenBy { it.sortOrder },
        )
        else -> entries.sortedWith(
            compareBy<RestaurantCatalogEntry> { entry -> deviceLocation?.let { location -> distanceMeters(location, entry.latitude, entry.longitude) } ?: Double.MAX_VALUE }
                .thenByDescending { it.rating ?: -1.0 }
                .thenByDescending { it.ratingCount ?: 0 }
                .thenBy { it.sortOrder },
        )
    }
    val liveRatingsUnavailableMessage = localized(
        "Рейтинг и фото Google временно недоступны — показан каталог ресторанов",
        "Google ratings and photos are temporarily unavailable — showing the restaurant catalog",
        "Las valoraciones y fotos de Google no están disponibles temporalmente — se muestra el catálogo",
        "Google-Bewertungen und Fotos sind vorübergehend nicht verfügbar — der Katalog wird angezeigt",
    )

    LaunchedEffect(city, query, language) {
        loading = true
        message = null
        delay(180)
        runCatching { catalogRepository.search(city = city, query = query) }
            .onSuccess { localEntries ->
                entries = localEntries
                liveRatingsAvailable = false
                loading = false
                val liveEntries = try {
                    catalogRepository.searchLiveRatings(city = city, query = query, language = language)
                } catch (error: CancellationException) {
                    throw error
                } catch (_: Throwable) {
                    message = liveRatingsUnavailableMessage
                    emptyList()
                }
                if (liveEntries.isNotEmpty()) {
                    entries = liveEntries
                    liveRatingsAvailable = true
                    val photoNames = liveEntries
                        .filter { it.photoUrl.isNullOrBlank() && it.photoName.isNotBlank() }
                        .map(RestaurantCatalogEntry::photoName)
                        .take(12)
                    if (photoNames.isNotEmpty()) {
                        val photos = try {
                            catalogRepository.resolveRestaurantPhotos(photoNames)
                        } catch (error: CancellationException) {
                            throw error
                        } catch (_: Throwable) {
                            emptyMap()
                        }
                        if (photos.isNotEmpty()) {
                            entries = entries.map { entry ->
                                val photo = photos[entry.photoName]
                                if (photo == null) entry else entry.copy(
                                    photoUrl = photo.photoUrl ?: entry.photoUrl,
                                    photoAttribution = photo.photoAttribution ?: entry.photoAttribution,
                                )
                            }
                        }
                    }
                }
            }
            .onFailure { error ->
                if (error is CancellationException) throw error
                entries = emptyList()
                message = localizedFailure(language, error, localized(language, "Не удалось загрузить каталог", "Could not load the restaurant catalog", "No se pudo cargar el catálogo", "Restaurantkatalog konnte nicht geladen werden"))
            }
        loading = false
    }

    Column(
        modifier = Modifier
            .fillMaxWidth()
            .fillMaxHeight(0.94f)
            .windowInsetsPadding(WindowInsets.navigationBars)
            .imePadding()
            .padding(horizontal = 16.dp, vertical = 7.dp),
        verticalArrangement = Arrangement.spacedBy(10.dp),
    ) {
        Row(verticalAlignment = Alignment.CenterVertically) {
            Column(modifier = Modifier.weight(1f)) {
                Text(
                    localized("Рестораны", "Restaurants", "Restaurantes", "Restaurants"),
                    color = contentTextColor(),
                    fontFamily = Manrope,
                    fontWeight = FontWeight.W800,
                    fontSize = 22.sp,
                )
                Text(
                    localizedCityName(city),
                    color = secondaryTextColor(),
                    fontFamily = Manrope,
                    fontWeight = FontWeight.W600,
                    fontSize = 13.sp,
                )
            }
            Box {
                Row(
                    modifier = Modifier
                        .clip(RoundedCornerShape(50))
                        .background(tintedSurfaceColor())
                        .clickable { sortMenuOpen = !sortMenuOpen }
                        .padding(horizontal = 13.dp, vertical = 10.dp),
                    horizontalArrangement = Arrangement.spacedBy(7.dp),
                    verticalAlignment = Alignment.CenterVertically,
                ) {
                    OdysseySortIcon()
                    Text(
                        text = sortButtonLabel,
                        color = primaryColor(),
                        fontFamily = Manrope,
                        fontWeight = FontWeight.W800,
                        fontSize = 12.sp,
                    )
                }
                DropdownMenu(
                    expanded = sortMenuOpen,
                    onDismissRequest = { sortMenuOpen = false },
                    modifier = Modifier.width(228.dp),
                    shape = RoundedCornerShape(16.dp),
                    containerColor = cardSurfaceColor(),
                    shadowElevation = 14.dp,
                ) {
                    Text(
                        text = sortButtonLabel.uppercase(Locale.ROOT),
                        color = secondaryTextColor(),
                        fontFamily = Manrope,
                        fontWeight = FontWeight.W800,
                        fontSize = 10.sp,
                        modifier = Modifier.padding(horizontal = 16.dp, vertical = 10.dp),
                    )
                    DropdownMenuItem(
                        text = {
                            Column {
                                Text(sortRatingLabel, color = contentTextColor(), fontFamily = Manrope, fontWeight = FontWeight.W800, fontSize = 13.sp)
                                Text(localized("Сначала лучшие", "Best first", "Mejor valorados", "Beste zuerst"), color = secondaryTextColor(), fontFamily = Manrope, fontWeight = FontWeight.W600, fontSize = 10.5.sp)
                            }
                        },
                        leadingIcon = { Text("★", color = Color(0xFFE29B32), fontSize = 18.sp) },
                        trailingIcon = if (sortMode == "rating") {
                            { Icon(Icons.Filled.Check, contentDescription = null, tint = primaryColor(), modifier = Modifier.size(18.dp)) }
                        } else null,
                        onClick = {
                            sortMode = "rating"
                            sortMenuOpen = false
                        },
                    )
                    DropdownMenuItem(
                        text = {
                            Column {
                                Text(sortPriceLabel, color = contentTextColor(), fontFamily = Manrope, fontWeight = FontWeight.W800, fontSize = 13.sp)
                                Text(localized("Сначала доступные", "Most affordable first", "Más económicos primero", "Günstigste zuerst"), color = secondaryTextColor(), fontFamily = Manrope, fontWeight = FontWeight.W600, fontSize = 10.5.sp)
                            }
                        },
                        leadingIcon = { Text("€", color = primaryColor(), fontFamily = Manrope, fontWeight = FontWeight.W800, fontSize = 17.sp) },
                        trailingIcon = if (sortMode == "price") {
                            { Icon(Icons.Filled.Check, contentDescription = null, tint = primaryColor(), modifier = Modifier.size(18.dp)) }
                        } else null,
                        onClick = {
                            sortMode = "price"
                            sortMenuOpen = false
                        },
                    )
                }
            }
            Box(
                modifier = Modifier.size(36.dp).clip(CircleShape).background(secondarySurfaceColor()).clickable(onClick = onClose),
                contentAlignment = Alignment.Center,
            ) {
                Icon(Icons.Filled.Close, contentDescription = localized("Закрыть", "Close", "Cerrar", "Schließen"), tint = secondaryTextColor(), modifier = Modifier.size(18.dp))
            }
        }
        OutlinedTextField(
            value = query,
            onValueChange = { query = it },
            modifier = Modifier.fillMaxWidth(),
            singleLine = true,
            shape = RoundedCornerShape(14.dp),
            placeholder = { Text(localized("Поиск по названию или кухне", "Search by name or cuisine", "Buscar por nombre o cocina", "Nach Name oder Küche suchen"), color = secondaryTextColor(), fontFamily = Manrope, fontSize = 13.sp) },
            leadingIcon = { Icon(Icons.Outlined.Restaurant, contentDescription = null, tint = primaryColor(), modifier = Modifier.size(20.dp)) },
            colors = OutlinedTextFieldDefaults.colors(focusedBorderColor = primaryColor(), unfocusedBorderColor = contentBorderColor()),
        )
        if (liveRatingsAvailable) {
            Text(
                text = localized("Рейтинг и фото из Google Maps", "Ratings and photos from Google Maps", "Valoraciones y fotos de Google Maps", "Bewertungen und Fotos aus Google Maps"),
                color = secondaryTextColor(),
                fontFamily = Manrope,
                fontWeight = FontWeight.W600,
                fontSize = 10.sp,
            )
        }
        if (message != null) {
            Text(message!!, color = Color(0xFFE0524B), fontFamily = Manrope, fontWeight = FontWeight.W700, fontSize = 12.sp)
        }
        if (loading) {
            Box(modifier = Modifier.weight(1f).fillMaxWidth(), contentAlignment = Alignment.Center) {
                CircularProgressIndicator(color = primaryColor(), strokeWidth = 3.dp, modifier = Modifier.size(30.dp))
            }
        } else if (entries.isEmpty()) {
            Box(modifier = Modifier.weight(1f).fillMaxWidth(), contentAlignment = Alignment.Center) {
                Text(
                    localized("Для этого города ресторанов пока нет", "No catalog restaurants for this city yet", "Todavía no hay restaurantes para esta ciudad", "Für diese Stadt gibt es noch keine Restaurants"),
                    color = secondaryTextColor(),
                    fontFamily = Manrope,
                    fontWeight = FontWeight.W600,
                    fontSize = 13.sp,
                    textAlign = TextAlign.Center,
                    modifier = Modifier.padding(horizontal = 22.dp),
                )
            }
        } else {
            LazyColumn(
                modifier = Modifier.weight(1f).fillMaxWidth(),
                verticalArrangement = Arrangement.spacedBy(8.dp),
            ) {
                items(sortedEntries, key = { it.id }) { entry ->
                    if (entry.photoUrl.isNullOrBlank() && entry.photoName.isNotBlank()) {
                        LaunchedEffect(entry.id, entry.photoName) {
                            val photo = try {
                                restaurantPhotoLoadGate.withPermit {
                                    catalogRepository.resolveRestaurantPhoto(entry.photoName)
                                }
                            } catch (error: CancellationException) {
                                throw error
                            } catch (_: Throwable) {
                                null
                            }
                            val photoUrl = photo?.photoUrl
                            if (!photoUrl.isNullOrBlank()) {
                                entries = entries.map { current ->
                                    if (current.id == entry.id &&
                                        current.photoName == entry.photoName &&
                                        current.photoUrl.isNullOrBlank()
                                    ) {
                                        current.copy(
                                            photoUrl = photoUrl,
                                            photoAttribution = photo?.photoAttribution ?: current.photoAttribution,
                                        )
                                    } else {
                                        current
                                    }
                                }
                            }
                        }
                    }
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .clip(RoundedCornerShape(14.dp))
                            .background(secondarySurfaceColor())
                            .border(1.dp, contentBorderColor(), RoundedCornerShape(14.dp))
                            .padding(horizontal = 12.dp, vertical = 11.dp),
                        verticalAlignment = Alignment.CenterVertically,
                    ) {
                        Box(
                            modifier = Modifier
                                .size(62.dp)
                                .clip(RoundedCornerShape(11.dp))
                                .background(if (entry.photoUrl.isNullOrBlank()) tintedSurfaceColor() else Color.Transparent)
                                .clickable(enabled = !entry.photoUrl.isNullOrBlank()) {
                                    entry.photoUrl?.let { photoUrl ->
                                        fullScreenRestaurantPhoto = photoUrl to entry.name(language)
                                    }
                                },
                            contentAlignment = Alignment.Center,
                        ) {
                            if (!entry.photoUrl.isNullOrBlank()) {
                                FastCatalogImage(
                                    url = entry.photoUrl,
                                    contentDescription = entry.name(language),
                                    contentScale = androidx.compose.ui.layout.ContentScale.Crop,
                                    modifier = Modifier.fillMaxSize(),
                                )
                            } else {
                                Icon(
                                    Icons.Outlined.Restaurant,
                                    contentDescription = null,
                                    tint = primaryColor(),
                                    modifier = Modifier.size(26.dp),
                                )
                            }
                        }
                        Spacer(modifier = Modifier.width(10.dp))
                        Column(modifier = Modifier.weight(1f)) {
                            Text(entry.name(language), color = contentTextColor(), fontFamily = Manrope, fontWeight = FontWeight.W800, fontSize = 14.sp, maxLines = 2, overflow = TextOverflow.Ellipsis)
                            val details = listOf(localizedRestaurantCuisine(entry.cuisine), entry.address).filter(String::isNotBlank).joinToString(" · ")
                            if (details.isNotBlank()) {
                                Text(details, color = secondaryTextColor(), fontFamily = Manrope, fontWeight = FontWeight.W600, fontSize = 11.5.sp, lineHeight = 15.sp, maxLines = 2, overflow = TextOverflow.Ellipsis, modifier = Modifier.padding(top = 2.dp))
                            }
                            if (entry.rating != null || entry.ratingCount != null || entry.ratingPlaceUrl.isNotBlank()) {
                                Row(
                                    modifier = Modifier.padding(top = 3.dp),
                                    horizontalArrangement = Arrangement.spacedBy(6.dp),
                                    verticalAlignment = Alignment.CenterVertically,
                                ) {
                                if (entry.rating != null) {
                                    Text(
                                        text = "★ ${entry.rating.toString().removeSuffix(".0")}",
                                        color = Color(0xFFE29B32),
                                        fontFamily = Manrope,
                                        fontWeight = FontWeight.W800,
                                        fontSize = 11.5.sp,
                                    )
                                }
                                if (entry.ratingCount != null) {
                                    Text(
                                        text = localized("${entry.ratingCount} отзывов", "${entry.ratingCount} reviews", "${entry.ratingCount} reseñas", "${entry.ratingCount} Bewertungen"),
                                        color = secondaryTextColor(),
                                        fontFamily = Manrope,
                                        fontWeight = FontWeight.W600,
                                        fontSize = 10.5.sp,
                                    )
                                }
                                if (entry.ratingPlaceUrl.isNotBlank()) {
                                    Text(
                                        text = "Google Maps",
                                        color = primaryColor(),
                                        fontFamily = Manrope,
                                        fontWeight = FontWeight.W800,
                                        fontSize = 10.sp,
                                        modifier = Modifier.clickable { uriHandler.openUri(entry.ratingPlaceUrl) },
                                    )
                                }
                            }
                            }
                            if (!entry.photoAttribution.isNullOrBlank()) {
                                Text(
                                    text = "Google photo",
                                    color = secondaryTextColor(),
                                    fontFamily = Manrope,
                                    fontWeight = FontWeight.W600,
                                    fontSize = 9.5.sp,
                                    modifier = Modifier.padding(top = 2.dp),
                                )
                            }
                        }
                        Box(
                            modifier = Modifier
                                .padding(start = 8.dp)
                                .size(40.dp)
                                .clip(RoundedCornerShape(12.dp))
                                .background(secondarySurfaceColor())
                                .border(1.dp, contentBorderColor(), RoundedCornerShape(12.dp))
                                .clickable { onSelect(entry) },
                            contentAlignment = Alignment.Center,
                        ) {
                            Text(
                                text = "+",
                                color = primaryColor(),
                                fontFamily = Manrope,
                                fontWeight = FontWeight.W800,
                                fontSize = 24.sp,
                            )
                        }
                    }
                }
            }
        }
        Text(
            text = "© OpenStreetMap contributors",
            color = secondaryTextColor(),
            fontFamily = Manrope,
            fontWeight = FontWeight.W600,
            fontSize = 10.sp,
            textAlign = TextAlign.Center,
            modifier = Modifier.fillMaxWidth(),
        )
        fullScreenRestaurantPhoto?.let { (photoUrl, title) ->
            FullScreenPhotoViewer(
                photos = listOf(photoUrl),
                initialIndex = 0,
                accommodationName = title,
                onDismiss = { fullScreenRestaurantPhoto = null },
            )
        }
    }
}

@Composable
private fun RestaurantAddSheet(
    name: String,
    city: String,
    cuisine: String,
    dateTime: String,
    price: String,
    address: String,
    status: String,
    priority: Boolean,
    photoUris: List<Uri>,
    saving: Boolean,
    message: String?,
    onNameChange: (String) -> Unit,
    onCityChange: (String) -> Unit,
    onCityPickerOpen: () -> Unit,
    onDatePickerOpen: () -> Unit,
    onCuisineChange: (String) -> Unit,
    onDateTimeChange: (String) -> Unit,
    onPriceChange: (String) -> Unit,
    onAddressChange: (String) -> Unit,
    onStatusChange: (String) -> Unit,
    onPriorityChange: () -> Unit,
    onPickPhoto: () -> Unit,
    onCatalogOpen: () -> Unit,
    onClose: () -> Unit,
    onSave: () -> Unit,
) {
    BoxWithConstraints(Modifier.fillMaxWidth()) {
        val scale = maxWidth.value / 368f
        fun d(value: Float) = (value * scale).dp
        fun s(value: Float) = (value * scale).sp
        val inputTextStyle = androidx.compose.ui.text.TextStyle(
            color = contentTextColor(),
            fontFamily = Manrope,
            fontWeight = FontWeight.W600,
            fontSize = s(15f),
            lineHeight = s(20f),
            platformStyle = OdysseyNoFontPadding,
        )
        val labelStyle = androidx.compose.ui.text.TextStyle(
            color = labelColor(),
            fontFamily = Manrope,
            fontWeight = FontWeight.W800,
            fontSize = s(13f),
            lineHeight = s(18f),
            platformStyle = OdysseyNoFontPadding,
        )
        val photoBorderColor = contentBorderColor()
        val scrollState = rememberScrollState()
        val photoScrollState = rememberScrollState()
        var fullScreenPhotoIndex by remember(photoUris) { mutableStateOf<Int?>(null) }

        Box(
            modifier = Modifier
                .fillMaxWidth()
                .height(d(704f))
                .verticalScroll(scrollState),
        ) {
            Box(Modifier.fillMaxWidth().height(d(926f))) {
                Box(
                    modifier = Modifier
                        .offset(x = d(156.5f), y = d(12f))
                        .size(d(40f), d(4f))
                        .clip(RoundedCornerShape(d(2f)))
                        .background(contentBorderColor()),
                )

                Text(
                    text = localized("Новый ресторан", "New restaurant", "Nuevo restaurante", "Neues Restaurant"),
