@Composable
private fun RestaurantFilterSegmentedRow(
    options: List<String>,
    selected: String,
    onSelect: (String) -> Unit,
    scale: Float,
    itemFontSize: Float = 14f,
    modifier: Modifier = Modifier,
) {
    fun d(value: Float) = (value * scale).dp
    Row(
        horizontalArrangement = Arrangement.spacedBy(d(5f)),
        modifier = modifier
            .height(d(53f))
            .clip(RoundedCornerShape(d(14f)))
            .background(secondarySurfaceColor())
            .padding(d(5f)),
    ) {
        options.forEach { option ->
            val active = option == selected
            Box(
                contentAlignment = Alignment.Center,
                modifier = Modifier
                    .weight(1f)
                    .height(d(43f))
                    .shadow(if (active) d(2f) else 0.dp, RoundedCornerShape(d(11f)), clip = false, ambientColor = Color(0x1A000000), spotColor = Color(0x1A000000))
                    .clip(RoundedCornerShape(d(11f)))
                    .background(if (active) cardSurfaceColor() else Color.Transparent)
                    .clickable { onSelect(option) },
            ) {
                Text(
                    text = option,
                    color = if (active) contentTextColor() else secondaryTextColor(),
                    fontFamily = Manrope,
                    fontWeight = FontWeight.W800,
                    fontSize = d(itemFontSize).value.sp,
                    lineHeight = d(itemFontSize * 1.35f).value.sp,
                    style = androidx.compose.ui.text.TextStyle(platformStyle = OdysseyNoFontPadding),
                    textAlign = TextAlign.Center,
                )
            }
        }
    }
}

@Composable
private fun RestaurantFilterTypeIcon(kind: String, iconSize: Dp, color: Color) {
    Canvas(Modifier.size(iconSize)) {
        val sx = size.width / 24f
        val sy = size.height / 24f
        val stroke = 2.dp.toPx()
        fun p(x: Float, y: Float) = Offset(x * sx, y * sy)
        when (kind) {
            "restaurant" -> {
                drawLine(color, p(3f, 2f), p(3f, 9f), strokeWidth = stroke, cap = StrokeCap.Round)
                drawLine(color, p(5f, 2f), p(5f, 22f), strokeWidth = stroke, cap = StrokeCap.Round)
                drawLine(color, p(7f, 2f), p(7f, 9f), strokeWidth = stroke, cap = StrokeCap.Round)
                val fork = Path().apply {
                    moveTo(3f * sx, 9f * sy)
                    cubicTo(3f * sx, 10.1f * sy, 3.9f * sx, 11f * sy, 5f * sx, 11f * sy)
                    cubicTo(6.1f * sx, 11f * sy, 7f * sx, 10.1f * sy, 7f * sx, 9f * sy)
                }
                drawPath(fork, color, style = Stroke(width = stroke, cap = StrokeCap.Round))
                val spoon = Path().apply {
                    moveTo(17f * sx, 2f * sy)
                    lineTo(17f * sx, 12f * sy)
                    cubicTo(19f * sx, 12f * sy, 21f * sx, 10.5f * sy, 21f * sx, 7f * sy)
                    cubicTo(21f * sx, 3.5f * sy, 19f * sx, 2f * sy, 17f * sx, 2f * sy)
                    close()
                }
                drawPath(spoon, color, style = Stroke(width = stroke, cap = StrokeCap.Round))
                drawLine(color, p(17f, 12f), p(17f, 22f), strokeWidth = stroke, cap = StrokeCap.Round)
            }
            "bar" -> {
                drawLine(color, p(8f, 22f), p(16f, 22f), strokeWidth = stroke, cap = StrokeCap.Round)
                drawLine(color, p(12f, 11f), p(12f, 22f), strokeWidth = stroke, cap = StrokeCap.Round)
                val glass = Path().apply { moveTo(3f * sx, 5f * sy); lineTo(21f * sx, 5f * sy); lineTo(12f * sx, 11f * sy); close() }
                drawPath(glass, color, style = Stroke(width = stroke, cap = StrokeCap.Round, join = androidx.compose.ui.graphics.StrokeJoin.Round))
            }
            else -> {
                val cup = Path().apply {
                    moveTo(2f * sx, 8f * sy)
                    lineTo(18f * sx, 8f * sy)
                    lineTo(18f * sx, 17f * sy)
                    cubicTo(18f * sx, 19.2f * sy, 16.2f * sx, 21f * sy, 14f * sx, 21f * sy)
                    lineTo(6f * sx, 21f * sy)
                    cubicTo(3.8f * sx, 21f * sy, 2f * sx, 19.2f * sy, 2f * sx, 17f * sy)
                    close()
                }
                drawPath(cup, color, style = Stroke(width = stroke, cap = StrokeCap.Round, join = androidx.compose.ui.graphics.StrokeJoin.Round))
                val handle = Path().apply { moveTo(18f * sx, 8f * sy); lineTo(19f * sx, 8f * sy); cubicTo(24f * sx, 8f * sy, 24f * sx, 16f * sy, 19f * sx, 16f * sy); lineTo(18f * sx, 16f * sy) }
                drawPath(handle, color, style = Stroke(width = stroke, cap = StrokeCap.Round))
            }
        }
    }
}

@Composable
private fun RestaurantFilterFeatureIcon(kind: String, iconSize: Dp, color: Color) {
    Canvas(Modifier.size(iconSize)) {
        val sx = size.width / 24f
        val sy = size.height / 24f
        fun p(x: Float, y: Float) = Offset(x * sx, y * sy)
        when (kind) {
            "priority" -> {
                val star = Path().apply {
                    moveTo(12f * sx, 2f * sy)
                    lineTo(15f * sx, 8.5f * sy)
                    lineTo(22f * sx, 9.1f * sy)
                    lineTo(16.7f * sx, 13.7f * sy)
                    lineTo(18.3f * sx, 20.5f * sy)
                    lineTo(12f * sx, 17.3f * sy)
                    lineTo(5.1f * sx, 20.5f * sy)
                    lineTo(6.7f * sx, 13.7f * sy)
                    lineTo(1.4f * sx, 9.1f * sy)
                    lineTo(8.4f * sx, 8.5f * sy)
                    close()
                }
                drawPath(star, color)
            }
            "dog" -> {
                drawCircle(color, radius = 2f * sx, center = p(5f, 9f))
                drawCircle(color, radius = 2f * sx, center = p(19f, 9f))
                drawCircle(color, radius = 2f * sx, center = p(9f, 5f))
                drawCircle(color, radius = 2f * sx, center = p(15f, 5f))
                val dog = Path().apply {
                    moveTo(12f * sx, 11f * sy)
                    cubicTo(9f * sx, 11f * sy, 7f * sx, 13.5f * sy, 7f * sx, 16f * sy)
                    cubicTo(7f * sx, 18f * sy, 8.5f * sx, 19f * sy, 10f * sx, 19f * sy)
                    cubicTo(11f * sx, 19f * sy, 11.5f * sx, 18.5f * sy, 12f * sx, 18.5f * sy)
                    cubicTo(12.5f * sx, 18.5f * sy, 13f * sx, 19f * sy, 14f * sx, 19f * sy)
                    cubicTo(15.5f * sx, 19f * sy, 17f * sx, 18f * sy, 17f * sx, 16f * sy)
                    cubicTo(17f * sx, 13.5f * sy, 15f * sx, 11f * sy, 12f * sx, 11f * sy)
                    close()
                }
                drawPath(dog, color)
            }
            "reservation" -> {
                val calendar = Path().apply {
                    moveTo(5f * sx, 4f * sy)
                    lineTo(19f * sx, 4f * sy)
                    cubicTo(20.1f * sx, 4f * sy, 21f * sx, 4.9f * sy, 21f * sx, 6f * sy)
                    lineTo(21f * sx, 20f * sy)
                    cubicTo(21f * sx, 21.1f * sy, 20.1f * sx, 22f * sy, 19f * sx, 22f * sy)
                    lineTo(5f * sx, 22f * sy)
                    cubicTo(3.9f * sx, 22f * sy, 3f * sx, 21.1f * sy, 3f * sx, 20f * sy)
                    lineTo(3f * sx, 6f * sy)
                    cubicTo(3f * sx, 4.9f * sy, 3.9f * sx, 4f * sy, 5f * sx, 4f * sy)
                }
                drawPath(calendar, color, style = Stroke(width = 2.dp.toPx(), cap = StrokeCap.Round))
                drawLine(color, p(8f, 2f), p(8f, 6f), strokeWidth = 2.dp.toPx(), cap = StrokeCap.Round)
                drawLine(color, p(16f, 2f), p(16f, 6f), strokeWidth = 2.dp.toPx(), cap = StrokeCap.Round)
                drawLine(color, p(3f, 10f), p(21f, 10f), strokeWidth = 2.dp.toPx(), cap = StrokeCap.Round)
            }
            else -> {
                val leaf = Path().apply {
                    moveTo(11f * sx, 20f * sy)
                    cubicTo(7f * sx, 20f * sy, 4f * sx, 17f * sy, 4f * sx, 13f * sy)
                    cubicTo(4f * sx, 7f * sy, 10f * sx, 3f * sy, 20f * sx, 3f * sy)
                    cubicTo(19f * sx, 11f * sy, 15f * sx, 18f * sy, 11f * sx, 20f * sy)
                    close()
                }
                drawPath(leaf, color, style = Stroke(width = 2.dp.toPx(), cap = StrokeCap.Round, join = androidx.compose.ui.graphics.StrokeJoin.Round))
                drawLine(color, p(11f, 20f), p(17f, 12f), strokeWidth = 2.dp.toPx(), cap = StrokeCap.Round)
            }
        }
    }
}

@Composable
private fun RestaurantCard(
    restaurant: com.odyssey.travelplanner.data.Restaurant,
    saving: Boolean,
    uploading: Boolean,
    canEdit: Boolean = true,
    onEdit: () -> Unit,
    onAddPhoto: () -> Unit,
    modifier: Modifier = Modifier,
    onStatusChange: (String) -> Unit,
) {
    val uriHandler = LocalUriHandler.current
    val cardBorderColor = contentBorderColor()
    // Failed signed-URL resolutions are represented by blank placeholders so
    // photo indexes stay stable in the editor. They must not make a viewer
    // appear to have a usable photo.
    val photos = restaurant.photos.filter(String::isNotBlank)
    var photoIndex by remember(restaurant.id, photos) { mutableStateOf(0) }
    var fullScreenPhotoIndex by remember(restaurant.id, photos) { mutableStateOf<Int?>(null) }
    val activePhotoIndex = photoIndex.coerceIn(0, (photos.size - 1).coerceAtLeast(0))
    val displayedNote = localizedRestaurantNote(restaurant.note)
    val booked = restaurant.status == "бронь"
    val visited = restaurant.status == "были"
    val reviewsLabel = restaurant.reviews.trim().let { raw ->
        when {
            raw.isBlank() -> ""
            raw.contains("отзыв", ignoreCase = true) || raw.contains("review", ignoreCase = true) || raw.contains("reseña", ignoreCase = true) || raw.contains("Bewertung", ignoreCase = true) -> raw
            else -> localized("$raw отзывов", "$raw reviews", "$raw reseñas", "$raw Bewertungen")
        }
    }
    val reservation = when (restaurant.status) {
        "бронь" -> localized("Бронь подтверждена", "Reservation confirmed", "Reserva confirmada", "Reservierung bestätigt")
        "были" -> localized("Посещено", "Visited", "Visitado", "Besucht")
        else -> localized("Запланировать бронь", "Plan reservation", "Planificar reserva", "Reservierung planen")
    }
    Column(
        modifier = modifier
            .fillMaxWidth()
            .clip(RoundedCornerShape(18.dp))
            .background(cardSurfaceColor())
            .shadow(6.dp, RoundedCornerShape(18.dp), clip = false, ambientColor = Color(0x0F141428), spotColor = Color(0x0F141428))
            .padding(12.dp),
    ) {
        Row(
            modifier = Modifier.fillMaxWidth().height(78.dp),
            verticalAlignment = Alignment.Top,
            horizontalArrangement = Arrangement.spacedBy(13.dp),
        ) {
            Box(
                modifier = Modifier
                    .size(78.dp)
                    .clip(RoundedCornerShape(14.dp))
                    .background(Color(0xFFE4E1EA))
                    .clickable(enabled = !uploading && (canEdit || photos.isNotEmpty())) {
                        if (photos.isEmpty() && canEdit) onAddPhoto() else if (photos.isNotEmpty()) fullScreenPhotoIndex = activePhotoIndex
                    },
            ) {
                photos.getOrNull(activePhotoIndex)?.let { AsyncImage(model = it, contentDescription = restaurant.name, contentScale = androidx.compose.ui.layout.ContentScale.Crop, modifier = Modifier.fillMaxSize()) }
                if (photos.isEmpty()) Icon(Icons.Outlined.Restaurant, contentDescription = null, tint = Color(0xFFA7A1B2), modifier = Modifier.align(Alignment.Center).size(27.dp))
                // Restaurant thumbnails stay clean; photo controls are available in the fullscreen viewer.
                if (photos.size > 1 && fullScreenPhotoIndex != null) {
                    Box(
                        contentAlignment = Alignment.Center,
                        modifier = Modifier
                            .align(Alignment.CenterStart)
                            .padding(start = 4.dp)
                            .size(24.dp)
                            .clip(CircleShape)
                            .background(Color(0x990F0F19))
                            .clickable {
                                photoIndex = (activePhotoIndex - 1 + photos.size) % photos.size
                            },
                    ) {
                        Icon(
                            Icons.Outlined.ArrowBack,
                            contentDescription = localized("Предыдущее фото", "Previous photo", "Foto anterior", "Vorheriges Foto"),
                            tint = Color.White,
                            modifier = Modifier.size(14.dp),
                        )
                    }
                    Box(
                        contentAlignment = Alignment.Center,
                        modifier = Modifier
                            .align(Alignment.CenterEnd)
                            .padding(end = 4.dp)
                            .size(24.dp)
                            .clip(CircleShape)
                            .background(Color(0x990F0F19))
                            .clickable {
                                photoIndex = (activePhotoIndex + 1) % photos.size
                            },
                    ) {
                        Icon(
                            Icons.Outlined.ArrowBack,
                            contentDescription = localized("Следующее фото", "Next photo", "Foto siguiente", "Nächstes Foto"),
                            tint = Color.White,
                            modifier = Modifier.size(14.dp).graphicsLayer(rotationZ = 180f),
                        )
                    }
                    Box(
                        contentAlignment = Alignment.Center,
                        modifier = Modifier
                            .align(Alignment.BottomCenter)
                            .padding(bottom = 4.dp)
                            .clip(RoundedCornerShape(10.dp))
                            .background(Color(0x990F0F19))
                            .padding(horizontal = 5.dp, vertical = 2.dp),
                    ) {
                        Text(
                            text = "${activePhotoIndex + 1}/${photos.size}",
                            color = Color.White,
                            fontFamily = Manrope,
                            fontWeight = FontWeight.W800,
                            fontSize = 9.sp,
                            lineHeight = 11.sp,
                            style = androidx.compose.ui.text.TextStyle(platformStyle = OdysseyNoFontPadding),
                        )
                    }
                }
            }
            Column(modifier = Modifier.weight(1f).height(78.dp)) {
                Row(modifier = Modifier.fillMaxWidth(), verticalAlignment = Alignment.Top) {
                    Text(
                        restaurant.name,
                        color = contentTextColor(),
                        fontFamily = Manrope,
                        fontWeight = FontWeight.W800,
                        fontSize = 15.sp,
                        lineHeight = 17.25.sp,
                        style = androidx.compose.ui.text.TextStyle(platformStyle = OdysseyNoFontPadding),
                        maxLines = 1,
                        overflow = TextOverflow.Ellipsis,
                        modifier = Modifier.weight(1f),
                    )
                    restaurantLinkUri(restaurant.link)?.let { link ->
                        OdysseyExternalLinkIcon(
                            17.dp,
                            primaryColor(),
                            modifier = Modifier
                                .padding(top = 2.dp)
                                .clickable { runCatching { uriHandler.openUri(link) } },
                        )
                    }
                }
                Text(
                    restaurant.city.takeIf(String::isNotBlank)?.let { localizedCityName(it) }
                        ?: localized("Город не указан", "City not specified", "Ciudad no indicada", "Stadt nicht angegeben"),
                    color = secondaryTextColor(),
                    fontFamily = Manrope,
                    fontWeight = FontWeight.W600,
                    fontSize = 12.sp,
                    lineHeight = 17.sp,
                    style = androidx.compose.ui.text.TextStyle(platformStyle = OdysseyNoFontPadding),
                    maxLines = 1,
                    overflow = TextOverflow.Ellipsis,
                    modifier = Modifier.padding(top = 3.dp),
                )
                Row(horizontalArrangement = Arrangement.spacedBy(6.dp), modifier = Modifier.padding(top = 9.dp).height(25.dp)) {
                    restaurant.rating?.let {
                        Row(
                            modifier = Modifier.height(25.dp).clip(RoundedCornerShape(8.dp)).background(warningSurfaceColor()).padding(horizontal = 8.dp, vertical = 4.dp),
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.spacedBy(4.dp),
                        ) {
                            Text("★", color = Color(0xFFF5A623), fontFamily = Manrope, fontWeight = FontWeight.W400, fontSize = 11.sp, lineHeight = 15.sp, style = androidx.compose.ui.text.TextStyle(platformStyle = OdysseyNoFontPadding))
                            Text(it.toString(), color = contentTextColor(), fontFamily = Manrope, fontWeight = FontWeight.W800, fontSize = 12.sp, lineHeight = 17.sp, style = androidx.compose.ui.text.TextStyle(platformStyle = OdysseyNoFontPadding))
                        }
                    }
                    if (restaurant.price.isNotBlank()) {
                        Box(modifier = Modifier.height(25.dp).clip(RoundedCornerShape(8.dp)).background(tintedSurfaceColor()).padding(horizontal = 8.dp, vertical = 4.dp), contentAlignment = Alignment.Center) {
                            Text(restaurant.price, color = primaryColor(), fontFamily = Manrope, fontWeight = FontWeight.W800, fontSize = 12.sp, lineHeight = 17.sp, style = androidx.compose.ui.text.TextStyle(platformStyle = OdysseyNoFontPadding))
                        }
                    }
                    if (displayedNote.isNotBlank() && !restaurant.note.contains("http", ignoreCase = true)) {
                        Box(modifier = Modifier.height(25.dp).clip(RoundedCornerShape(8.dp)).background(secondarySurfaceColor()).padding(horizontal = 8.dp, vertical = 4.dp), contentAlignment = Alignment.Center) {
                            Text(displayedNote, color = secondaryTextColor(), fontFamily = Manrope, fontWeight = FontWeight.W700, fontSize = 12.sp, lineHeight = 17.sp, maxLines = 1, overflow = TextOverflow.Ellipsis, style = androidx.compose.ui.text.TextStyle(platformStyle = OdysseyNoFontPadding))
                        }
                    }
                }
            }
        }
        Row(
            verticalAlignment = Alignment.CenterVertically,
            modifier = Modifier
                .fillMaxWidth()
                .padding(top = 12.dp)
                .height(29.dp)
                .drawBehind { drawLine(cardBorderColor, Offset(0f, 0f), Offset(size.width, 0f), strokeWidth = 1.dp.toPx()) }
                .padding(top = 11.dp)
                .clickable(enabled = canEdit && !saving) { onStatusChange(when (restaurant.status) { "хочу" -> "бронь"; "бронь" -> "были"; else -> "хочу" }) },
        ) {
            if (booked || visited) {
                Row(modifier = Modifier.weight(1f), verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(6.dp)) {
                    OdysseyCalendarIcon(14.dp, if (booked) Color(0xFF22B07D) else secondaryTextColor())
                    Text(if (saving) localized("Сохраняем…", "Saving…", "Guardando…", "Wird gespeichert…") else reservation, color = if (booked) Color(0xFF22B07D) else secondaryTextColor(), fontFamily = Manrope, fontWeight = FontWeight.W800, fontSize = 12.5.sp, lineHeight = 17.sp, style = androidx.compose.ui.text.TextStyle(platformStyle = OdysseyNoFontPadding), maxLines = 1, overflow = TextOverflow.Ellipsis)
                }
            } else {
                Text(
                    if (saving) localized("Сохраняем…", "Saving…", "Guardando…", "Wird gespeichert…") else reviewsLabel.ifBlank { reservation },
                    color = secondaryTextColor(),
                    fontFamily = Manrope,
                    fontWeight = FontWeight.W700,
                    fontSize = 12.5.sp,
                    lineHeight = 17.sp,
                    style = androidx.compose.ui.text.TextStyle(platformStyle = OdysseyNoFontPadding),
                    maxLines = 1,
                    overflow = TextOverflow.Ellipsis,
                    modifier = Modifier.weight(1f),
                )
                if (restaurant.reviews.isNotBlank()) {
                    Text(localized("Забронировать", "Book", "Reservar", "Buchen"), color = primaryColor(), fontFamily = Manrope, fontWeight = FontWeight.W800, fontSize = 12.5.sp, lineHeight = 17.sp, style = androidx.compose.ui.text.TextStyle(platformStyle = OdysseyNoFontPadding), maxLines = 1)
                }
            }
        }
        if (canEdit) {
            OutlinedButton(
                onClick = onEdit,
                colors = ButtonDefaults.outlinedButtonColors(contentColor = labelColor()),
                border = androidx.compose.foundation.BorderStroke(1.dp, contentBorderColor()),
                shape = RoundedCornerShape(12.dp),
                modifier = Modifier.fillMaxWidth().padding(top = 11.dp).height(42.dp),
                contentPadding = androidx.compose.foundation.layout.PaddingValues(11.dp),
            ) {
                Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(7.dp)) {
                    OdysseyEditIcon(15.dp, primaryColor())
                    Text(localized("Редактировать", "Edit", "Editar", "Bearbeiten"), color = labelColor(), fontFamily = Manrope, fontWeight = FontWeight.W800, fontSize = 13.5.sp, lineHeight = 17.sp, style = androidx.compose.ui.text.TextStyle(platformStyle = OdysseyNoFontPadding), maxLines = 1)
                }
            }
        }
        fullScreenPhotoIndex?.let { initialIndex ->
            if (photos.isNotEmpty()) {
                FullScreenPhotoViewer(
                    photos = photos,
                    initialIndex = initialIndex,
                    accommodationName = restaurant.name,
                    onDismiss = { selectedIndex ->
                        photoIndex = selectedIndex
                        fullScreenPhotoIndex = null
                    },
                )
            }
        }
    }
}

@Composable
private fun RestaurantMapCard(
    restaurants: List<com.odyssey.travelplanner.data.Restaurant>,
    cityCoordinates: Map<String, CityLocation> = emptyMap(),
    modifier: Modifier = Modifier,
) {
    val context = LocalContext.current
    val language = LocalLanguage.current
    val attributionDescription = localized("Информация об источниках карты", "Map attribution information", "Información de atribución del mapa", "Informationen zur Kartenquelle")
    val restaurantPoints = remember(restaurants) {
        restaurants
            .mapNotNull { mapCoordinate(it.city, cityCoordinates) }
            .distinctBy { "${it.longitude()},${it.latitude()}" }
    }
    var mapStyleReady by remember { mutableStateOf(false) }
    val mapView = remember(context, attributionDescription) {
        MapView(
            context,
            MapInitOptions(
                context = context,
                textureView = true,
                styleUri = null,
            ),
        ).also {
            it.scalebar.enabled = false
            keepMapGesturesInsideMap(it)
            it.post { labelMapboxAccessibility(it, attributionDescription) }
        }
    }
    val annotationManager = remember(mapView) { mapView.annotations.createCircleAnnotationManager() }
    val numberAnnotationManager = remember(mapView) { mapView.annotations.createPointAnnotationManager() }

    LaunchedEffect(mapView) {
        mapStyleReady = false
        mapView.mapboxMap.loadStyle(Style.MAPBOX_STREETS) { style ->
            style.localizeLabels(mapLocale(language))
            mapStyleReady = true
        }
    }

    DisposableEffect(mapView, annotationManager, numberAnnotationManager) {
        onDispose {
            annotationManager.deleteAll()
            numberAnnotationManager.deleteAll()
        }
    }

    LaunchedEffect(mapStyleReady, language) {
        if (mapStyleReady) mapView.mapboxMap.style?.localizeLabels(mapLocale(language))
    }

    LaunchedEffect(mapStyleReady, restaurantPoints) {
        if (!mapStyleReady) return@LaunchedEffect
        annotationManager.deleteAll()
        numberAnnotationManager.deleteAll()
        restaurantPoints.forEachIndexed { index, point ->
            annotationManager.create(
                CircleAnnotationOptions()
                    .withPoint(point)
                    .withCircleRadius(9.0)
                    .withCircleColor("#6C5CE7")
                    .withCircleStrokeColor("#FFFFFF")
                    .withCircleStrokeWidth(3.0),
            )
            numberAnnotationManager.create(
                PointAnnotationOptions()
                    .withPoint(point)
                    .withTextField((index + 1).toString())
                    .withTextColor("#FFFFFF")
                    .withTextSize(12.0)
                    .withTextAnchor(TextAnchor.CENTER),
            )
        }
        val camera = when {
            restaurantPoints.size > 1 -> mapView.mapboxMap.cameraForCoordinates(
                restaurantPoints,
                EdgeInsets(34.0, 34.0, 34.0, 34.0),
                null,
                null,
            )
            restaurantPoints.size == 1 -> CameraOptions.Builder()
                .center(restaurantPoints.first())
                .zoom(9.0)
                .build()
            else -> CameraOptions.Builder()
                .center(Point.fromLngLat(12.4964, 41.9028))
                .zoom(5.0)
                .build()
        }
        mapView.mapboxMap.setCamera(camera)
    }

    Column(
        modifier = modifier
            .fillMaxWidth()
            .height(150.dp)
            .shadow(10.dp, RoundedCornerShape(22.dp), clip = false, ambientColor = Color(0x19141428), spotColor = Color(0x19141428))
            .clip(RoundedCornerShape(22.dp))
            .background(cardSurfaceColor()),
    ) {
        Box(modifier = Modifier.fillMaxSize()) {
            AndroidView(
                factory = { mapView },
                modifier = Modifier.fillMaxSize(),
            )
        }
    }
}

@Composable
private fun EditRestaurantPanel(restaurant: com.odyssey.travelplanner.data.Restaurant, tripId: String, onClose: () -> Unit, onDeleted: () -> Unit, onSaved: () -> Unit) {
    val language = LocalLanguage.current
    var name by remember(restaurant.id) { mutableStateOf(restaurant.name) }
    var city by remember(restaurant.id) { mutableStateOf(restaurant.city) }
    var note by remember(restaurant.id) { mutableStateOf(restaurant.note) }
    var price by remember(restaurant.id) { mutableStateOf(restaurant.price) }
    var link by remember(restaurant.id) { mutableStateOf(restaurant.link) }
    var saving by remember { mutableStateOf(false) }
    var deleteDialogOpen by remember { mutableStateOf(false) }
    var message by remember { mutableStateOf<String?>(null) }
    val scope = rememberCoroutineScope()
    Column(modifier = Modifier.fillMaxWidth().clip(RoundedCornerShape(18.dp)).background(cardSurfaceColor()).padding(16.dp), verticalArrangement = Arrangement.spacedBy(10.dp)) {
        Text(localized("Редактировать ресторан", "Edit restaurant", "Editar restaurante", "Restaurant bearbeiten"), color = contentTextColor(), fontFamily = Manrope, fontWeight = FontWeight.W800, fontSize = 17.sp)
        AuthField(localized("Название", "Name", "Nombre", "Name"), localized("Название", "Name", "Nombre", "Name"), name) { name = it }
        AuthField(localized("Город", "City", "Ciudad", "Stadt"), localized("Город", "City", "Ciudad", "Stadt"), city) { city = it }
        AuthField(localized("Заметка", "Note", "Nota", "Notiz"), localized("Кухня или комментарий", "Cuisine or note", "Cocina o comentario", "Küche oder Notiz"), note) { note = it }
        AuthField(localized("Цена", "Price", "Precio", "Preis"), "€€ / €€€", price) { price = it }
        AuthField(localized("Ссылка", "Link", "Enlace", "Link"), "https://…", link) { link = it }
        if (message != null) Text(message!!, color = Color(0xFFE0524B), fontFamily = Manrope, fontWeight = FontWeight.W700, fontSize = 12.sp)
        Row(horizontalArrangement = Arrangement.spacedBy(10.dp), verticalAlignment = Alignment.CenterVertically) {
            Box(modifier = Modifier.size(46.dp).clip(RoundedCornerShape(11.dp)).background(dangerSurfaceColor()).clickable(enabled = !saving) {
                deleteDialogOpen = true
            }, contentAlignment = Alignment.Center) {
                Icon(Icons.Outlined.Delete, contentDescription = localized("Удалить", "Delete", "Eliminar", "Löschen"), tint = Color(0xFFFF6B65), modifier = Modifier.size(19.dp))
            }
            Button(onClick = onClose, colors = ButtonDefaults.buttonColors(containerColor = secondarySurfaceColor(), contentColor = contentTextColor()), shape = RoundedCornerShape(11.dp)) { Text(localized("Отмена", "Cancel", "Cancelar", "Abbrechen"), fontFamily = Manrope, fontWeight = FontWeight.W800) }
            Button(onClick = {
                scope.launch {
                    saving = true
                    runCatching {
                        SupabaseTripRepository(SupabaseProvider.clientForCurrentAuthFlow()).updateRestaurantDetailsRich(
                            tripId,
                            restaurant.id,
                            com.odyssey.travelplanner.data.RestaurantInput(
                                name = name,
                                city = city,
                                status = restaurant.status,
                                note = note,
                                price = price,
                                link = link,
                                priority = restaurant.priority,
                            ),
                        )
                    }
                        .onSuccess { onSaved() }
                        .onFailure { message = localizedFailure(language, it, localized(language, "Не удалось сохранить ресторан", "Could not save restaurant", "No se pudo guardar el restaurante", "Restaurant konnte nicht gespeichert werden")) }
                    saving = false
                }
            }, enabled = !saving, colors = ButtonDefaults.buttonColors(containerColor = primaryColor(), contentColor = primaryContentColor()), shape = RoundedCornerShape(11.dp)) { Text(if (saving) localized("Сохраняем…", "Saving…", "Guardando…", "Wird gespeichert…") else localized("Сохранить", "Save", "Guardar", "Speichern"), fontFamily = Manrope, fontWeight = FontWeight.W800) }
        }
    }
    if (deleteDialogOpen) {
        AlertDialog(
            onDismissRequest = { if (!saving) deleteDialogOpen = false },
            title = {
                Text(
                    localized("Удалить ресторан?", "Delete restaurant?", "¿Eliminar restaurante?", "Restaurant löschen?"),
                    fontFamily = Manrope,
                    fontWeight = FontWeight.W800,
                )
            },
            text = {
                Text(
                    localized(
                        "Ресторан будет удалён из поездки.",
                        "The restaurant will be removed from the trip.",
                        "El restaurante se eliminará del viaje.",
                        "Das Restaurant wird aus der Reise entfernt.",
                    ),
                    fontFamily = Manrope,
                )
            },
            dismissButton = {
                TextButton(onClick = { deleteDialogOpen = false }, enabled = !saving) {
                    Text(localized("Отмена", "Cancel", "Cancelar", "Abbrechen"), fontFamily = Manrope, fontWeight = FontWeight.W800)
                }
            },
            confirmButton = {
                TextButton(
                    onClick = {
                        deleteDialogOpen = false
                        scope.launch {
                            saving = true
                            runCatching { SupabaseTripRepository(SupabaseProvider.clientForCurrentAuthFlow()).deleteTripItem(tripId, "restaurants", restaurant.id) }
                                .onSuccess { onDeleted() }
                                .onFailure { message = localizedFailure(language, it, localized(language, "Не удалось удалить ресторан", "Could not delete restaurant", "No se pudo eliminar el restaurante", "Restaurant konnte nicht gelöscht werden")) }
                            saving = false
                        }
                    },
                    enabled = !saving,
                    colors = ButtonDefaults.textButtonColors(contentColor = Color(0xFFD9534F)),
                ) {
                    Text(localized("Удалить", "Delete", "Eliminar", "Löschen"), fontFamily = Manrope, fontWeight = FontWeight.W800)
                }
            },
        )
    }
}

@Composable
private fun PhotosContent(tripId: String, overview: TripOverview, canEdit: Boolean = true, onPhotoAdded: () -> Unit) {
    val language = LocalLanguage.current
    val context = LocalContext.current
    val scope = rememberCoroutineScope()
    val uploadCities = remember(overview.id, overview.cities, overview.overviewMapPoints, overview.overviewWeatherCities, overview.routeLegs) {
        (
            overview.cities + overview.overviewMapPoints + overview.overviewWeatherCities + overview.routeLegs.flatMap { listOf(it.from, it.to) }
        ).flatMap(::splitStoredCityList).map(String::trim).filter(String::isNotBlank).distinctBy(::cityFilterKey)
    }
    var selectedUploadCity by remember(overview.id) { mutableStateOf("") }
    var uploadCityMenuOpen by remember { mutableStateOf(false) }
    var uploading by remember { mutableStateOf(false) }
    var message by remember { mutableStateOf<String?>(null) }
    LaunchedEffect(uploadCities) {
        if (selectedUploadCity.isBlank() || uploadCities.none { cityFilterKey(it) == cityFilterKey(selectedUploadCity) }) {
            selectedUploadCity = uploadCities.firstOrNull().orEmpty()
        }
    }
    val picker = rememberLauncherForActivityResult(ActivityResultContracts.GetMultipleContents()) { uris ->
        if (uris.isEmpty()) return@rememberLauncherForActivityResult
        scope.launch {
            uploading = true
            message = null
            runCatching {
                val repository = SupabaseTripRepository(SupabaseProvider.clientForCurrentAuthFlow())
                uris.forEach { uri ->
                    val bytes = context.contentResolver.openInputStream(uri)?.use { it.readBytes() }
                        ?: error(localized(language, "Не удалось прочитать изображение", "Could not read the image", "No se pudo leer la imagen", "Das Bild konnte nicht gelesen werden"))
                    repository.addCoverPhoto(tripId, bytes, selectedUploadCity)
                }
            }.onSuccess { onPhotoAdded() }.onFailure {
                message = localizedFailure(language, it, localized(language, "Не удалось загрузить фото", "Could not upload photo", "No se pudo subir la foto", "Foto konnte nicht hochgeladen werden"))
            }
            uploading = false
        }
    }
    // This gallery is user-owned: only photos explicitly uploaded from this
    // screen belong here. Catalog and section photos remain in their sections.
    val photos = overview.coverPhotos
        .map { it.imageUrl to it.city }
        // Cover photos used by the overview/weather are restored from the
        // trip's legacy catalog. The Photos tab is intentionally reserved for
        // images uploaded through this tab, which are stored under /covers/.
        .filter { (imageUrl, _) ->
            imageUrl.isNotBlank() && tripPhotoPath(imageUrl)?.contains("/covers/") == true
        }
        .distinctBy { it.first }
    val groupedPhotos = photos.groupBy { (_, city) -> city.ifBlank { localized(language, "Поездка", "Trip", "Viaje", "Reise") } }.toList()

    fun groupMeta(city: String, count: Int): String {
        val date = photoGroupDateRange(city, overview, groupedPhotos.indexOfFirst { it.first == city } + 1)
            ?.let { formatPhotoDateRange(it, language) }
        return listOfNotNull(date, "$count ${localized(language, "фото", "photos", "fotos", "Fotos")}").joinToString(" · ")
    }

    LazyColumn(
        contentPadding = androidx.compose.foundation.layout.PaddingValues(start = 18.dp, end = 18.dp, bottom = 30.dp),
        verticalArrangement = Arrangement.spacedBy(18.dp),
        modifier = Modifier
            .fillMaxSize()
            .windowInsetsPadding(WindowInsets.navigationBars),
    ) {
        item {
            Row(
                verticalAlignment = Alignment.Top,
                horizontalArrangement = Arrangement.SpaceBetween,
                modifier = Modifier.fillMaxWidth().padding(top = 12.dp),
            ) {
                Text(localized("Фото", "Photos", "Fotos", "Fotos"), color = contentTextColor(), fontFamily = Manrope, fontWeight = FontWeight.W800, fontSize = 17.sp)
                if (canEdit) {
                    Box(
                        contentAlignment = Alignment.Center,
                        modifier = Modifier
                            .clip(RoundedCornerShape(11.dp))
                            .background(Brush.linearGradient(listOf(primaryColor(), Color(0xFF7D6CF0))))
                            .shadow(5.dp, RoundedCornerShape(11.dp), clip = false, ambientColor = Color(0x426C5CE7), spotColor = Color(0x426C5CE7))
                            .clickable(enabled = !uploading) { picker.launch("image/*") }
                            .padding(horizontal = 12.dp, vertical = 7.dp),
                    ) {
                        Text(
                            if (uploading) localized("Загружаем…", "Uploading…", "Subiendo…", "Wird hochgeladen…") else localized("↑  Загрузить", "↑  Upload", "↑  Subir", "↑  Hochladen"),
                            color = primaryContentColor(),
                            fontFamily = Manrope,
                            fontWeight = FontWeight.W800,
                            fontSize = 12.5.sp,
                        )
                    }
                }
            }
        }
        if (canEdit && uploadCities.isNotEmpty()) {
            item {
                Box {
                    Row(
                        verticalAlignment = Alignment.CenterVertically,
                        modifier = Modifier
                            .fillMaxWidth()
                            .clip(RoundedCornerShape(13.dp))
                            .background(secondarySurfaceColor())
                            .border(1.dp, contentBorderColor(), RoundedCornerShape(13.dp))
                            .clickable { uploadCityMenuOpen = true }
                            .padding(horizontal = 13.dp, vertical = 11.dp),
                    ) {
                        Icon(Icons.Outlined.LocationOn, contentDescription = null, tint = primaryColor(), modifier = Modifier.size(18.dp))
                        Column(modifier = Modifier.weight(1f).padding(start = 9.dp)) {
                            Text(localized("Город фото", "Photo city", "Ciudad de la foto", "Fotostadt"), color = secondaryTextColor(), fontFamily = Manrope, fontWeight = FontWeight.W700, fontSize = 11.sp)
                            Text(localizedCityName(selectedUploadCity), color = contentTextColor(), fontFamily = Manrope, fontWeight = FontWeight.W800, fontSize = 14.sp, maxLines = 1, overflow = TextOverflow.Ellipsis)
                        }
                        Icon(Icons.Outlined.KeyboardArrowDown, contentDescription = localized("Выбрать город", "Choose city", "Elegir ciudad", "Stadt auswählen"), tint = secondaryTextColor(), modifier = Modifier.size(19.dp))
                    }
                    DropdownMenu(expanded = uploadCityMenuOpen, onDismissRequest = { uploadCityMenuOpen = false }, containerColor = cardSurfaceColor()) {
                        uploadCities.forEach { city ->
                            DropdownMenuItem(
                                text = { Text(localizedCityName(city), fontFamily = Manrope) },
                                onClick = { selectedUploadCity = city; uploadCityMenuOpen = false },
                            )
                        }
                    }
                }
            }
        }
        if (message != null) item { Text(message!!, color = Color(0xFFE0524B), fontFamily = Manrope, fontWeight = FontWeight.W700, fontSize = 12.sp) }
        if (groupedPhotos.isEmpty()) {
            item { Text(localized("Фотографии пока не добавлены", "No photos added yet", "Aún no se han añadido fotos", "Noch keine Fotos hinzugefügt"), color = secondaryTextColor(), fontFamily = Manrope, fontWeight = FontWeight.W700, fontSize = 14.sp) }
        } else {
            itemsIndexed(groupedPhotos, key = { _, group -> group.first }) { index, (city, cityPhotos) ->
                Column(verticalArrangement = Arrangement.spacedBy(8.dp), modifier = Modifier.fillMaxWidth()) {
                    Row(verticalAlignment = Alignment.CenterVertically, modifier = Modifier.fillMaxWidth()) {
                        Box(contentAlignment = Alignment.Center, modifier = Modifier.size(26.dp).background(Brush.linearGradient(listOf(Color(0xFFF5A623), Color(0xFFF77F4B))), CircleShape)) {
                            Text(photoGroupDay(city, overview, index + 1).toString(), color = Color.White, fontFamily = Manrope, fontWeight = FontWeight.W800, fontSize = 12.sp)
                        }
                    Text(localizedCityName(city), color = contentTextColor(), fontFamily = Manrope, fontWeight = FontWeight.W800, fontSize = 18.sp, modifier = Modifier.padding(start = 10.dp))
                        Spacer(Modifier.weight(1f))
                        Text(groupMeta(city, cityPhotos.size), color = secondaryTextColor(), fontFamily = Manrope, fontWeight = FontWeight.W600, fontSize = 12.5.sp)
                    }

                    if (cityPhotos.size >= 3) {
                        Row(horizontalArrangement = Arrangement.spacedBy(8.dp), modifier = Modifier.fillMaxWidth()) {
                            PhotoTile(cityPhotos[0].first, Modifier.weight(1.7f).height(216.dp))
                            Column(verticalArrangement = Arrangement.spacedBy(8.dp), modifier = Modifier.weight(1f)) {
                                PhotoTile(cityPhotos[1].first, Modifier.fillMaxWidth().height(104.dp))
                                PhotoTile(cityPhotos[2].first, Modifier.fillMaxWidth().height(104.dp))
                            }
                        }
                        cityPhotos.drop(3).chunked(3).forEach { row ->
                            PhotoTileRow(row)
                        }
                    } else {
                        cityPhotos.chunked(3).forEach { row ->
                            PhotoTileRow(row)
                        }
                    }
                }
            }
        }
    }
}

@Composable
private fun PhotoTileRow(photos: List<Pair<String, String>>) {
    Row(horizontalArrangement = Arrangement.spacedBy(8.dp), modifier = Modifier.fillMaxWidth()) {
        photos.forEach { (imageUrl, _) ->
            PhotoTile(imageUrl, Modifier.weight(1f).height(112.dp))
        }
        repeat(3 - photos.size) { Spacer(Modifier.weight(1f)) }
    }
}

@Composable
private fun PhotoTile(imageUrl: String, modifier: Modifier = Modifier) {
    Box(modifier = modifier.clip(RoundedCornerShape(16.dp)).background(Color(0xFFD9D6E1))) {
        AsyncImage(model = imageUrl, contentDescription = null, contentScale = androidx.compose.ui.layout.ContentScale.Crop, modifier = Modifier.fillMaxSize())
    }
}

@Composable
private fun MembersContent(tripId: String, overview: TripOverview, canEdit: Boolean = true, onRoleUpdated: () -> Unit) {
    val language = LocalLanguage.current
    val dashedBorderColor = if (LocalDarkTheme.current) OdysseyDarkBorder else Color(0xFFD3D3DB)
    var savingMemberId by remember { mutableStateOf<String?>(null) }
    var deleteMember by remember { mutableStateOf<com.odyssey.travelplanner.data.TripMember?>(null) }
    var deleteMemberError by remember { mutableStateOf<String?>(null) }
    var adding by remember { mutableStateOf(false) }
    var editing by remember { mutableStateOf(false) }
    var name by remember { mutableStateOf("") }
    var email by remember { mutableStateOf("") }
    var role by remember { mutableStateOf("Редактор") }
    var saving by remember { mutableStateOf(false) }
    var message by remember { mutableStateOf<String?>(null) }
    var actionMessage by remember { mutableStateOf<String?>(null) }
    val scope = rememberCoroutineScope()
    LazyColumn(
        contentPadding = androidx.compose.foundation.layout.PaddingValues(start = 18.dp, end = 18.dp, bottom = 30.dp),
        verticalArrangement = Arrangement.spacedBy(10.dp),
        modifier = Modifier
            .fillMaxSize()
            .windowInsetsPadding(WindowInsets.navigationBars),
    ) {
        item {
            Row(verticalAlignment = Alignment.CenterVertically, modifier = Modifier.fillMaxWidth().padding(top = 12.dp)) {
                Text(localized("Участники", "Members", "Participantes", "Teilnehmer"), color = contentTextColor(), fontFamily = Manrope, fontWeight = FontWeight.W800, fontSize = 17.sp)
                Spacer(Modifier.weight(1f))
                if (canEdit) {
                    Row(
                        verticalAlignment = Alignment.CenterVertically,
                        modifier = Modifier.clip(RoundedCornerShape(11.dp)).background(tintedSurfaceColor()).clickable { editing = !editing }.padding(horizontal = 13.dp, vertical = 8.dp),
                    ) {
                        Icon(Icons.Outlined.Edit, contentDescription = localized("Изменить участников", "Edit members", "Editar participantes", "Teilnehmer bearbeiten"), tint = primaryColor(), modifier = Modifier.size(16.dp))
                        Text(if (editing) localized("Готово", "Done", "Listo", "Fertig") else localized("Изменить", "Edit", "Editar", "Bearbeiten"), color = primaryColor(), fontFamily = Manrope, fontWeight = FontWeight.W800, fontSize = 13.sp, modifier = Modifier.padding(start = 5.dp))
                    }
                }
            }
        }
        if (actionMessage != null) {
            item {
                Text(actionMessage!!, color = Color(0xFFE0524B), fontFamily = Manrope, fontWeight = FontWeight.W700, fontSize = 12.sp)
            }
        }
        if (overview.members.isEmpty()) {
            item { Text(localized("Участники пока не добавлены", "No members added yet", "Aún no se han añadido participantes", "Noch keine Mitglieder hinzugefügt"), color = secondaryTextColor(), fontFamily = Manrope, fontWeight = FontWeight.W700, fontSize = 14.sp) }
        } else {
            items(overview.members, key = { it.id }) { member ->
                MemberCard(member, savingMemberId == member.id, canEdit && editing, onDelete = {
                    if (canEdit) {
                        deleteMember = member
                        deleteMemberError = null
                    }
                }) { role ->
                    if (canEdit) {
                        scope.launch {
                            savingMemberId = member.id
                            runCatching { SupabaseTripRepository(SupabaseProvider.clientForCurrentAuthFlow()).updateMemberRole(tripId, member.id, role) }
                                .onSuccess {
                                    actionMessage = null
                                    onRoleUpdated()
                                }
                                .onFailure {
                                    actionMessage = localizedFailure(language, it, localized(language, "Не удалось изменить роль. Проверьте интернет и повторите попытку.", "Could not change the role. Check your connection and try again.", "No se pudo cambiar el rol. Comprueba la conexión e inténtalo de nuevo.", "Die Rolle konnte nicht geändert werden. Prüfen Sie die Verbindung und versuchen Sie es erneut."))
                                }
                            savingMemberId = null
                        }
                    }
                }
            }
        }
        if (canEdit) item {
            if (adding) {
                Column(modifier = Modifier.fillMaxWidth().shadow(6.dp, RoundedCornerShape(18.dp), clip = false, ambientColor = Color(0x0F141428), spotColor = Color(0x0F141428)).clip(RoundedCornerShape(18.dp)).background(cardSurfaceColor()).padding(horizontal = 15.dp, vertical = 13.dp), verticalArrangement = Arrangement.spacedBy(10.dp)) {
                    InviteMemberField(localized("Имя участника", "Member name", "Nombre", "Name"), name) { name = it }
                    InviteMemberField("e-mail ${localized("нового участника", "of new member", "del nuevo participante", "des neuen Mitglieds")}", email) { email = it }
                    Row(
                        horizontalArrangement = Arrangement.spacedBy(4.dp),
                        modifier = Modifier.fillMaxWidth().clip(RoundedCornerShape(12.dp)).background(secondarySurfaceColor()).padding(3.dp),
                    ) {
                        listOf(
                            localized("Редактор", "Editor", "Editor", "Editor") to "Редактор",
                            localized("Просмотр", "Viewer", "Lector", "Leser") to "Читатель",
                        ).forEach { (label, value) ->
                            val selected = value == role
                            Box(contentAlignment = Alignment.Center, modifier = Modifier.weight(1f).height(36.dp).clip(RoundedCornerShape(10.dp)).background(if (selected) cardSurfaceColor() else Color.Transparent).border(if (selected) 1.dp else 0.dp, if (selected) contentBorderColor() else Color.Transparent, RoundedCornerShape(10.dp)).clickable { role = value }) {
                                Text(label, color = if (selected) contentTextColor() else secondaryTextColor(), fontFamily = Manrope, fontWeight = FontWeight.W800, fontSize = 12.sp)
                            }
                        }
                    }
                    if (message != null) Text(message!!, color = Color(0xFFE0524B), fontFamily = Manrope, fontWeight = FontWeight.W700, fontSize = 12.sp)
                    Row(horizontalArrangement = Arrangement.spacedBy(8.dp), modifier = Modifier.fillMaxWidth()) {
                        Box(contentAlignment = Alignment.Center, modifier = Modifier.weight(1f).height(47.dp).clip(RoundedCornerShape(13.dp)).background(cardSurfaceColor()).border(1.dp, contentBorderColor(), RoundedCornerShape(13.dp)).clickable { adding = false; message = null }) {
                            Text(localized("Отмена", "Cancel", "Cancelar", "Abbrechen"), color = contentTextColor(), fontFamily = Manrope, fontWeight = FontWeight.W800, fontSize = 14.sp)
                        }
                        Box(contentAlignment = Alignment.Center, modifier = Modifier.weight(1f).height(47.dp).shadow(6.dp, RoundedCornerShape(13.dp), clip = false, ambientColor = Color(0x476C5CE7), spotColor = Color(0x476C5CE7)).clip(RoundedCornerShape(13.dp)).background(primaryColor()).clickable(enabled = !saving) {
                            scope.launch {
                                saving = true
                                runCatching { SupabaseTripRepository(SupabaseProvider.clientForCurrentAuthFlow()).addMember(tripId, name, email, role) }
                                    .onSuccess { adding = false; name = ""; email = ""; onRoleUpdated() }
                                    .onFailure { message = localizedFailure(language, it, localized(language, "Не удалось добавить участника", "Could not add member", "No se pudo añadir al participante", "Mitglied konnte nicht hinzugefügt werden")) }
                                saving = false
                            }
                        }) {
                            Text(if (saving) localized("Сохраняем…", "Saving…", "Guardando…", "Wird gespeichert…") else localized("Пригласить", "Invite", "Invitar", "Einladen"), color = primaryContentColor(), fontFamily = Manrope, fontWeight = FontWeight.W800, fontSize = 14.sp)
                        }
                    }
                }
            }
        }
        if (canEdit) item {
            Box(
                contentAlignment = Alignment.Center,
                modifier = Modifier
                    .fillMaxWidth()
                    .height(55.dp)
                    .clip(RoundedCornerShape(18.dp))
                    .background(if (LocalDarkTheme.current) secondarySurfaceColor() else Color.White.copy(alpha = 0.4f))
                    .clickable { adding = true }
                    .drawBehind {
                        drawRoundRect(
                            color = dashedBorderColor,
                            cornerRadius = CornerRadius(18.dp.toPx()),
                            style = Stroke(width = 2.dp.toPx(), pathEffect = PathEffect.dashPathEffect(floatArrayOf(8.dp.toPx(), 6.dp.toPx()))),
                        )
                    },
            ) {
                Row(verticalAlignment = Alignment.CenterVertically) {
                    Text("＋", color = primaryColor(), fontFamily = Manrope, fontWeight = FontWeight.W500, fontSize = 18.sp)
                    Text(localized("Пригласить участника", "Invite member", "Invitar participante", "Mitglied einladen"), color = primaryColor(), fontFamily = Manrope, fontWeight = FontWeight.W800, fontSize = 14.sp, modifier = Modifier.padding(start = 5.dp))
                }
            }
        }
    }
    if (canEdit) deleteMember?.let { member ->
        val deleting = savingMemberId == member.id
        AlertDialog(
            onDismissRequest = {
                if (!deleting) {
                    deleteMember = null
                    deleteMemberError = null
                }
            },
            title = {
                Text(
                    localized("Удалить участника?", "Remove member?", "¿Eliminar participante?", "Mitglied entfernen?"),
                    fontFamily = Manrope,
                    fontWeight = FontWeight.W800,
                )
            },
            text = {
                Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                    Text(
                        localized(
                            "Участник «${member.name}» будет удалён из путешествия.",
                            "Member “${member.name}” will be removed from this trip.",
                            "El participante «${member.name}» se eliminará de este viaje.",
                            "Das Mitglied „${member.name}“ wird aus dieser Reise entfernt.",
                        ),
                        fontFamily = Manrope,
                        fontWeight = FontWeight.W600,
                    )
                    deleteMemberError?.let { error ->
                        Text(error, color = Color(0xFFE0524B), fontFamily = Manrope, fontWeight = FontWeight.W700, fontSize = 12.sp)
                    }
                }
            },
            dismissButton = {
                TextButton(
                    onClick = {
                        deleteMember = null
                        deleteMemberError = null
                    },
                    enabled = !deleting,
                ) {
                    Text(localized("Отмена", "Cancel", "Cancelar", "Abbrechen"), fontFamily = Manrope, fontWeight = FontWeight.W800)
                }
            },
            confirmButton = {
                TextButton(
                    onClick = {
                        scope.launch {
                            savingMemberId = member.id
                            deleteMemberError = null
                            runCatching { SupabaseTripRepository(SupabaseProvider.clientForCurrentAuthFlow()).deleteTripItem(tripId, "members", member.id) }
                                .onSuccess {
                                    deleteMember = null
                                    deleteMemberError = null
                                    actionMessage = null
                                    onRoleUpdated()
                                }
                                .onFailure {
                                    deleteMemberError = localizedFailure(language, it, localized(language, "Не удалось удалить участника. Проверьте интернет и повторите попытку.", "Could not remove the member. Check your connection and try again.", "No se pudo eliminar al participante. Comprueba la conexión e inténtalo de nuevo.", "Mitglied konnte nicht entfernt werden. Prüfen Sie die Verbindung und versuchen Sie es erneut."))
                                }
                            savingMemberId = null
                        }
                    },
                    enabled = !deleting,
                    colors = ButtonDefaults.textButtonColors(contentColor = Color(0xFFD9534F)),
                ) {
                    Text(
                        if (deleting) localized("Удаляем…", "Removing…", "Eliminando…", "Wird entfernt…")
                        else localized("Удалить", "Remove", "Eliminar", "Entfernen"),
                        fontFamily = Manrope,
                        fontWeight = FontWeight.W800,
                    )
                }
            },
        )
    }
}

@Composable
private fun InviteMemberField(placeholder: String, value: String, onValueChange: (String) -> Unit) {
    val shape = RoundedCornerShape(13.dp)
    Box(
        modifier = Modifier
            .fillMaxWidth()
            .height(47.dp)
            .clip(shape)
            .background(cardSurfaceColor())
            .border(1.dp, contentBorderColor(), shape),
        contentAlignment = Alignment.CenterStart,
    ) {
        BasicTextField(
            value = value,
            onValueChange = onValueChange,
            singleLine = true,
            textStyle = androidx.compose.ui.text.TextStyle(
                color = contentTextColor(),
                fontFamily = Manrope,
                fontWeight = FontWeight.W600,
                fontSize = 14.5.sp,
                platformStyle = OdysseyNoFontPadding,
            ),
            cursorBrush = androidx.compose.ui.graphics.SolidColor(primaryColor()),
            modifier = Modifier.fillMaxSize().padding(horizontal = 14.dp),
            decorationBox = { innerTextField ->
                Box(modifier = Modifier.fillMaxSize(), contentAlignment = Alignment.CenterStart) {
                    if (value.isBlank()) {
                        Text(
                            placeholder,
                            color = secondaryTextColor(),
                            fontFamily = Manrope,
                            fontWeight = FontWeight.W600,
                            fontSize = 14.5.sp,
                            style = androidx.compose.ui.text.TextStyle(platformStyle = OdysseyNoFontPadding),
                            maxLines = 1,
                            softWrap = false,
                            overflow = TextOverflow.Ellipsis,
                        )
                    }
                    innerTextField()
                }
            },
        )
    }
}

@Composable
private fun MemberCard(member: com.odyssey.travelplanner.data.TripMember, saving: Boolean, editing: Boolean, onDelete: () -> Unit, onRoleChange: (String) -> Unit) {
    val language = LocalLanguage.current
    val darkTheme = LocalDarkTheme.current
    val surface = cardSurfaceColor()
    val avatarColor = when (member.tone) {
        "sand", "orange" -> Color(0xFFF29A32)
        "teal", "green" -> Color(0xFF35AEB9)
        else -> primaryColor()
    }
    val isOwner = member.role == "Владелец"
    val roleLabel = when (member.role) {
        "Владелец" -> localized(language, "Владелец", "Owner", "Propietario", "Besitzer")
        "Редактор" -> localized(language, "Редактор", "Editor", "Editor", "Editor")
        "Читатель" -> localized(language, "Просмотр", "Viewer", "Lector", "Leser")
        else -> member.role
    }
    val roleBackground = when (member.role) {
        "Владелец" -> if (darkTheme) OdysseyDarkTint else Color(0xFFEDEAFF)
        "Редактор" -> if (darkTheme) Color(0xFF203C35) else Color(0xFFEEFAF3)
        else -> secondarySurfaceColor()
    }
    val roleColor = when (member.role) {
        "Владелец" -> primaryColor()
        "Редактор" -> Color(0xFF22B07D)
        else -> secondaryTextColor()
    }
    Column(
        modifier = Modifier.fillMaxWidth().shadow(6.dp, RoundedCornerShape(18.dp), clip = false, ambientColor = Color(0x0F141428), spotColor = Color(0x0F141428)).clip(RoundedCornerShape(18.dp)).background(surface).padding(horizontal = 15.dp, vertical = 13.dp),
    ) {
        Row(verticalAlignment = Alignment.CenterVertically, modifier = Modifier.fillMaxWidth()) {
            Box(contentAlignment = Alignment.Center, modifier = Modifier.size(44.dp).clip(RoundedCornerShape(13.dp)).background(avatarColor)) {
                Text(member.initials.take(1), color = Color.White, fontFamily = Manrope, fontWeight = FontWeight.W800, fontSize = 18.sp)
            }
            Column(modifier = Modifier.weight(1f).padding(start = 13.dp)) {
                Text(member.name, color = contentTextColor(), fontFamily = Manrope, fontWeight = FontWeight.W800, fontSize = 15.sp, maxLines = 1, overflow = TextOverflow.Ellipsis)
                if (member.email.isNotBlank()) Text(member.email, color = secondaryTextColor(), fontFamily = Manrope, fontWeight = FontWeight.W600, fontSize = 12.sp, modifier = Modifier.padding(top = 2.dp), maxLines = 1, overflow = TextOverflow.Ellipsis)
            }
            if (!editing || isOwner) {
                Box(contentAlignment = Alignment.Center, modifier = Modifier.clip(RoundedCornerShape(20.dp)).background(roleBackground).padding(horizontal = 10.dp, vertical = 5.dp)) {
                    Text(if (saving) "…" else roleLabel, color = roleColor, fontFamily = Manrope, fontWeight = FontWeight.W800, fontSize = 11.sp)
                }
            }
        }
        if (editing && !isOwner) {
            Row(horizontalArrangement = Arrangement.spacedBy(6.dp), verticalAlignment = Alignment.CenterVertically, modifier = Modifier.fillMaxWidth().padding(top = 12.dp)) {
                listOf(
                    localized("Редактор", "Editor", "Editor", "Editor") to "Редактор",
                    localized("Просмотр", "Viewer", "Lector", "Leser") to "Читатель",
                ).forEach { (label, value) ->
                    val selected = member.role == value
                    Box(contentAlignment = Alignment.Center, modifier = Modifier.weight(1f).height(36.dp).clip(RoundedCornerShape(11.dp)).background(if (selected) cardSurfaceColor() else secondarySurfaceColor()).border(if (selected) 1.dp else 0.dp, if (selected) contentBorderColor() else Color.Transparent, RoundedCornerShape(11.dp)).clickable(enabled = !saving) { onRoleChange(value) }) {
                        Text(label, color = if (selected) contentTextColor() else secondaryTextColor(), fontFamily = Manrope, fontWeight = FontWeight.W800, fontSize = 12.sp)
                    }
                }
                Box(contentAlignment = Alignment.Center, modifier = Modifier.size(36.dp).clip(RoundedCornerShape(11.dp)).background(dangerSurfaceColor()).clickable(enabled = !saving) { onDelete() }) {
                    Icon(Icons.Outlined.Delete, contentDescription = localized("Удалить участника", "Remove member", "Eliminar participante", "Mitglied entfernen"), tint = Color(0xFFE35D61), modifier = Modifier.size(18.dp))
                }
            }
        }
    }
}

@Composable
@OptIn(ExperimentalMaterial3Api::class)
private fun BudgetContent(
    tripId: String,
    overview: TripOverview,
    canEdit: Boolean = true,
    onExpenseAdded: () -> Unit,
    onCurrencyChanged: (String) -> Unit,
) {
    val language = LocalLanguage.current
    val scope = rememberCoroutineScope()
    val expenses = overview.budgetExpenses
    val categoryStyles = listOf(
        BudgetCategoryStyle("Жильё", "Жильё", Color(0xFF6C5CE7), setOf("жильё", "жилье", "проживание")),
        BudgetCategoryStyle("Транспорт", "Транспорт", Color(0xFFF5A623), setOf("транспорт")),
        BudgetCategoryStyle("Еда и рестораны", "Питание", Color(0xFF22B07D), setOf("еда и рестораны", "питание", "еда")),
        BudgetCategoryStyle("Активности и билеты", "Развлечения", Color(0xFF4AA3F0), setOf("активности и билеты", "развлечения", "активности")),
        BudgetCategoryStyle("Прочее", "Прочее", Color(0xFFEE6C8A), setOf("прочее")),
    )
    val currencyOptions = listOf(
        BudgetCurrencyStyle("RUB", "₽"),
        BudgetCurrencyStyle("EUR", "€"),
        BudgetCurrencyStyle("CZK", "Kč"),
    )
    val storedCurrencyCode = budgetCurrencyCode(overview.budgetCurrency)
    var selectedCurrencyCode by remember(tripId, storedCurrencyCode) { mutableStateOf(storedCurrencyCode) }
    val currencySymbol = currencyOptions.firstOrNull { it.code == selectedCurrencyCode }?.symbol ?: "₽"
    val exchangeRateRepository = remember { ExchangeRateRepository() }
    DisposableEffect(exchangeRateRepository) {
        onDispose { exchangeRateRepository.close() }
    }
    val storedManualRates = overview.budgetManualRates
    var manualRates by remember(tripId, storedManualRates) { mutableStateOf(storedManualRates) }
    var onlineRates by remember(tripId) { mutableStateOf<Map<String, Double>>(emptyMap()) }
    var onlineRateDate by remember(tripId) { mutableStateOf("") }
    var loadingRates by remember(tripId) { mutableStateOf(false) }
    var ratesMessage by remember(tripId) { mutableStateOf<String?>(null) }
    val budgetScrollState = rememberScrollState()
    LaunchedEffect(Unit) { budgetScrollState.scrollTo(0) }

    var adding by remember { mutableStateOf(false) }
    var editingExpense by remember { mutableStateOf<com.odyssey.travelplanner.data.BudgetExpense?>(null) }
    var editMode by remember { mutableStateOf(false) }
    var name by remember { mutableStateOf("") }
    var amountInput by remember { mutableStateOf("") }
    var category by remember { mutableStateOf("Еда и рестораны") }
    var scopeName by remember { mutableStateOf("общий") }
    var paidBy by remember { mutableStateOf("Общее") }
    var date by remember { mutableStateOf("") }
    var datePickerOpen by remember { mutableStateOf(false) }
    var saving by remember { mutableStateOf(false) }
    var savingCurrency by remember { mutableStateOf(false) }
    var deletingExpenseId by remember { mutableStateOf<String?>(null) }
    var deleteExpense by remember { mutableStateOf<com.odyssey.travelplanner.data.BudgetExpense?>(null) }
    var deleteExpenseError by remember { mutableStateOf<String?>(null) }
    var message by remember { mutableStateOf<String?>(null) }
    var rateEditorCode by remember { mutableStateOf<String?>(null) }
    var rateReferenceCode by remember { mutableStateOf("RUB") }
    var rateInput by remember { mutableStateOf("") }
    var rateError by remember { mutableStateOf<String?>(null) }
    var savingRate by remember { mutableStateOf(false) }

    fun fallbackCurrencyRate(code: String): Double = when (code) {
        "EUR" -> 1.0 / 100.0
        "CZK" -> 1.0 / 4.0
        else -> 1.0
    }

    fun effectiveCurrencyRate(code: String): Double = when {
        code == "RUB" -> 1.0
        manualRates[code]?.takeIf { it > 0.0 } != null -> manualRates.getValue(code)
        onlineRates[code]?.takeIf { it > 0.0 } != null -> onlineRates.getValue(code)
        else -> fallbackCurrencyRate(code)
    }

    val hasReliableCurrencyRate = selectedCurrencyCode == "RUB" ||
        manualRates[selectedCurrencyCode]?.let { it > 0.0 } == true ||
        onlineRates[selectedCurrencyCode]?.let { it > 0.0 } == true
    val missingCurrencyRateMessage = localized(
        "Курс валюты ещё не загружен. Обновите курс или задайте его вручную.",
        "The exchange rate is not loaded yet. Refresh it or set it manually.",
        "El tipo de cambio aún no está cargado. Actualízalo o establécelo manualmente.",
        "Der Wechselkurs ist noch nicht geladen. Aktualisieren Sie ihn oder geben Sie ihn manuell ein.",
    )

    fun rubPerCurrencyUnit(code: String): Double = 1.0 / effectiveCurrencyRate(code)

    fun rateInReferenceCurrency(code: String, referenceCode: String): Double =
        rubPerCurrencyUnit(code) * effectiveCurrencyRate(referenceCode)

    val peopleCount = (overview.budgetGroups.sumOf { it.people }.takeIf { it > 0 } ?: overview.members.size).coerceAtLeast(1)
    val dayCount = budgetTripDayCount(overview.dates)
    val currencyRate = effectiveCurrencyRate(selectedCurrencyCode)
    fun displayedExpenseAmount(expense: com.odyssey.travelplanner.data.BudgetExpense): Double =
        expense.amountIn(selectedCurrencyCode, currencyRate)
    val total = expenses.sumOf(::displayedExpenseAmount)

    suspend fun refreshOnlineRates() {
        loadingRates = true
        ratesMessage = null
        runCatching { exchangeRateRepository.loadRubRates(currencyOptions.map { it.code }.toSet()) }
            .onSuccess {
                onlineRates = it.rates
                onlineRateDate = it.date
            }
            .onFailure {
                ratesMessage = localized(language, "Не удалось обновить онлайн-курс", "Could not refresh the online rate", "No se pudo actualizar el tipo online", "Online-Kurs konnte nicht aktualisiert werden")
            }
        loadingRates = false
    }

    LaunchedEffect(tripId) { refreshOnlineRates() }

    fun manualRatesJson(rates: Map<String, Double>) = buildJsonObject {
        rates.toSortedMap().forEach { (code, rate) -> put(code, rate) }
    }

    fun saveManualRate() {
        val code = rateEditorCode ?: return
        val referenceRate = effectiveCurrencyRate(rateReferenceCode)
        val referenceUnitsPerUnit = rateInput.replace(',', '.').toDoubleOrNull()
        val rubPerUnit = referenceUnitsPerUnit?.let { it / referenceRate }
        if (rubPerUnit == null || rubPerUnit <= 0.0) {
            rateError = localized(language, "Введите курс больше нуля", "Enter a rate greater than zero", "Introduce un tipo mayor que cero", "Geben Sie einen Kurs größer als null ein")
            return
        }
        val previousRates = manualRates
        val previousAmountInput = amountInput
        val previousRate = effectiveCurrencyRate(code)
        val updatedRates = manualRates.toMutableMap().apply { put(code, 1.0 / rubPerUnit) }
        manualRates = updatedRates
        if (code == selectedCurrencyCode) {
            previousAmountInput.replace(',', '.').toDoubleOrNull()?.let { enteredAmount ->
                amountInput = formatBudgetInput(enteredAmount / previousRate, effectiveCurrencyRate(code))
            }
        }
        scope.launch {
            savingRate = true
            runCatching {
                SupabaseTripRepository(SupabaseProvider.clientForCurrentAuthFlow()).updateTripSection(
                    tripId,
                    "budgetManualRates",
                    manualRatesJson(updatedRates),
                )
            }.onSuccess {
                rateEditorCode = null
                rateError = null
            }.onFailure {
                manualRates = previousRates
                amountInput = previousAmountInput
                rateError = localizedFailure(language, it, localized(language, "Не удалось сохранить курс", "Could not save the rate", "No se pudo guardar el tipo", "Kurs konnte nicht gespeichert werden"))
            }
            savingRate = false
        }
    }

    fun changeRateReference(referenceCode: String) {
        val code = rateEditorCode ?: return
        if (referenceCode == rateReferenceCode) return
        val previousReferenceCode = rateReferenceCode
        val enteredValue = rateInput.replace(',', '.').toDoubleOrNull()
        rateReferenceCode = referenceCode
        if (enteredValue != null && enteredValue > 0.0) {
            val rubPerUnit = enteredValue / effectiveCurrencyRate(previousReferenceCode)
            rateInput = formatBudgetRateInput(rubPerUnit * effectiveCurrencyRate(referenceCode))
        } else {
            rateInput = formatBudgetRateInput(rateInReferenceCurrency(code, referenceCode))
        }
    }

    fun resetManualRate() {
        val code = rateEditorCode ?: return
        val previousRates = manualRates
        val previousAmountInput = amountInput
        val previousRate = effectiveCurrencyRate(code)
        val updatedRates = manualRates.toMutableMap().apply { remove(code) }
        manualRates = updatedRates
        if (code == selectedCurrencyCode) {
            previousAmountInput.replace(',', '.').toDoubleOrNull()?.let { enteredAmount ->
                amountInput = formatBudgetInput(enteredAmount / previousRate, effectiveCurrencyRate(code))
            }
        }
        scope.launch {
            savingRate = true
            runCatching {
                SupabaseTripRepository(SupabaseProvider.clientForCurrentAuthFlow()).updateTripSection(
                    tripId,
                    "budgetManualRates",
                    manualRatesJson(updatedRates),
                )
            }.onSuccess {
                rateEditorCode = null
                rateError = null
            }.onFailure {
                manualRates = previousRates
                amountInput = previousAmountInput
                rateError = localizedFailure(language, it, localized(language, "Не удалось сбросить курс", "Could not reset the rate", "No se pudo restablecer el tipo", "Kurs konnte nicht zurückgesetzt werden"))
            }
            savingRate = false
        }
    }

    fun closeExpenseSheet() {
        adding = false
        editingExpense = null
        datePickerOpen = false
        message = null
    }

    fun openNewExpense() {
        name = ""
        amountInput = ""
        category = "Еда и рестораны"
        scopeName = "общий"
        paidBy = "Общее"
        date = ""
        message = null
        editingExpense = null
        adding = true
    }

    fun openEditExpense(expense: com.odyssey.travelplanner.data.BudgetExpense) {
        name = expense.name
        amountInput = formatBudgetInput(displayedExpenseAmount(expense), 1.0)
        category = categoryStyles.firstOrNull { it.aliases.contains(expense.category.trim().lowercase(java.util.Locale.ROOT)) }?.key ?: "Прочее"
        scopeName = budgetScopeValue(expense.scope)
        paidBy = expense.paidBy.ifBlank { "Общее" }
        date = expense.date
        message = null
        adding = false
        editingExpense = expense
    }

    Column(
        modifier = Modifier
            .fillMaxSize()
            .windowInsetsPadding(WindowInsets.navigationBars)
            .verticalScroll(budgetScrollState)
            .padding(start = 18.dp, top = 18.dp, end = 18.dp, bottom = 30.dp),
    ) {
        BudgetSummaryCard(total = total, currencySymbol = currencySymbol, conversionRate = 1.0)
        Spacer(Modifier.height(14.dp))
        BudgetCurrencySelector(
            selectedCode = selectedCurrencyCode,
            options = currencyOptions,
            saving = savingCurrency,
            editable = canEdit,
            onSelect = { selected ->
                if (selected != selectedCurrencyCode && !savingCurrency) {
                    val previousCurrencyCode = selectedCurrencyCode
                    val previousAmountInput = amountInput
                    selectedCurrencyCode = selected
                    previousAmountInput.replace(',', '.').toDoubleOrNull()?.let { enteredAmount ->
                        val baseAmount = enteredAmount / effectiveCurrencyRate(previousCurrencyCode)
                        amountInput = formatBudgetInput(baseAmount, effectiveCurrencyRate(selected))
                    }
                    scope.launch {
                        savingCurrency = true
                        runCatching {
                            SupabaseTripRepository(SupabaseProvider.clientForCurrentAuthFlow()).updateTripSection(
                                tripId,
                                "budgetCurrency",
                                JsonPrimitive(selected),
                            )
                        }.onSuccess { onCurrencyChanged(selected) }
                            .onFailure {
                                selectedCurrencyCode = previousCurrencyCode
                                amountInput = previousAmountInput
                                message = localizedFailure(language, it, localized(language, "Не удалось изменить валюту", "Could not change currency", "No se pudo cambiar la moneda", "Währung konnte nicht geändert werden"))
                            }
                        savingCurrency = false
                    }
                }
            },
        )
        Spacer(Modifier.height(10.dp))
        BudgetExchangeRateCard(
            currencyCode = selectedCurrencyCode,
            rubPerUnit = rubPerCurrencyUnit(selectedCurrencyCode),
            isManual = manualRates.containsKey(selectedCurrencyCode),
            loading = loadingRates,
            onlineRateDate = onlineRateDate,
            hasOnlineRate = selectedCurrencyCode == "RUB" || onlineRates.containsKey(selectedCurrencyCode),
            message = ratesMessage,
            onEdit = {
                if (canEdit && selectedCurrencyCode != "RUB") {
                    rateEditorCode = selectedCurrencyCode
                    rateReferenceCode = "RUB"
                    rateInput = formatBudgetRateInput(rubPerCurrencyUnit(selectedCurrencyCode))
                    rateError = null
                }
            },
            onRefresh = { scope.launch { refreshOnlineRates() } },
            editable = canEdit,
        )
        Spacer(Modifier.height(14.dp))
        Row(horizontalArrangement = Arrangement.spacedBy(10.dp), modifier = Modifier.fillMaxWidth().height(71.dp)) {
            BudgetMetricCard(
                label = localized("НА ЧЕЛОВЕКА", "PER PERSON", "POR PERSONA", "PRO PERSON"),
                value = formatBudgetAmount(if (peopleCount == 0) 0.0 else total / peopleCount, currencySymbol, 1.0),
                modifier = Modifier.weight(1f),
            )
            BudgetMetricCard(
                label = localized("В ДЕНЬ", "PER DAY", "POR DÍA", "PRO TAG"),
                value = formatBudgetAmount(if (dayCount == 0) 0.0 else total / dayCount, currencySymbol, 1.0),
                modifier = Modifier.weight(1f),
            )
        }
        Spacer(Modifier.height(22.dp))
        Text(
            text = localized("По категориям", "By category", "Por categorías", "Nach Kategorien"),
            color = contentTextColor(),
            fontFamily = Manrope,
            fontWeight = FontWeight.W800,
            fontSize = 16.sp,
            lineHeight = 22.sp,
            style = androidx.compose.ui.text.TextStyle(platformStyle = OdysseyNoFontPadding),
            modifier = Modifier.height(22.dp),
        )
        Spacer(Modifier.height(14.dp))
        Column(verticalArrangement = Arrangement.spacedBy(16.dp), modifier = Modifier.fillMaxWidth()) {
            categoryStyles.forEach { categoryStyle ->
                val categoryTotal = expenses.filter { expense ->
                    categoryStyle.aliases.contains(expense.category.trim().lowercase(java.util.Locale.ROOT))
                }.sumOf(::displayedExpenseAmount)
                BudgetCategoryRow(
                    style = categoryStyle,
                    amount = categoryTotal,
                    total = total,
                    currencySymbol = currencySymbol,
                    conversionRate = 1.0,
                )
            }
        }
        Spacer(Modifier.height(22.dp))
        BudgetExpensesCard(
            expenses = expenses,
            currencySymbol = currencySymbol,
            currencyCode = selectedCurrencyCode,
            currentConversionRate = currencyRate,
            editMode = editMode,
            editable = canEdit,
            deletingExpenseId = deletingExpenseId,
            onToggleEditMode = { editMode = !editMode },
            onAdd = {
                if (hasReliableCurrencyRate) openNewExpense() else ratesMessage = missingCurrencyRateMessage
            },
            onEdit = { expense ->
                if (hasReliableCurrencyRate) openEditExpense(expense) else ratesMessage = missingCurrencyRateMessage
            },
            onDelete = { expense ->
                if (canEdit) {
                    deleteExpense = expense
                    deleteExpenseError = null
                }
            },
        )
    }

    if (canEdit && (adding || editingExpense != null)) {
        ModalBottomSheet(
            onDismissRequest = ::closeExpenseSheet,
            sheetState = rememberModalBottomSheetState(skipPartiallyExpanded = true),
            containerColor = cardSurfaceColor(),
            tonalElevation = 0.dp,
            scrimColor = Color(0x730F0F19),
            shape = RoundedCornerShape(topStart = 26.dp, topEnd = 26.dp),
            dragHandle = null,
        ) {
            BudgetExpenseSheet(
                title = if (editingExpense == null) localized("Новая трата", "New expense", "Nuevo gasto", "Neue Ausgabe") else localized("Редактировать трату", "Edit expense", "Editar gasto", "Ausgabe bearbeiten"),
                currencySymbol = currencySymbol,
                name = name,
                amount = amountInput,
                payer = paidBy,
                date = date,
                category = category,
                scopeName = scopeName,
                editing = editingExpense != null,
                saving = saving,
                message = message,
                onNameChange = { name = it },
                onAmountChange = { amountInput = it },
                onPayerChange = { paidBy = it },
                onDateClick = { datePickerOpen = true },
                onCategoryChange = { category = it },
                onScopeChange = { scopeName = it },
                onClose = ::closeExpenseSheet,
                onSave = {
                    if (!hasReliableCurrencyRate) {
                        message = missingCurrencyRateMessage
                    } else {
                        scope.launch {
                            saving = true
                            message = null
                            val value = amountInput.replace(',', '.').toDoubleOrNull() ?: 0.0
                            val baseValue = value / currencyRate
                            val expenseName = name.trim().ifBlank { category }
                            val input = com.odyssey.travelplanner.data.ExpenseInput(
                                name = expenseName,
                                amount = baseValue,
                                category = category,
                                scope = scopeName,
                                paidBy = paidBy,
                                date = date,
                                inputCurrency = selectedCurrencyCode,
                                inputCurrencyRate = currencyRate,
                            )
                            runCatching {
                                val repository = SupabaseTripRepository(SupabaseProvider.clientForCurrentAuthFlow())
                                editingExpense?.let { expense ->
                                    repository.updateBudgetExpenseDetails(tripId, expense.id, input)
                                } ?: repository.addBudgetExpenseDetails(tripId, input)
                            }.onSuccess {
                                closeExpenseSheet()
                                onExpenseAdded()
                            }.onFailure {
                                message = localizedFailure(language, it, localized(language, "Не удалось сохранить трату", "Could not save expense", "No se pudo guardar el gasto", "Ausgabe konnte nicht gespeichert werden"))
                            }
                            saving = false
                        }
                    }
                },
            )
        }
    }
    if (datePickerOpen) {
        AccommodationCalendarDialog(
            initialValue = date,
            onDismiss = { datePickerOpen = false },
            onConfirm = {
                date = it
                datePickerOpen = false
            },
        )
    }
    if (canEdit) deleteExpense?.let { expense ->
        val deleting = deletingExpenseId == expense.id
        AlertDialog(
            onDismissRequest = {
                if (!deleting) {
                    deleteExpense = null
                    deleteExpenseError = null
                }
            },
            title = {
                Text(
                    localized("Удалить расход?", "Delete expense?", "¿Eliminar gasto?", "Ausgabe löschen?"),
                    fontFamily = Manrope,
                    fontWeight = FontWeight.W800,
                )
            },
            text = {
                Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                    Text(
                        localized(
                            "Расход «${expense.name}» будет удалён без возможности восстановления.",
                            "Expense “${expense.name}” will be permanently deleted.",
                            "El gasto «${expense.name}» se eliminará de forma permanente.",
                            "Die Ausgabe „${expense.name}“ wird dauerhaft gelöscht.",
                        ),
                        fontFamily = Manrope,
                        fontWeight = FontWeight.W600,
                    )
                    deleteExpenseError?.let { error ->
                        Text(error, color = Color(0xFFE0524B), fontFamily = Manrope, fontWeight = FontWeight.W700, fontSize = 12.sp)
                    }
                }
            },
            dismissButton = {
                TextButton(
                    onClick = {
                        deleteExpense = null
                        deleteExpenseError = null
                    },
                    enabled = !deleting,
                ) {
                    Text(localized("Отмена", "Cancel", "Cancelar", "Abbrechen"), fontFamily = Manrope, fontWeight = FontWeight.W800)
                }
            },
            confirmButton = {
                TextButton(
                    onClick = {
                        scope.launch {
                            deletingExpenseId = expense.id
                            deleteExpenseError = null
                            runCatching {
                                SupabaseTripRepository(SupabaseProvider.clientForCurrentAuthFlow()).deleteTripItem(tripId, "budgetExpenses", expense.id)
                            }.onSuccess {
                                deleteExpense = null
                                deleteExpenseError = null
                                onExpenseAdded()
                            }.onFailure {
                                deleteExpenseError = localizedFailure(language, it, localized(language, "Не удалось удалить расход", "Could not delete expense", "No se pudo eliminar el gasto", "Ausgabe konnte nicht gelöscht werden"))
                            }
                            deletingExpenseId = null
                        }
                    },
                    enabled = !deleting,
                    colors = ButtonDefaults.textButtonColors(contentColor = Color(0xFFD9534F)),
                ) {
                    Text(
                        if (deleting) localized("Удаляем…", "Deleting…", "Eliminando…", "Wird gelöscht…")
                        else localized("Удалить", "Delete", "Eliminar", "Löschen"),
                        fontFamily = Manrope,
                        fontWeight = FontWeight.W800,
                    )
                }
            },
        )
    }
    if (canEdit) rateEditorCode?.let { code ->
        AlertDialog(
            onDismissRequest = { if (!savingRate) rateEditorCode = null },
            title = {
                Text(
                    localized("Курс $code", "${code} exchange rate", "Tipo $code", "$code-Wechselkurs"),
                    fontFamily = Manrope,
                    fontWeight = FontWeight.W800,
                )
            },
            text = {
                Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                    Text(
                        localized("Считать курс в", "Quote the rate in", "Expresar el tipo en", "Kurs angeben in"),
                        fontFamily = Manrope,
                        fontWeight = FontWeight.W700,
                        fontSize = 12.sp,
                    )
                    Row(horizontalArrangement = Arrangement.spacedBy(6.dp)) {
                        currencyOptions.filter { it.code != code }.forEach { option ->
                            val selected = option.code == rateReferenceCode
                            Text(
                                "${option.code} ${option.symbol}",
                                color = if (selected) primaryContentColor() else secondaryTextColor(),
                                fontFamily = Manrope,
                                fontWeight = FontWeight.W800,
                                fontSize = 12.sp,
                                modifier = Modifier
                                    .clip(RoundedCornerShape(10.dp))
                                    .background(if (selected) primaryColor() else secondarySurfaceColor())
                                    .clickable(enabled = !savingRate) { changeRateReference(option.code) }
                                    .padding(horizontal = 10.dp, vertical = 7.dp),
                            )
                        }
                    }
                    Text(
                        localized(
                            "Укажите, сколько $rateReferenceCode стоит 1 $code",
                            "Enter how many $rateReferenceCode 1 $code costs",
                            "Indica cuántos $rateReferenceCode cuesta 1 $code",
                            "Geben Sie an, wie viele $rateReferenceCode 1 $code kostet",
                        ),
                        fontFamily = Manrope,
                    )
                    AuthField(
                        label = localized("Курс в $rateReferenceCode", "Rate in $rateReferenceCode", "Tipo en $rateReferenceCode", "Kurs in $rateReferenceCode"),
                        placeholder = "100,00",
                        value = rateInput,
                        onValueChange = { rateInput = it },
                    )
                    rateError?.let {
                        Text(it, color = Color(0xFFE0524B), fontFamily = Manrope, fontWeight = FontWeight.W700, fontSize = 12.sp)
                    }
                    if (manualRates.containsKey(code)) {
                        TextButton(onClick = ::resetManualRate, enabled = !savingRate) {
                            Text(
                                localized("Сбросить на онлайн-курс", "Use online rate", "Usar tipo online", "Online-Kurs verwenden"),
                                color = primaryColor(),
                                fontFamily = Manrope,
                                fontWeight = FontWeight.W800,
                            )
                        }
                    }
                }
            },
            dismissButton = {
                TextButton(onClick = { rateEditorCode = null }, enabled = !savingRate) {
                    Text(localized("Отмена", "Cancel", "Cancelar", "Abbrechen"), fontFamily = Manrope, fontWeight = FontWeight.W800)
                }
            },
            confirmButton = {
                TextButton(onClick = ::saveManualRate, enabled = !savingRate) {
                    Text(
                        if (savingRate) localized("Сохраняем…", "Saving…", "Guardando…", "Wird gespeichert…")
                        else localized("Сохранить", "Save", "Guardar", "Speichern"),
                        color = primaryColor(),
                        fontFamily = Manrope,
                        fontWeight = FontWeight.W800,
                    )
                }
            },
        )
    }
}

private data class BudgetCategoryStyle(
    val key: String,
    val label: String,
    val color: Color,
    val aliases: Set<String>,
)

private data class BudgetCurrencyStyle(val code: String, val symbol: String)

private fun budgetCurrencyCode(value: String): String = when (value.trim().uppercase(java.util.Locale.ROOT)) {
    "RUB", "₽" -> "RUB"
    "EUR", "€" -> "EUR"
    "CZK", "KČ", "Kč" -> "CZK"
    else -> "RUB"
}

@Composable
private fun localizedBudgetExpenseName(value: String): String {
    val normalized = value.trim().lowercase(Locale.ROOT)
    return when {
        normalized == "жильё" || normalized == "жилье" || normalized == "проживание" -> localized("Жильё", "Lodging", "Alojamiento", "Unterkunft")
        normalized == "аренда машины" -> localized("Аренда машины", "Car rental", "Alquiler de coche", "Mietwagen")
        normalized == "бензин" -> localized("Бензин", "Fuel", "Combustible", "Kraftstoff")
        normalized.startsWith("дневные траты") -> localized(
            "Дневные траты · 28 сентября – 13 октября",
            "Daily expenses · 28 Sep – 13 Oct",
            "Gastos diarios · 28 sep – 13 oct",
            "Tagesausgaben · 28. Sep. – 13. Okt.",
        )
        else -> value
    }
}

private fun budgetScopeValue(value: String): String = when (value.trim().lowercase(java.util.Locale.ROOT)) {
    "семья", "family" -> "семья"
    "личный", "личное", "personal" -> "личный"
    else -> "общий"
}

private fun budgetTripDayCount(value: String): Int {
    parseTripDateRange(value)?.let { (start, end) ->
        return (ChronoUnit.DAYS.between(start, end).toInt() + 1).coerceAtLeast(1)
    }
    val match = Regex("""(\d+)\s*(?:дн\w*|day\w*|día\w*|tag\w*)""", RegexOption.IGNORE_CASE).find(value)
    return match?.groupValues?.getOrNull(1)?.toIntOrNull()?.coerceAtLeast(1) ?: 1
}

private fun formatBudgetRate(value: Double): String {
    val symbols = java.text.DecimalFormatSymbols(java.util.Locale("ru", "RU")).apply {
        groupingSeparator = '\u00A0'
        decimalSeparator = ','
    }
    return java.text.DecimalFormat("#,##0.####", symbols).format(value)
}

private fun formatBudgetRateInput(value: Double): String =
    java.text.DecimalFormat("0.####", java.text.DecimalFormatSymbols(java.util.Locale.US)).format(value)

private fun formatBudgetInput(value: Double, conversionRate: Double): String =
    java.text.DecimalFormat("0.##", java.text.DecimalFormatSymbols(java.util.Locale.US)).format(value * conversionRate)

private fun formatBudgetAmount(value: Double, currencySymbol: String, conversionRate: Double): String {
    val symbols = java.text.DecimalFormatSymbols(java.util.Locale("ru", "RU")).apply {
        groupingSeparator = '\u00A0'
        decimalSeparator = ','
    }
    val displayValue = value * conversionRate
    val pattern = if (displayValue % 1.0 == 0.0) "#,##0" else "#,##0.##"
    val formattedValue = java.text.DecimalFormat(pattern, symbols).format(displayValue)
    return if (budgetCurrencyCode(currencySymbol) == "RUB") "$formattedValue $currencySymbol" else "$currencySymbol $formattedValue"
}

