@Composable
private fun AccommodationCalendarDialog(
    initialValue: String,
    minimumDate: Calendar? = null,
    onDismiss: () -> Unit,
    onConfirm: (String) -> Unit,
) {
    val language = LocalLanguage.current
    val minimumCalendar = remember(minimumDate?.timeInMillis) {
        minimumDate?.let {
            Calendar.getInstance().apply {
                clear()
                set(it.get(Calendar.YEAR), it.get(Calendar.MONTH), it.get(Calendar.DAY_OF_MONTH))
            }
        }
    }
    val initialCalendar = remember(initialValue, minimumCalendar?.timeInMillis) {
        accommodationDateCalendar(initialValue).let { candidate ->
            if (minimumCalendar != null && candidate.before(minimumCalendar)) {
                minimumCalendar.clone() as Calendar
            } else {
                candidate
            }
        }
    }
    var displayedYear by remember(initialValue, minimumCalendar?.timeInMillis) { mutableStateOf(initialCalendar.get(Calendar.YEAR)) }
    var displayedMonth by remember(initialValue, minimumCalendar?.timeInMillis) { mutableStateOf(initialCalendar.get(Calendar.MONTH)) }
    var selectedYear by remember(initialValue, minimumCalendar?.timeInMillis) { mutableStateOf(initialCalendar.get(Calendar.YEAR)) }
    var selectedMonth by remember(initialValue, minimumCalendar?.timeInMillis) { mutableStateOf(initialCalendar.get(Calendar.MONTH)) }
    var selectedDay by remember(initialValue, minimumCalendar?.timeInMillis) { mutableStateOf(initialCalendar.get(Calendar.DAY_OF_MONTH)) }
    val monthNames = when (language) {
        "EN" -> listOf("January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December")
        "ES" -> listOf("enero", "febrero", "marzo", "abril", "mayo", "junio", "julio", "agosto", "septiembre", "octubre", "noviembre", "diciembre")
        "DE" -> listOf("Januar", "Februar", "März", "April", "Mai", "Juni", "Juli", "August", "September", "Oktober", "November", "Dezember")
        else -> listOf("январь", "февраль", "март", "апрель", "май", "июнь", "июль", "август", "сентябрь", "октябрь", "ноябрь", "декабрь")
    }
    val weekDays = when (language) {
        "EN" -> listOf("M", "T", "W", "T", "F", "S", "S")
        "ES" -> listOf("L", "M", "X", "J", "V", "S", "D")
        "DE" -> listOf("M", "D", "M", "D", "F", "S", "S")
        else -> listOf("П", "В", "С", "Ч", "П", "С", "В")
    }
    val daysInMonth = Calendar.getInstance().apply {
        clear()
        set(displayedYear, displayedMonth + 1, 0)
    }.get(Calendar.DAY_OF_MONTH)
    val firstDay = Calendar.getInstance().apply {
        clear()
        set(displayedYear, displayedMonth, 1)
    }.get(Calendar.DAY_OF_WEEK)
    val leadingEmpty = (firstDay - Calendar.MONDAY + 7) % 7
    val displayedMonthIndex = displayedYear * 12 + displayedMonth
    val minimumMonthIndex = minimumCalendar?.let { it.get(Calendar.YEAR) * 12 + it.get(Calendar.MONTH) }
    val canGoPrevious = minimumMonthIndex == null || displayedMonthIndex > minimumMonthIndex

    androidx.compose.ui.window.Dialog(
        onDismissRequest = onDismiss,
        properties = androidx.compose.ui.window.DialogProperties(usePlatformDefaultWidth = false),
    ) {
        Box(
            modifier = Modifier
                .fillMaxSize()
                .background(Color(0x730F0F19)),
            contentAlignment = Alignment.Center,
        ) {
            Column(
                modifier = Modifier
                    .width(336.dp)
                    .clip(RoundedCornerShape(26.dp))
                    .background(cardSurfaceColor())
                    .padding(16.dp),
            ) {
                Row(
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.SpaceBetween,
                    modifier = Modifier.fillMaxWidth().height(34.dp),
                ) {
                    Text(
                        text = localized("Выберите дату", "Choose date", "Elige una fecha", "Datum auswählen"),
                        color = contentTextColor(),
                        fontFamily = Manrope,
                        fontWeight = FontWeight.W800,
                        fontSize = 18.sp,
                        lineHeight = 24.sp,
                        style = androidx.compose.ui.text.TextStyle(platformStyle = OdysseyNoFontPadding),
                    )
                    Box(
                        contentAlignment = Alignment.Center,
                        modifier = Modifier
                            .size(34.dp)
                            .clip(CircleShape)
                            .background(surfaceVariantColor())
                            .clickable(onClick = onDismiss),
                    ) {
                        Icon(Icons.Filled.Close, contentDescription = localized("Закрыть", "Close", "Cerrar", "Schließen"), tint = secondaryTextColor(), modifier = Modifier.size(16.dp))
                    }
                }
                Spacer(Modifier.height(14.dp))
                Row(
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.SpaceBetween,
                    modifier = Modifier.fillMaxWidth().height(32.dp),
                ) {
                    Box(
                        contentAlignment = Alignment.Center,
                        modifier = Modifier.size(32.dp).clip(CircleShape).clickable(enabled = canGoPrevious) {
                            if (displayedMonth == 0) {
                                displayedMonth = 11
                                displayedYear -= 1
                            } else {
                                displayedMonth -= 1
                            }
                        },
                    ) {
                        Icon(Icons.Outlined.ArrowBack, contentDescription = localized("Предыдущий месяц", "Previous month", "Mes anterior", "Vorheriger Monat"), tint = if (canGoPrevious) primaryColor() else secondaryTextColor(), modifier = Modifier.size(20.dp))
                    }
                    Text(
                        text = "${monthNames[displayedMonth]} $displayedYear",
                        color = contentTextColor(),
                        fontFamily = Manrope,
                        fontWeight = FontWeight.W800,
                        fontSize = 16.sp,
                        lineHeight = 22.sp,
                        style = androidx.compose.ui.text.TextStyle(platformStyle = OdysseyNoFontPadding),
                    )
                    Box(
                        contentAlignment = Alignment.Center,
                        modifier = Modifier.size(32.dp).clip(CircleShape).clickable {
                            if (displayedMonth == 11) {
                                displayedMonth = 0
                                displayedYear += 1
                            } else {
                                displayedMonth += 1
                            }
                        },
                    ) {
                        Icon(Icons.Outlined.ArrowBack, contentDescription = localized("Следующий месяц", "Next month", "Mes siguiente", "Nächster Monat"), tint = primaryColor(), modifier = Modifier.size(20.dp).graphicsLayer { rotationY = 180f })
                    }
                }
                Spacer(Modifier.height(16.dp))
                Row(modifier = Modifier.fillMaxWidth().height(24.dp)) {
                    weekDays.forEach { day ->
                        Text(
                            text = day,
                            color = secondaryTextColor(),
                            fontFamily = Manrope,
                            fontWeight = FontWeight.W800,
                            fontSize = 11.sp,
                            lineHeight = 16.sp,
                            textAlign = TextAlign.Center,
                            style = androidx.compose.ui.text.TextStyle(platformStyle = OdysseyNoFontPadding),
                            modifier = Modifier.weight(1f),
                        )
                    }
                }
                Spacer(Modifier.height(8.dp))
                Column(verticalArrangement = Arrangement.spacedBy(0.dp), modifier = Modifier.fillMaxWidth()) {
                    (0 until 6).forEach { week ->
                        Row(modifier = Modifier.fillMaxWidth().height(42.dp)) {
                            (0 until 7).forEach { weekday ->
                                val dayIndex = week * 7 + weekday - leadingEmpty + 1
                                val validDay = dayIndex in 1..daysInMonth
                                Box(contentAlignment = Alignment.Center, modifier = Modifier.weight(1f).fillMaxHeight()) {
                                    if (validDay) {
                                        val selected = dayIndex == selectedDay && displayedYear == selectedYear && displayedMonth == selectedMonth
                                        val dayCalendar = Calendar.getInstance().apply {
                                            clear()
                                            set(displayedYear, displayedMonth, dayIndex)
                                        }
                                        val selectable = minimumCalendar == null || !dayCalendar.before(minimumCalendar)
                                        Box(
                                            contentAlignment = Alignment.Center,
                                            modifier = Modifier
                                                .size(34.dp)
                                                .clip(CircleShape)
                                                .background(if (selected) primaryColor() else Color.Transparent)
                                                .clickable(enabled = selectable) {
                                                    selectedYear = displayedYear
                                                    selectedMonth = displayedMonth
                                                    selectedDay = dayIndex
                                                },
                                        ) {
                                            Text(
                                                text = dayIndex.toString(),
                                                color = when {
                                                    selected -> primaryContentColor()
                                                    selectable -> contentTextColor()
                                                    else -> secondaryTextColor().copy(alpha = 0.45f)
                                                },
                                                fontFamily = Manrope,
                                                fontWeight = if (selected) FontWeight.W800 else FontWeight.W600,
                                                fontSize = 14.sp,
                                                lineHeight = 18.sp,
                                                textAlign = TextAlign.Center,
                                                style = androidx.compose.ui.text.TextStyle(platformStyle = OdysseyNoFontPadding),
                                            )
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
                Spacer(Modifier.height(16.dp))
                Row(horizontalArrangement = Arrangement.spacedBy(11.dp), modifier = Modifier.fillMaxWidth().height(48.dp)) {
                    Box(
                        contentAlignment = Alignment.Center,
                        modifier = Modifier
                            .weight(1f)
                            .fillMaxHeight()
                            .clip(RoundedCornerShape(15.dp))
                            .background(cardSurfaceColor())
                            .border(1.dp, contentBorderColor(), RoundedCornerShape(15.dp))
                            .clickable(onClick = onDismiss),
                    ) {
                        Text(localized("Отмена", "Cancel", "Cancelar", "Abbrechen"), color = contentTextColor(), fontFamily = Manrope, fontWeight = FontWeight.W800, fontSize = 14.sp, style = androidx.compose.ui.text.TextStyle(platformStyle = OdysseyNoFontPadding))
                    }
                    Box(
                        contentAlignment = Alignment.Center,
                        modifier = Modifier
                            .weight(1.3f)
                            .fillMaxHeight()
                            .clip(RoundedCornerShape(15.dp))
                            .background(Brush.linearGradient(listOf(primaryColor(), Color(0xFF7D6CF0))))
                            .clickable {
                                val selectedCalendar = Calendar.getInstance().apply {
                                    clear()
                                    set(selectedYear, selectedMonth, selectedDay)
                                }
                                if (minimumCalendar == null || !selectedCalendar.before(minimumCalendar)) {
                                    onConfirm(accommodationDateIso(selectedYear, selectedMonth, selectedDay))
                                }
                            },
                    ) {
                        Text(localized("Готово", "Done", "Listo", "Fertig"), color = primaryContentColor(), fontFamily = Manrope, fontWeight = FontWeight.W800, fontSize = 14.sp, style = androidx.compose.ui.text.TextStyle(platformStyle = OdysseyNoFontPadding))
                    }
                }
            }
        }
    }
}

@Composable
@OptIn(ExperimentalMaterial3Api::class)
private fun TripRouteContent(tripId: String, overview: TripOverview, canEdit: Boolean = true, onRouteAdded: () -> Unit) {
    val language = LocalLanguage.current
    val cityCatalogContext = LocalContext.current
    val cityCatalogRepository = remember(cityCatalogContext) { CityCatalogRepository(cityCatalogContext.assets) }
    val hapticFeedback = LocalHapticFeedback.current
    val routeListState = rememberLazyListState()
    val routeCities = remember(overview.routeLegs) {
        overview.routeLegs
            .flatMap { listOf(it.from, it.to) }
            .filter(String::isNotBlank)
            .distinct()
    }
    var resolvedRouteFlags by remember { mutableStateOf<Map<String, String>>(emptyMap()) }
    var adding by remember { mutableStateOf(false) }
    var from by remember { mutableStateOf("") }
    var to by remember { mutableStateOf("") }
    var checkIn by remember { mutableStateOf("") }
    var checkOut by remember { mutableStateOf("") }
    var notes by remember { mutableStateOf("") }
    var mapsUrl by remember { mutableStateOf("") }
    var selectedDateIso by remember { mutableStateOf("") }
    var datePickerOpen by remember { mutableStateOf(false) }
    var editingLeg by remember { mutableStateOf<com.odyssey.travelplanner.data.RouteLeg?>(null) }
    var saving by remember { mutableStateOf(false) }
    var savingRouteOrder by remember { mutableStateOf(false) }
    var message by remember { mutableStateOf<String?>(null) }
    var actionMessage by remember { mutableStateOf<String?>(null) }
    var orderedRouteIds by remember(overview.routeLegs) { mutableStateOf(overview.routeLegs.map { it.dayId }) }
    var draggedRouteId by remember { mutableStateOf<String?>(null) }
    var dragOffsetPx by remember { mutableStateOf(0f) }
    var dragInitialOrder by remember { mutableStateOf<List<String>>(emptyList()) }
    val scope = rememberCoroutineScope()

    val displayedRouteLegs = orderedRouteIds.mapNotNull { id ->
        overview.routeLegs.firstOrNull { it.dayId == id }
    } + overview.routeLegs.filterNot { leg -> orderedRouteIds.contains(leg.dayId) }

    fun updateRouteDrag(dragAmount: Float) {
        val draggedId = draggedRouteId ?: return
        dragOffsetPx += dragAmount
        val draggedKey = "route:$draggedId"
        val draggedInfo = routeListState.layoutInfo.visibleItemsInfo.firstOrNull { it.key == draggedKey } ?: return
        val draggedCenter = draggedInfo.offset + draggedInfo.size / 2f + dragOffsetPx
        val viewport = routeListState.layoutInfo
        when {
            draggedCenter < viewport.viewportStartOffset + 80f -> scope.launch { routeListState.scrollBy(-24f) }
            draggedCenter > viewport.viewportEndOffset - 80f -> scope.launch { routeListState.scrollBy(24f) }
        }
        val currentIndex = orderedRouteIds.indexOf(draggedId)
        if (currentIndex < 0) return
        val targetIndex = when {
            dragAmount > 0f -> currentIndex + 1
            dragAmount < 0f -> currentIndex - 1
            else -> return
        }
        if (targetIndex !in orderedRouteIds.indices) return
        val targetId = orderedRouteIds[targetIndex]
        val targetInfo = routeListState.layoutInfo.visibleItemsInfo
            .firstOrNull { it.key == "route:$targetId" }
            ?: return
        val targetCenter = targetInfo.offset + targetInfo.size / 2f
        val crossedTarget = if (dragAmount > 0f) {
            draggedCenter > targetCenter
        } else {
            draggedCenter < targetCenter
        }
        if (!crossedTarget) return

        // Keep the card under the finger when its slot changes in the list.
        dragOffsetPx -= (targetInfo.offset - draggedInfo.offset).toFloat()
        orderedRouteIds = orderedRouteIds.toMutableList().apply {
            removeAt(currentIndex)
            add(targetIndex, draggedId)
        }
    }

    fun finishRouteDrag() {
        val draggedId = draggedRouteId
        val finalOrder = orderedRouteIds
        val changed = draggedId != null && finalOrder != dragInitialOrder
        draggedRouteId = null
        dragOffsetPx = 0f
        dragInitialOrder = emptyList()
        if (!changed) return

        scope.launch {
            savingRouteOrder = true
            runCatching {
                SupabaseTripRepository(SupabaseProvider.clientForCurrentAuthFlow())
                    .reorderRouteLegs(tripId, finalOrder)
            }.onSuccess {
                actionMessage = null
                onRouteAdded()
            }.onFailure {
                orderedRouteIds = overview.routeLegs.map { it.dayId }
                actionMessage = localizedFailure(language, it, localized(
                    language,
                    "Не удалось сохранить порядок маршрута. Проверьте интернет и повторите попытку.",
                    "Could not save the route order. Check your connection and try again.",
                    "No se pudo guardar el orden de la ruta. Comprueba la conexión e inténtalo de nuevo.",
                    "Die Reihenfolge der Route konnte nicht gespeichert werden. Prüfen Sie die Verbindung und versuchen Sie es erneut.",
                ))
            }
            savingRouteOrder = false
        }
    }

    LaunchedEffect(routeCities) {
        val unresolvedCities = routeCities.filter { cityFlag(it) == "📍" }
        resolvedRouteFlags = if (unresolvedCities.isEmpty()) {
            emptyMap()
        } else {
            cityCatalogRepository.findExact(unresolvedCities)
                .mapValues { (_, entry) -> countryFlag(entry.countryCode) ?: cityFlag(entry.russian) }
                .filterValues { it != "📍" }
        }
    }

    val cityCount = overview.overviewMapPoints
        .ifEmpty { overview.routeLegs.flatMap { listOf(it.from, it.to) } }
        .filter(String::isNotBlank)
        .distinctBy { cityFilterKey(it) }
        .size
    val tripDays = routeDurationDays(overview.dates)
    LazyColumn(
        contentPadding = androidx.compose.foundation.layout.PaddingValues(start = 20.dp, end = 20.dp, top = 18.dp, bottom = 112.dp),
        verticalArrangement = Arrangement.spacedBy(14.dp),
        state = routeListState,
        modifier = Modifier.fillMaxSize(),
    ) {
        item {
            Text(
                localizedRouteSummary(tripDays, cityCount, language),
                color = primaryColor(),
                fontFamily = Manrope,
                fontWeight = FontWeight.W800,
                fontSize = 11.sp,
            )
        }
        if (actionMessage != null) {
            item {
                Text(actionMessage!!, color = Color(0xFFE0524B), fontFamily = Manrope, fontWeight = FontWeight.W700, fontSize = 12.sp)
            }
        }
        if (overview.routeLegs.isEmpty()) {
            item {
                Text(localized("Переезды пока не добавлены", "No route legs added yet", "Aún no se han añadido trayectos", "Noch keine Etappen hinzugefügt"), color = secondaryTextColor(), fontFamily = Manrope, fontWeight = FontWeight.W700, fontSize = 14.sp, modifier = Modifier.padding(vertical = 20.dp))
            }
        } else {
            itemsIndexed(displayedRouteLegs, key = { _, leg -> "route:${leg.dayId}" }) { index, leg ->
                RouteLegCard(
                    leg = leg,
                    dayIndex = index,
                    tripDates = overview.dates,
                    resolvedCityFlags = resolvedRouteFlags,
                    canEdit = canEdit,
                    dragEnabled = canEdit && !adding && !savingRouteOrder,
                    isDragging = draggedRouteId == leg.dayId,
                    dragOffsetPx = if (draggedRouteId == leg.dayId) dragOffsetPx else 0f,
                    onDragStart = {
                        if (canEdit && !adding && !savingRouteOrder) {
                            draggedRouteId = leg.dayId
                            dragInitialOrder = orderedRouteIds
                            dragOffsetPx = 0f
                            hapticFeedback.performHapticFeedback(HapticFeedbackType.LongPress)
                        }
                    },
                    onDrag = ::updateRouteDrag,
                    onDragEnd = ::finishRouteDrag,
                    onEdit = {
                    if (canEdit) {
                        editingLeg = leg
                        from = leg.from
                        to = leg.to
                        checkIn = leg.checkIn
                        checkOut = leg.checkOut
                        notes = leg.notes
                        mapsUrl = leg.mapsUrl
                        selectedDateIso = routeEditorDateIso(leg.date, overview.dates, index, leg.dateDay, leg.dateMonth)
                        adding = true
                    }
                    },
                )
            }
        }
        if (canEdit) item {
            if (!adding) {
                Text(
                    localized("＋  Добавить день", "＋  Add day", "＋  Añadir día", "＋  Tag hinzufügen"),
                    color = primaryColor(),
                    fontFamily = Manrope,
                    fontWeight = FontWeight.W800,
                    fontSize = 14.sp,
                    textAlign = TextAlign.Center,
                    modifier = Modifier.fillMaxWidth().height(55.dp).clip(RoundedCornerShape(16.dp)).background(tintedSurfaceColor()).drawBehind {
                        drawRoundRect(
                            color = Color(0xFFD7D0FF),
                            cornerRadius = CornerRadius(16.dp.toPx()),
                            style = Stroke(width = 1.dp.toPx(), pathEffect = PathEffect.dashPathEffect(floatArrayOf(5.dp.toPx(), 4.dp.toPx()))),
                        )
                    }.clickable {
                        editingLeg = null
                        from = ""
                        to = ""
                        checkIn = ""
                        checkOut = ""
                        notes = ""
                        mapsUrl = ""
                        selectedDateIso = routeEditorDateIso("", overview.dates, overview.routeLegs.size, "", "")
                        adding = true
                    }.padding(top = 17.dp),
                )
            }
        }
    }
    if (canEdit && adding) {
        ModalBottomSheet(
            onDismissRequest = { adding = false; editingLeg = null; message = null },
            sheetState = rememberModalBottomSheetState(skipPartiallyExpanded = true),
            containerColor = cardSurfaceColor(),
        ) {
            RouteLegEditorSheet(
                from = from,
                to = to,
                date = selectedDateIso,
                checkIn = checkIn,
                checkOut = checkOut,
                mapsUrl = mapsUrl,
                saving = saving,
                message = message,
                onFromChange = { from = it },
                onToChange = { to = it },
                onDateClick = { datePickerOpen = true },
                onCheckInChange = { checkIn = it },
                onCheckOutChange = { checkOut = it },
                onMapsUrlChange = { mapsUrl = it },
                onCancel = { adding = false; editingLeg = null; message = null },
                canDelete = canEdit && editingLeg != null,
                onDelete = {
                    editingLeg?.let { leg ->
                        scope.launch {
                            saving = true
                            runCatching { SupabaseTripRepository(SupabaseProvider.clientForCurrentAuthFlow()).deleteTripItem(tripId, "days", leg.dayId) }
                                .onSuccess { adding = false; editingLeg = null; onRouteAdded() }
                                .onFailure { message = localizedFailure(language, it, localized(language, "Не удалось удалить день", "Could not delete day", "No se pudo eliminar el día", "Tag konnte nicht gelöscht werden")) }
                            saving = false
                        }
                    }
                },
                onSave = {
                    scope.launch {
                        saving = true
                        val dateValues = routeEditorDateValues(selectedDateIso, "", 0, language)
                        runCatching {
                            val repository = SupabaseTripRepository(SupabaseProvider.clientForCurrentAuthFlow())
                            editingLeg?.let {
                                repository.updateRouteLegDetails(
                                    id = tripId,
                                    dayId = it.dayId,
                                    from = from,
                                    to = to,
                                    checkIn = checkIn,
                                    checkOut = checkOut,
                                    notes = notes,
                                    mapsUrl = mapsUrl,
                                    date = selectedDateIso,
                                    dateDay = dateValues.day,
                                    dateMonth = dateValues.month,
                                    weekday = dateValues.weekday,
                                    distance = it.distance,
                                    travelTime = it.travelTime,
                                )
                            } ?: repository.addRouteLeg(
                                id = tripId,
                                from = from,
                                to = to,
                                checkIn = checkIn,
                                checkOut = checkOut,
                                notes = notes,
                                mapsUrl = mapsUrl,
                                date = selectedDateIso,
                                dateDay = dateValues.day,
                                dateMonth = dateValues.month,
                                weekday = dateValues.weekday,
                            )
                        }.onSuccess { adding = false; editingLeg = null; datePickerOpen = false; from = ""; to = ""; checkIn = ""; checkOut = ""; notes = ""; mapsUrl = ""; selectedDateIso = ""; onRouteAdded() }
                            .onFailure { message = localizedFailure(language, it, localized(language, "Не удалось сохранить переезд", "Could not save route leg", "No se pudo guardar el trayecto", "Etappe konnte nicht gespeichert werden")) }
                        saving = false
                    }
                },
            )
        }
    }
    if (canEdit && datePickerOpen) {
        AccommodationCalendarDialog(
            initialValue = selectedDateIso,
            onDismiss = { datePickerOpen = false },
            onConfirm = {
                selectedDateIso = it
                datePickerOpen = false
            },
        )
    }
}

@Composable
private fun RouteLegEditorSheet(
    from: String,
    to: String,
    date: String,
    checkIn: String,
    checkOut: String,
    mapsUrl: String,
    saving: Boolean,
    message: String?,
    onFromChange: (String) -> Unit,
    onToChange: (String) -> Unit,
    onDateClick: () -> Unit,
    onCheckInChange: (String) -> Unit,
    onCheckOutChange: (String) -> Unit,
    onMapsUrlChange: (String) -> Unit,
    onCancel: () -> Unit,
    canDelete: Boolean,
    onDelete: () -> Unit,
    onSave: () -> Unit,
) {
    val language = LocalLanguage.current
    var deleteDialogOpen by remember { mutableStateOf(false) }
    val displayedFrom = localizedCityName(from)
    val displayedTo = localizedCityName(to)
    var visibleFrom by remember(from, language) { mutableStateOf(displayedFrom) }
    var visibleTo by remember(to, language) { mutableStateOf(displayedTo) }
    val navigationBarInset = WindowInsets.navigationBars.asPaddingValues().calculateBottomPadding()
    Column(
        modifier = Modifier
            .fillMaxWidth()
            .verticalScroll(rememberScrollState())
            .imePadding()
            .padding(horizontal = 12.dp, vertical = 6.dp)
            .padding(bottom = navigationBarInset),
        verticalArrangement = Arrangement.spacedBy(11.dp),
    ) {
        Row(verticalAlignment = Alignment.CenterVertically) {
            Text(localized("День маршрута", "Route day", "Día de ruta", "Reisetag"), color = contentTextColor(), fontFamily = Manrope, fontWeight = FontWeight.W800, fontSize = 23.sp)
            Spacer(Modifier.weight(1f))
            Box(modifier = Modifier.size(37.dp).clip(CircleShape).background(secondarySurfaceColor()).clickable { onCancel() }, contentAlignment = Alignment.Center) {
                Icon(Icons.Filled.Close, contentDescription = localized("Закрыть", "Close", "Cerrar", "Schließen"), tint = secondaryTextColor(), modifier = Modifier.size(18.dp))
            }
        }
        Row(horizontalArrangement = Arrangement.spacedBy(12.dp)) {
            RouteEditorField(localized("Откуда", "From", "Desde", "Von"), visibleFrom, { visibleFrom = it; onFromChange(it) }, Modifier.weight(1f))
            RouteEditorField(localized("Куда", "To", "A", "Nach"), visibleTo, { visibleTo = it; onToChange(it) }, Modifier.weight(1f))
        }
        RouteEditorDateField(
            label = localized("Дата", "Date", "Fecha", "Datum"),
            value = routeEditorDateLabel(date, language),
            onClick = onDateClick,
            modifier = Modifier.fillMaxWidth(),
        )
        RouteEditorField(localized("Заселение до", "Check-in by", "Entrada antes de", "Check-in bis"), checkIn, onCheckInChange, Modifier.fillMaxWidth(), placeholder = "—")
        RouteEditorField(localized("Выселение до", "Check-out by", "Salida antes de", "Check-out bis"), checkOut, onCheckOutChange, Modifier.fillMaxWidth(), placeholder = "—")
        RouteEditorField(
            localized("Ссылка на карту", "Map link", "Enlace al mapa", "Kartenlink"),
            mapsUrl,
            onMapsUrlChange,
            Modifier.fillMaxWidth(),
            placeholder = "https://maps.app.goo.gl/...",
            includeFontPadding = true,
        )
        if (message != null) Text(message, color = Color(0xFFE0524B), fontFamily = Manrope, fontWeight = FontWeight.W700, fontSize = 12.sp)
        Row(horizontalArrangement = Arrangement.spacedBy(10.dp), modifier = Modifier.fillMaxWidth().padding(top = 2.dp, bottom = 8.dp)) {
            if (canDelete) {
                Box(modifier = Modifier.size(54.dp).clip(RoundedCornerShape(14.dp)).background(dangerSurfaceColor()).clickable(enabled = !saving) { deleteDialogOpen = true }, contentAlignment = Alignment.Center) {
                    Icon(Icons.Outlined.Delete, contentDescription = localized("Удалить день", "Delete day", "Eliminar día", "Tag löschen"), tint = Color(0xFFFF6B65), modifier = Modifier.size(22.dp))
                }
            }
            Button(onClick = onCancel, modifier = Modifier.height(54.dp).weight(1f), colors = ButtonDefaults.buttonColors(containerColor = cardSurfaceColor(), contentColor = contentTextColor()), shape = RoundedCornerShape(14.dp)) { Text(localized("Отмена", "Cancel", "Cancelar", "Abbrechen"), fontFamily = Manrope, fontWeight = FontWeight.W800) }
            Button(onClick = onSave, enabled = !saving, modifier = Modifier.height(54.dp).weight(1.25f), colors = ButtonDefaults.buttonColors(containerColor = primaryColor(), contentColor = primaryContentColor()), shape = RoundedCornerShape(14.dp)) { Text(if (saving) localized("Сохраняем…", "Saving…", "Guardando…", "Wird gespeichert…") else localized("Сохранить", "Save", "Guardar", "Speichern"), fontFamily = Manrope, fontWeight = FontWeight.W800) }
        }
    }
    if (deleteDialogOpen) {
        AlertDialog(
            onDismissRequest = { if (!saving) deleteDialogOpen = false },
            title = {
                Text(
                    localized("Удалить день маршрута?", "Delete route day?", "¿Eliminar día de ruta?", "Reisetag löschen?"),
                    fontFamily = Manrope,
                    fontWeight = FontWeight.W800,
                )
            },
            text = {
                Text(
                    localized(
                        "День маршрута будет удалён из поездки.",
                        "The route day will be removed from the trip.",
                        "El día de ruta se eliminará del viaje.",
                        "Der Reisetag wird aus der Reise entfernt.",
                    ),
                    fontFamily = Manrope,
                )
            },
            dismissButton = {
                TextButton(onClick = { deleteDialogOpen = false }, enabled = !saving) {
                    Text(localized("Отмена", "Cancel", "Cancelar", "Abbrechen"), fontFamily = Manrope, fontWeight = FontWeight.W800)
                }
            },
            confirmButton = {
                TextButton(
                    onClick = {
                        deleteDialogOpen = false
                        onDelete()
                    },
                    enabled = !saving,
                    colors = ButtonDefaults.textButtonColors(contentColor = Color(0xFFD9534F)),
                ) {
                    Text(localized("Удалить", "Delete", "Eliminar", "Löschen"), fontFamily = Manrope, fontWeight = FontWeight.W800)
                }
            },
        )
    }
}

