                    fontFamily = Manrope,
                    fontWeight = FontWeight.W700,
                    fontSize = 13.sp,
                    modifier = Modifier
                        .background(if (!tripDatesWeather) cardSurfaceColor() else Color.Transparent, RoundedCornerShape(9.dp))
